-- pregnancy week 1: Small, steady beginnings
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   1,
   'first',
   NULL,
   'Small, steady beginnings',
   '"Nothing here needs to feel different yet."',
   'Early pregnancy doesn''t call for a different way of eating — it calls for regular, ordinary meals, enough fluid, and a folic-acid supplement. Food supports the rest; it isn''t the whole job. If you already manage a condition — diabetes, thyroid disease, high blood pressure, anemia, epilepsy, or something else — continue your existing care plan, and check with your clinician about any pregnancy-specific adjustment to medication or supplements.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Begin", "notes": "Today: Nothing needs to change dramatically today. Regular meals, enough fluid, and the folic-acid supplement recommended for you are a steady place to begin. However today''s meals looked, eating something and drinking water is a good start.", "breakfast_a": "Vegetable poha with peanuts, side of curd. Swap: besan chilla with mint chutney.", "breakfast_b": null, "lunch_a": "Dal, roti, sabzi, and curd. Want more? Add extra dal/rajma or paneer — or a side of egg bhurji or a small piece of well-cooked chicken.", "lunch_b": null, "nourishment_break_a": "A banana with a small handful of peanuts. Nut-free option: roasted chana.", "nourishment_break_b": null, "dinner_a": "Khichdi with ghee and a vegetable of your choice.", "dinner_b": null, "still_hungry": "A glass of milk or buttermilk before bed."}, {"day_number": 2, "title": "Make it easier", "notes": "Today: Same idea as yesterday, with less effort behind it. Make it easier: Order in or reheat leftovers — refrigerate cooked food promptly, keep it chilled, and reheat until steaming hot rather than just warm.", "breakfast_a": "Plain curd with a banana, or a slice of toast with peanut butter.", "breakfast_b": null, "lunch_a": "Whatever the household is already eating — dal, rice, and sabzi is a workable meal on its own.", "lunch_b": null, "nourishment_break_a": "A glass of milk or buttermilk.", "nourishment_break_b": null, "dinner_a": "Simple khichdi, or roti with a vegetable — nothing separate needs to be cooked just for you.", "dinner_b": null, "still_hungry": "Roasted chana or a small handful of nuts."}, {"day_number": 3, "title": "Build", "notes": "Today: Today, a folate-rich food finds its way into one or two meals — leafy greens, moong dal, and citrus fruit all count. A folic-acid supplement is especially important before and during early pregnancy — continue the one recommended for you, and let everyday food provide the wider nourishment your body needs.", "breakfast_a": "Palak (spinach) paratha with curd.", "breakfast_b": null, "lunch_a": "Moong dal, rice, and a leafy vegetable sabzi like methi or palak.", "lunch_b": null, "nourishment_break_a": "A whole orange or mosambi. If you''d rather have juice, use a safely prepared or pasteurized option and keep the portion modest.", "nourishment_break_b": null, "dinner_a": "Dal and roti, with a vegetable of your choice — it doesn''t need to be leafy again tonight.", "dinner_b": null, "still_hungry": "A boiled egg adds protein and choline; curd or roasted chana are easy alternatives."}, {"day_number": 4, "title": "Adapt", "notes": "Today: If any food is starting to feel a little off, smaller and blander is a completely workable way to eat this week — even if nothing feels different for you yet. If today is harder: Curd rice at lunch, toast with egg or peanut butter later, and khichdi at dinner — small, plain, and spaced out. Keep water nearby and take small sips through the day. Relevant safety: If you can''t keep liquids down, are passing very little or very dark urine, feel faint or dizzy, or notice a racing heartbeat, contact your maternity team — these are dehydration warning signs, not something to wait out.", "breakfast_a": "Plain toast, a few soaked almonds, or a small bowl of mildly-spiced poha.", "breakfast_b": null, "lunch_a": "A smaller portion of dal-rice, or khichdi if a full lunch feels like a lot.", "lunch_b": null, "nourishment_break_a": "A few plain crackers or roasted makhana.", "nourishment_break_b": null, "dinner_a": "Curd rice, or a simple roti with a mild sabzi.", "dinner_b": null, "still_hungry": "A mild ginger drink or a plain dry snack may feel easier for some women."}, {"day_number": 5, "title": "Family table", "notes": "Today: Today''s meal is one the whole family can share — nothing separate to cook just for yourself. Make it easier: Ask for a smaller portion of the same meal rather than a separate plan.", "breakfast_a": "Whatever the household usually has — parathas, upma, or idli-sambar all work.", "breakfast_b": null, "lunch_a": "Eat the household meal. Include something sustaining — dal, rajma or chole, curd, paneer, egg, chicken, or a well-cooked lower-mercury fish — and fruit or vegetables where convenient.", "lunch_b": null, "nourishment_break_a": "A shared plate of roasted chana or fruit with everyone else.", "nourishment_break_b": null, "dinner_a": "Whatever''s already planned for the family — the same idea applies: something sustaining, plus fruit or vegetables where easy.", "dinner_b": null, "still_hungry": "An extra roti, or a glass of milk alongside the family meal."}, {"day_number": 6, "title": "Real life", "notes": "Today: Today is about what''s actually available — leftovers, ordering in, or a quick meal all work. When you can, round the day out with something sustaining — dal, curd, paneer, egg, chicken, fish, nuts, or roasted chana. Make it easier: This entire day is the shortcut — reheat leftovers until steaming hot, and avoid reheating the same portion more than once.", "breakfast_a": "Leftover roti or paratha from last night, or whatever''s fastest.", "breakfast_b": null, "lunch_a": "Order in, or reheat yesterday''s dal-rice — either way, something sustaining like dal, paneer, egg, chicken, or fish rounds out the plate.", "lunch_b": null, "nourishment_break_a": "A curd cup, roasted chana, or fruit — no preparation needed.", "nourishment_break_b": null, "dinner_a": "Same idea as lunch — leftovers, ordered food, or something simple like bread and eggs.", "dinner_b": null, "still_hungry": "A glass of milk, or a simple packaged snack with clearly labelled ingredients — some protein bars carry high caffeine or herbal additives that aren''t a good default in pregnancy."}, {"day_number": 7, "title": "Reset", "notes": "Today: A lower-effort day, built from what is already in the kitchen — and a good moment to prep something for the week ahead, only if you have the energy for it. If today is harder: Rest first — that''s completely fine today. Make it easier: If you have the energy, soak or cook a batch of dal or rajma for the coming week. If not, leave it for another day.", "breakfast_a": "Whatever''s in the fridge, built around something sustaining — eggs, dal, or paneer — with whatever vegetables and bread are on hand.", "breakfast_b": null, "lunch_a": "A simple, familiar meal using what''s already there — dal-rice or khichdi both work.", "lunch_b": null, "nourishment_break_a": "Fruit, nuts, or curd — whatever''s easiest to reach.", "nourishment_break_b": null, "dinner_a": "Khichdi, or a lentil/bean/chicken soup with toast.", "dinner_b": null, "still_hungry": "Add curd, a boiled egg, roasted chana, fruit with nuts, or another small bowl of dal-rice."}]'::jsonb,
   'Was there a meal or a day this week that felt easier than you expected? That''s worth noticing — it''s likely a version of eating you can return to.',
   'Next week continues gently — small, steady meals, without needing anything to feel different yet.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 9: Calcium, built in steadily
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   9,
   'first',
   NULL,
   'Calcium, built in steadily',
   '"A couple of dependable sources across the day, with prescribed supplements timed as advised."',
   'Calcium supports your bones and helps build your baby''s bones and teeth. Most pregnant adults aged 19-50 need about 1,000mg a day; pregnant teenagers need about 1,300mg. Milk, curd, paneer, and cheese can contribute, as can calcium-fortified plant milks, calcium-set tofu, and some plant foods. If you take prescribed calcium and iron supplements, follow your care team''s timing instructions and usually take them several hours apart. Ordinary meals don''t need to be organised around perfect nutrient separation. If you eat meat, fish, or eggs: Each day this week offers a non-vegetarian choice alongside the vegetarian one. Chicken, fish fillets, and eggs are good protein sources, but they''re not meaningful calcium contributors on their own — so wherever a meal swaps in one of these, a dairy, fortified-plant-milk, or plant calcium side stays alongside it, keeping your day''s calcium source in place. Egg yolk and lower-mercury oily fish do help with vitamin D (Day 4), and small fish eaten with their soft, edible bones are a genuine non-dairy calcium source in their own right (Day 6).',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: One or two dependable calcium sources are a practical starting point today — your total intake still depends on the food, portion, and any supplement prescribed to you. If this applies to you (high blood pressure): Compare labels where available, choose fresh or lower-sodium paneer and cheese, and follow any sodium guidance given by your maternity team.", "breakfast_a": "Ragi porridge made with milk or calcium-fortified plant milk.", "breakfast_b": "The same porridge, with a fully cooked egg alongside.", "lunch_a": "Roti, dal, and a cooked vegetable.", "lunch_b": "The same roti, dal, and vegetable, with a boiled egg or a portion of chicken curry (cooked through) added alongside — the dal remains part of the meal''s plant-based calcium contribution.", "nourishment_break_a": "Curd with fruit.", "nourishment_break_b": "Fruit with almonds and sesame seeds, or a small piece of til chikki.", "dinner_a": "Palak paneer or calcium-set tofu with roti.", "dinner_b": "Palak chicken (cooked through) with roti, plus a side of curd or a small glass of milk to keep today''s calcium source in place.", "still_hungry": "Fruit, toast, or another familiar snack."}, {"day_number": 2, "title": "Time your supplements, not your meals", "notes": "Today: If you take prescribed calcium and iron tablets, they commonly need to be taken several hours apart. Follow the timing given by your maternity team. You don''t need to separate every iron-containing food from every calcium-containing food in your ordinary meals. This week''s food doesn''t need any special separation — that''s really about prescribed supplements, and your care team''s instructions are the ones to follow there. If this applies to you (hypothyroidism (levothyroxine)): Calcium and iron supplements can reduce levothyroxine''s absorption. Take levothyroxine exactly as prescribed, and ask your doctor or pharmacist how to separate it from calcium, iron, and food — a four-hour gap from calcium or iron supplements is commonly advised. Pregnancy also needs timely thyroid monitoring, so don''t adjust your own dose. Source: NHS guidance on pregnancy and hypothyroidism.", "breakfast_a": "Oats with curd and fruit.", "breakfast_b": "The same oats with curd and fruit, with a fully cooked egg added alongside.", "lunch_a": "Sambar, rice, and a cooked vegetable.", "lunch_b": "The same sambar, rice, and vegetable, with a portion of fish curry (cooked through) added alongside.", "nourishment_break_a": "Fruit with a few nuts.", "nourishment_break_b": "Curd with fruit, or calcium-fortified plant yogurt with fruit.", "dinner_a": "A paneer or tofu-and-vegetable roti wrap.", "dinner_b": "A chicken-and-vegetable roti wrap (cooked through), with a side of curd or a small glass of milk for today''s calcium.", "still_hungry": "A hunger-led snack — whatever you''d normally reach for."}, {"day_number": 3, "title": "Sesame and ragi", "notes": "Today: Ragi and sesame are two of the better plant-based calcium contributors in an Indian kitchen — worth knowing about, without needing to appear at every meal. Sesame and ragi genuinely contribute calcium — worth knowing about, not something to build every meal around.", "breakfast_a": "Ragi dosa with chutney.", "breakfast_b": "The same ragi dosa with chutney, with a fully cooked egg alongside.", "lunch_a": "Rajma-and-vegetable roti wrap, or dal with rice and vegetables.", "lunch_b": "A chicken-and-vegetable roti wrap (cooked through), with a side of curd for today''s calcium.", "nourishment_break_a": "Tahini on toast.", "nourishment_break_b": "Til chutney with a small snack.", "dinner_a": "Tofu-and-vegetable curry with roti.", "dinner_b": "A fish curry (cooked through) with roti, plus a side of curd or paneer to keep today''s calcium source in place.", "still_hungry": "A regular hunger-led snack."}, {"day_number": 4, "title": "Vitamin D and calcium", "notes": "Today: Vitamin D helps your body absorb calcium — worth knowing where it comes from, even though there''s no single simple way to guarantee enough of it. Vitamin D helps the body absorb calcium. Food sources include fortified milk or plant milk, egg yolk, and fully cooked lower-mercury oily fish where suitable. Safe time outdoors has many benefits, but sunlight doesn''t provide a predictable dose for everyone — skin tone, season, clothing, and where you live all affect it. Ask your maternity care team whether your prenatal supplement provides enough vitamin D, or whether testing is right for you.", "breakfast_a": "Vegetable poha.", "breakfast_b": "Vegetable poha with a fully cooked egg alongside — egg yolk is a genuine vitamin D source.", "lunch_a": "Roti, dal, and a cooked vegetable.", "lunch_b": "The same roti, dal, and vegetable, with a portion of chicken curry (cooked through) added alongside.", "nourishment_break_a": "Fruit with a few nuts.", "nourishment_break_b": "Curd with fruit, or calcium-fortified plant yogurt with fruit.", "dinner_a": "A paneer curry with rice or roti.", "dinner_b": "Fully cooked lower-mercury fish with rice and vegetables, with curd or calcium-fortified plant milk alongside — the fish contributes vitamin D, while the side keeps the meal''s calcium purpose.", "still_hungry": "Fruit, or a familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: Calcium-friendly choices are still findable when you''re not cooking yourself. Make it easier: Carry cheese, paneer, boiled eggs, and other perishable foods in an insulated bag with an ice pack, and eat them promptly.", "breakfast_a": "Idli with sambar, plus a small cup of milk or calcium-fortified plant milk if desired. Chai can still fit within your daily caffeine limit, but it isn''t really a calcium serving on its own.", "breakfast_b": "The same idli-sambar, with a boiled egg alongside if it''s available.", "lunch_a": "A paneer or tofu wrap, or a simple curd-based raita alongside whatever you''re having.", "lunch_b": "A chicken or egg wrap (cooked through), with the same curd-based raita alongside to keep today''s calcium source in place.", "nourishment_break_a": "A slice of cheese.", "nourishment_break_b": "Roasted til chikki.", "dinner_a": "A shared family meal — whatever''s on the table.", "dinner_b": "The same meal, with a small glass of milk or curd added on the side if you''d like an extra calcium boost.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "When dairy doesn''t appeal", "notes": "Today: If dairy doesn''t sit well for you — whether it''s taste, tolerance, or just not appealing right now — a planned approach can still meet your calcium needs. If you avoid dairy, check labels — plant milks and tofu vary a lot in calcium content. A dairy-free diet, with or without meat, fish, or eggs, can meet your calcium needs; it doesn''t automatically require dairy.", "breakfast_a": "Ragi porridge made with calcium-fortified plant milk — shake the carton and check the label, since products vary.", "breakfast_b": "The same porridge, with a fully cooked egg alongside.", "lunch_a": "Calcium-set tofu and vegetable stir-fry with roti.", "lunch_b": "Cooked sardines or another small fish with soft, edible bones — a genuine non-dairy calcium source — with rice and vegetables.", "nourishment_break_a": "Tahini on toast.", "nourishment_break_b": "Fruit with almonds.", "dinner_a": "Chickpea-and-vegetable curry with roti.", "dinner_b": "A chicken-and-chickpea vegetable curry, cooked through, with roti.", "still_hungry": "Fortified plant milk, if that suits you, or a regular snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of small calcium habits is worth a quick look back — and a good moment to ask your care team about your own prescribed dose and timing, if you haven''t already. Calcium-rich foods support your everyday intake, but a prescribed calcium supplement serves a separate antenatal purpose — India''s national guidelines usually include it alongside iron and folic acid, from around the second trimester. Don''t stop or replace a prescribed supplement with food unless your care team advises it; they''ll guide you on your own dose and timing.", "breakfast_a": "Whichever breakfast felt best this week, vegetarian or not — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A glass of milk, or another familiar snack."}]'::jsonb,
   'Which calcium-friendly habit felt easiest to keep up this week — a food, a supplement-timing change, or just noticing what was already in your usual meals?',
   'Next week, we''ll look at folate-rich foods — and why they support, but don''t replace, recommended folic-acid supplementation.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 10: Folate-rich foods, alongside your tablet
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   10,
   'first',
   NULL,
   'Folate-rich foods, alongside your tablet',
   '"Everyday greens, lentils, and citrus support your folate — they don''t replace your prescribed folic acid."',
   'Folate (vitamin B9) supports cell division and your baby''s earliest development. Getting enough folic acid before conception and during early pregnancy reduces the risk of neural tube defects — this is why it matters especially early, often before many people even know they''re pregnant. ICMR-NIN''s 2020 guidelines set the RDA for pregnant women at 570mcg of dietary folate a day, and India''s national guidance recommends a standalone 400mcg folic acid tablet from before conception through the first trimester, moving to a combined iron-folic-acid (IFA) tablet from the second trimester onward. Leafy greens (spinach, methi, amaranth), lentils and legumes (moong, chana, rajma, lobia), and citrus fruits are the main food sources. Food folate is real and worth eating regularly, but it''s less reliably absorbed than the folic acid in your tablet, and easily reduced by cooking — so it supports, rather than replaces, whatever''s been prescribed to you. If you eat meat, fish, or eggs: Folate itself is overwhelmingly a plant-food story this week — leafy greens, lentils, and citrus carry far more of it than meat, fish, or eggs do. So most of this week''s non-vegetarian choices add protein and variety alongside the folate-rich part of the meal, rather than replacing it. The one real exception is liver, which is unusually rich in folate but also concentrated in vitamin A (retinol) — pregnancy guidance is to skip it, not add it, since too much preformed vitamin A carries its own risk. Eggs, dairy, meat, and fish matter for a different reason this week: they''re where vitamin B12 mainly comes from, which is worth knowing about on Day 4.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: A couple of folate-rich foods across the day — a leafy green, a lentil, or a citrus fruit — is a reasonable place to start. Your prescribed folic acid or IFA tablet is still doing a separate, more concentrated job.", "breakfast_a": "Vegetable poha with peas, or a moong dal chilla.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Roti, palak (spinach) dal, and a cooked vegetable.", "lunch_b": "The same roti, palak dal, and vegetable, with a portion of chicken curry (cooked through) added alongside — the palak dal remains a real folate contributor either way.", "nourishment_break_a": "An orange or sweet lime (mosambi).", "nourishment_break_b": "A handful of roasted chana or peanuts.", "dinner_a": "Rajma or chana curry with rice.", "dinner_b": "Egg curry or chicken curry (cooked through) with rice, plus a side of sautéed greens to keep today''s folate source in place.", "still_hungry": "Fruit, toast, or another familiar snack."}, {"day_number": 2, "title": "Food folate isn''t the same as your tablet", "notes": "Today: The folate in food and the folic acid in your tablet aren''t quite the same thing. Folic acid is the form used in the research behind the neural-tube-defect guidance, and it''s absorbed more reliably than the folate naturally found in food. Cooking matters too, though not dramatically: folate can be reduced by prolonged cooking and by discarding cooking water. Cook greens only as long as needed, and when preparing dal or legumes, keeping the cooking liquid in the dish helps retain what has moved into the water. Cooked foods still count — there''s no need to chase perfect nutrient retention. Your prescribed folic acid or IFA tablet is doing a job food alone can''t fully guarantee, especially this early in pregnancy — cooking method is a nice-to-know, not something to be strict about. If this applies to you (pre-existing type 1 or type 2 diabetes): If you were living with diabetes before this pregnancy, guidelines often recommend a higher, prescription-strength folic acid dose (5mg a day) rather than the standard amount — ideally started before conception, reflecting a higher baseline risk of neural tube defects. This is a consensus recommendation, not something to arrange yourself: ask your doctor whether it applies to you. If you were diagnosed with gestational diabetes during this pregnancy rather than beforehand, this particular higher-dose guidance doesn''t apply the same way, since it''s specifically about the very earliest weeks of pregnancy. Source: NICE guidance on diabetes and maternal nutrition in pregnancy (NG247).", "breakfast_a": "Methi paratha cooked normally on a tawa, with curd or fruit alongside.", "breakfast_b": "The same, with a boiled egg (cooked through) on the side.", "lunch_a": "Moong dal, rice, and a lightly cooked (not over-boiled) green vegetable.", "lunch_b": "A fish curry (cooked through), rice, and the same lightly cooked green vegetable.", "nourishment_break_a": "An orange, or a small bowl of papaya.", "nourishment_break_b": "Roasted peanuts or chana.", "dinner_a": "Chana or rajma curry with roti.", "dinner_b": "Chicken curry (cooked through) with roti, plus a side of dal to keep today''s folate source in place.", "still_hungry": "A hunger-led snack — whatever you''d normally reach for."}, {"day_number": 3, "title": "Greens and dals, the everyday way", "notes": "Today: Methi, palak, chana, and moong are already folate-rich staples in most Indian kitchens — this day is about noticing what''s already there, not adding anything unusual. None of this needs to be a separate ''folate meal'' — it''s the same dal and sabzi most households already cook.", "breakfast_a": "Palak (spinach) and moong dal cheela.", "breakfast_b": "The same cheela, with a boiled egg (cooked through) on the side.", "lunch_a": "Chana dal, rice, and a methi or palak sabzi.", "lunch_b": "A chicken-and-vegetable curry (cooked through) with rice, plus the same methi or palak sabzi.", "nourishment_break_a": "Roasted chana or peanuts.", "nourishment_break_b": "An orange or a small bowl of papaya.", "dinner_a": "Rajma or lobia (black-eyed peas) curry with roti.", "dinner_b": "A fish curry (cooked through) with roti, plus a side of dal to keep today''s folate source in place.", "still_hungry": "A regular hunger-led snack."}, {"day_number": 4, "title": "Folate and vitamin B12 — a package deal", "notes": "Today: Folate and vitamin B12 both support healthy blood formation and your baby''s development. Large amounts of supplemental folic acid can sometimes correct the anaemia caused by B12 deficiency without treating the underlying nerve damage. This is not a reason to reduce or stop prescribed folic acid. It is simply why adequate B12 deserves attention, particularly if you eat little or no dairy, eggs, meat, or fish. B12 comes mainly from animal foods and is essentially absent from unfortified plant foods, so vegetarian and vegan mothers are genuinely at higher risk of falling short. If you eat little to no dairy, eggs, meat, or fish, ask your maternity team whether your prenatal supplement includes enough B12, or whether it''s worth checking directly — this isn''t something food alone can reliably fix on a fully plant-based diet.", "breakfast_a": "Curd with an orange, mosambi, or fully ripe papaya.", "breakfast_b": "The same, with a boiled egg (cooked through) on the side.", "lunch_a": "Paneer-and-vegetable curry with a side of palak, methi, or dal.", "lunch_b": "A fish or chicken curry (cooked through) with the same palak, methi, or dal side.", "nourishment_break_a": "A small glass of milk or fortified plant milk (check the label — some fortified plant milks add B12).", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "A paneer or curd-based curry with chana, peas, or greens included.", "dinner_b": "A fish or egg curry with a small dal or cooked-green side.", "still_hungry": "Fruit, or a familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: Folate-friendly choices are still findable when you''re not cooking yourself. Make it easier: Carry roasted chana, peanuts, or a peeled orange for a folate-friendly snack that travels easily. If you''re carrying a boiled egg, keep it in an insulated bag with an ice pack, same as any perishable food.", "breakfast_a": "A dal-based breakfast (like a dal chilla) or sambar with idli, plus a whole orange or mosambi, or sealed pasteurized juice if that''s the practical option.", "breakfast_b": "The same, with a boiled egg alongside if it''s available.", "lunch_a": "A dal or rajma-based thali item, or a simple sabzi with rice.", "lunch_b": "A chicken or egg dish (cooked through), with the same dal or sabzi alongside.", "nourishment_break_a": "A whole orange or banana carried with you.", "nourishment_break_b": "Roasted chana or peanuts carried with you.", "dinner_a": "A shared family meal — whatever''s on the table.", "dinner_b": "The same meal, with an extra spoon of dal or a side of greens added if you''d like a folate boost.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "When greens don''t appeal", "notes": "Today: If leafy greens feel impossible right now — taste, nausea, or just not appealing — lentils, legumes, and citrus fruit can carry a good share of your folate without needing a single spinach leaf. Greens are a good source, not the only one. Lentils, legumes, and citrus fruit can genuinely carry this day''s folate without them.", "breakfast_a": "A moong dal chilla, or a citrus fruit with breakfast.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma or chana curry with rice.", "lunch_b": "A chicken curry (cooked through) with rice, plus a side of rajma or chana to keep today''s folate source in place.", "nourishment_break_a": "An orange or a small bowl of papaya.", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "Lobia (black-eyed peas) or moong dal curry with roti.", "dinner_b": "A fish curry (cooked through) with roti, plus a side of dal to keep today''s folate source in place.", "still_hungry": "Fortified cereal or bread, if that suits you, or a regular snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of small folate habits is worth a quick look back — and a good reminder that your prescribed folic acid or IFA tablet is still doing its own job underneath all of it. Folate-rich foods support your everyday intake, but your prescribed folic acid or IFA tablet serves a separate, more concentrated purpose — especially in these very early weeks. Don''t stop or replace it with food unless your care team advises it.", "breakfast_a": "Whichever breakfast felt best this week, vegetarian or not — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A piece of fruit, or another familiar snack."}]'::jsonb,
   'Which folate-friendly habit felt easiest to keep up this week — a food, a cooking-method change, or just noticing what was already in your usual dal and sabzi?',
   'Next week, we''ll look at iron-rich foods — including why pairing them with vitamin C helps, and why tea or coffee too close to a meal can work against you.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
