-- pregnancy week 13: Healthy fats, without the fear
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   13,
   'first',
   NULL,
   'Healthy fats, without the fear',
   '"Some fat every day supports your baby''s brain — the type matters more than cutting it out."',
   'Fat should not be eliminated from pregnancy meals. It helps build your baby''s brain and nervous system, and carries fat-soluble vitamins A, D, E, and K that your body can''t absorb well without it. The practical goal is moderate cooking fat, a greater emphasis on unsaturated-fat foods like nuts, seeds, and lower-mercury fish, and avoiding trans fat — not adding extra ghee or oil simply because you''re pregnant. DHA, a specific omega-3 fat, is especially important for your baby''s brain and eye development, and lower-mercury fatty fish provides it directly. Ghee, nuts, seeds, and cooking oil all have a place — the type and amount matter more than avoiding fat altogether. If you eat meat, fish, or eggs: Fatty fish is the most direct source of DHA this week — walnuts, flaxseed, and chia give a related plant omega-3 (ALA), but the body converts only a small fraction of that into DHA. Eggs contain a modest amount of DHA too. If you don''t eat fish or eggs, that''s not a dead end — an algae-based DHA supplement is a real option worth asking your care team about, since it''s where fish get their own DHA from in the first place. A note on how much fish: If you eat fish, aim for variety and choose lower-mercury options. Across the week, use the fish alternatives for about two or three meals rather than selecting fish every day; choose egg or chicken for the other non-vegetarian alternatives unless your maternity team advises differently.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: A little fat at most meals — ghee, oil, nuts, or seeds — supports your baby''s brain development and helps you absorb some vitamins. Pregnancy isn''t a time to cut fat out; it''s about choosing it thoughtfully most days.", "breakfast_a": "Vegetable poha or upma cooked in a little oil or ghee, with a few nuts on the side.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Roti or rice, dal, and a vegetable cooked with a little oil or ghee.", "lunch_b": "The same, with a chicken curry (cooked through) added alongside.", "nourishment_break_a": "A small handful of walnuts or almonds.", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "A dal or vegetable curry with a little ghee stirred through, and roti.", "dinner_b": "A fish curry (cooked through) with roti.", "still_hungry": "Fruit, a few nuts, or another familiar snack."}, {"day_number": 2, "title": "Not all fat is the same — and cutting it isn''t the answer", "notes": "Today: Fat is essential this trimester — it helps build your baby''s brain and nervous system, and carries vitamins A, D, E, and K, which your body can''t absorb well without it. Cutting fat out isn''t the answer, but that doesn''t mean unlimited is the goal either: the practical aim is a moderate amount of cooking oil or ghee, suited to your overall diet, with a greater emphasis on unsaturated-fat foods such as nuts, seeds, suitable vegetable oils, and lower-mercury fish, and less reliance on regularly fried or heavily processed food. This isn''t permission to eat unlimited fried food either — the goal is an ordinary, unafraid amount of the everyday fats you already cook with, leaning toward nuts, seeds, and fish where you can, and keeping deep-fried snacks as an occasional treat rather than a daily habit.", "breakfast_a": "Ragi or oats porridge with a few walnuts or a spoon of flaxseed stirred in.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma or chana curry with rice, cooked in a little oil as usual.", "lunch_b": "A chicken curry (cooked through) with rice.", "nourishment_break_a": "A small handful of mixed nuts and seeds.", "nourishment_break_b": "Roasted peanuts or chana.", "dinner_a": "A vegetable curry with roti, using your usual cooking oil or ghee.", "dinner_b": "An egg curry (cooked through) with roti.", "still_hungry": "A hunger-led snack — whatever you''d normally reach for."}, {"day_number": 3, "title": "Ghee, nuts, and seeds — the everyday way", "notes": "Today: Ghee, til (sesame), flaxseed (alsi), and walnuts (akhrot) are already familiar fat sources in most Indian kitchens — a sensible, ordinary amount of each is genuinely useful, not something to load up on or avoid. None of this needs to be a large or special serving. Small amounts are sufficient; ghee is optional, and more is not automatically better.", "breakfast_a": "Paratha made with a little ghee, with curd.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Dal tempered with ghee, rice, and a vegetable.", "lunch_b": "A chicken curry (cooked through) with rice and a vegetable.", "nourishment_break_a": "A small piece of til (sesame) or flaxseed chikki, or a few walnuts.", "nourishment_break_b": "Roasted peanuts.", "dinner_a": "A vegetable curry with a little ghee, and roti.", "dinner_b": "A chicken curry (cooked through) with roti.", "still_hungry": "A regular hunger-led snack."}, {"day_number": 4, "title": "Where fish genuinely helps", "notes": "Today: DHA is an omega-3 fat involved in your baby''s brain and eye development, and fatty fish provides it directly. Walnuts, flaxseed, and chia contain a related plant omega-3 (ALA), but the body converts only a small fraction of it into DHA — often well under 10%. If you eat fish, this is where it can provide DHA directly; if you don''t, an algae-based DHA supplement (a real, vegetarian and vegan-friendly source, since fish get their own DHA from algae in the first place) is worth asking your care team about. Choose lower-mercury fish and cook it fully, same as every week — this doesn''t change for DHA specifically. If this applies to you (high blood pressure): Don''t use fish-oil or omega-3 supplements as a replacement for medication or a preventive plan prescribed by your maternity team. Ask before starting any supplement, especially if you take medicines that affect bleeding. Source: general antenatal supplement-safety guidance.", "breakfast_a": "Vegetable upma or poha.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside — egg yolk carries a modest amount of DHA too.", "lunch_a": "Rajma or chana curry with rice and a vegetable.", "lunch_b": "A fatty fish curry (cooked through) — such as sardines, or locally identified small mackerel/bangda (not king mackerel) — with rice.", "nourishment_break_a": "A small handful of walnuts, or flaxseed sprinkled on fruit.", "nourishment_break_b": "Roasted peanuts or chana.", "dinner_a": "A dal or vegetable curry with roti.", "dinner_b": "An egg or chicken curry (cooked through) with roti.", "still_hungry": "Fruit, or a familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: Healthy-fat choices are still findable when you''re not cooking yourself — and an occasional fried snack away from home isn''t something to worry over. Make it easier: If a meal out turns out to be fried or oilier than usual, that''s fine as an occasional thing — there''s no need to compensate at the next meal or feel like the day is ruined.", "breakfast_a": "Idli or dosa with a light drizzle of oil, plus curd.", "breakfast_b": "The same, with a boiled egg alongside if it''s available.", "lunch_a": "A dal or sabzi-based thali item with rice or roti.", "lunch_b": "A chicken or fish dish (cooked through), with the same dal or sabzi alongside.", "nourishment_break_a": "Roasted peanuts, chana, or a small handful of nuts carried with you.", "nourishment_break_b": "A piece of fruit.", "dinner_a": "A shared family meal — whatever''s on the table.", "dinner_b": "The same meal, with a few extra nuts or seeds if you''d like a fat-source boost.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "When everyone says ''eat more ghee for the baby''", "notes": "Today: Ghee, nuts, and dry fruits carry real, well-meaning tradition behind them — but more isn''t automatically better for your baby''s brain or birth weight. A sensible, ordinary amount most days does the job; there''s no evidence that eating large quantities speeds up development or guarantees a bigger, healthier baby. It''s completely reasonable to gently say ''this is enough for me today'' to a well-meaning family member — eating more ghee or dry fruits than you want isn''t required to nourish your baby well, and a very large intake can just mean more calories than you actually need right now.", "breakfast_a": "Your usual breakfast, with the usual amount of ghee or oil — no need to add extra.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Dal and a vegetable with rice or roti, cooked as you normally would.", "lunch_b": "A chicken or fish curry (cooked through) with rice or roti.", "nourishment_break_a": "A small, ordinary handful of nuts or dry fruits — not a large bowlful.", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "A vegetable curry with roti, your usual amount of oil or ghee.", "dinner_b": "A chicken curry (cooked through) with roti.", "still_hungry": "Fruit, or a familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of small fat habits is worth a quick look back — and a fitting close to this First Trimester nourishment journey through calcium, folate, iron, protein, and now fat. Fat isn''t a nutrient to fear in pregnancy — an ordinary, everyday amount, leaning toward nuts, seeds, and fish where you can, genuinely supports your baby''s development. If you don''t eat fish and want to be sure about DHA specifically, an algae-based supplement is a real option worth raising with your care team.", "breakfast_a": "Whichever breakfast felt best this week, vegetarian or not — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which fat-related habit felt easiest to notice this week — choosing ghee or oil without guilt, adding a few nuts or seeds, or gently saying ''enough'' to a well-meaning push for more?',
   'This closes our First Trimester nourishment journey. As you move into the Second Trimester, we''ll pick up with new themes suited to this next stage — for now, the calcium, folate, iron, protein, and fat habits from these seven weeks are worth carrying forward.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 14: Eating for one and a bit, not two
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   14,
   'second',
   NULL,
   'Eating for one and a bit, not two',
   '"A modest addition, not a doubling — the Second Trimester''s extra energy need is smaller than most people think."',
   'Your energy needs shift a little as you enter the Second Trimester. ICMR-NIN''s 2024 dietary guidelines use roughly 350 additional kcal a day as a general reference for a sedentary woman across the second and third trimesters (a separate, higher figure applies specifically to undernourished mothers, which is for your care team to assess, not something to work out yourself) — individual needs still vary with body size, activity, appetite, and your care team''s own guidance for you. In practice, this may look like one nourishing snack or two smaller additions distributed across the day — not a second full meal, and not extra food at every meal. ''Eating for two'' is a common phrase, but not an accurate description of what your body actually needs right now. If you eat meat, fish, or eggs: This week is not about a nutrient found only in meat, fish, or eggs — the modest increase can come from familiar foods whichever way you eat. Where fish is offered, keep it to about two or three meals across the week; egg or chicken cover the other non-vegetarian choices. A note on how these choices work: The options below show different places across the day where a modest addition may fit — they''re alternatives, not instructions to add extra food at every meal. Appetite, your usual intake, and your maternity team''s growth guidance still matter most.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: The second trimester brings a modest increase in energy needs — often met through one nourishing snack or two smaller additions across the day. Today''s nourishment break shows one place that increase may fit.", "breakfast_a": "Vegetable poha with peanuts.", "breakfast_b": "Vegetable poha with a fully cooked egg.", "lunch_a": "Dal, roti, rice, and a cooked vegetable.", "lunch_b": "Chicken curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "A glass of milk with a small handful of nuts — a reasonable place for today''s modest addition.", "nourishment_break_b": "Curd with fruit and a few nuts.", "dinner_a": "Rajma with rice and a cooked vegetable.", "dinner_b": "Fish curry (cooked through) with rice and a cooked vegetable.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "You''re not eating for two", "notes": "Today: ''Eating for two'' doesn''t mean doubling your portions. Both eating much less than you need and substantially more than you need can affect pregnancy health, which is why your maternity team tracks your growth and weight over time rather than a fixed number. This is guidance, not a reason to restrict food, count every calorie, or feel guilty. If you notice yourself eating well past comfortable fullness because you feel you ''should'' for the baby, that''s worth softening, not pushing through. If this applies to you (gestational diabetes): If you have diabetes or gestational diabetes, both the type and portion of any additional food matter. Choose additions that fit the carbohydrate portions, meal timing, and glucose targets given by your care team — foods containing protein, fibre, or vegetables may be useful choices within that plan. Source: general nutrition guidance for diabetes and gestational diabetes in pregnancy.", "breakfast_a": "Besan (chickpea flour) chilla with a side of curd.", "breakfast_b": "Besan chilla with a fully cooked egg alongside.", "lunch_a": "Chana dal, rice, and a cooked vegetable.", "lunch_b": "Chicken curry (cooked through), rice, and a cooked vegetable.", "nourishment_break_a": "Fruit with a small handful of nuts — a reasonable everyday portion, not a doubled one.", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "A vegetable curry with roti, in your usual portion.", "dinner_b": "An egg curry (cooked through) with roti, in your usual portion.", "still_hungry": "A hunger-led snack."}, {"day_number": 3, "title": "A little more, not a lot more", "notes": "Today: What might a modest, ordinary addition actually look like this trimester? Something small and familiar — not a separate project. A slightly fuller bowl of dal, an extra piece of fruit, or a small handful of nuts are realistic, everyday-sized examples — nothing needs to be a special or separate addition.", "breakfast_a": "Vegetable upma with a side of curd.", "breakfast_b": "Vegetable upma with a fully cooked egg.", "lunch_a": "Dal, roti, and a cooked vegetable, with a slightly fuller bowl of dal than usual.", "lunch_b": "Chicken curry (cooked through), roti, and a cooked vegetable.", "nourishment_break_a": "A banana with a small handful of nuts.", "nourishment_break_b": "Curd with fruit.", "dinner_a": "Palak paneer or tofu curry with roti.", "dinner_b": "Egg curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Make the little bit extra count", "notes": "Today: Since any extra is modest, it''s worth being something that also carries protein, fibre, or a nutrient this trimester needs — rather than a food that contributes fewer of the nutrients being emphasized this week. This isn''t about cutting out a sweet or fried treat entirely — it''s just that a nutrient-carrying addition does more for you and your baby than a food that contributes fewer of the nutrients being emphasized this week.", "breakfast_a": "Ragi porridge with a spoon of nuts or seeds.", "breakfast_b": "Ragi porridge with a fully cooked egg.", "lunch_a": "Rajma, rice, and a cooked vegetable.", "lunch_b": "Chicken curry (cooked through), rice, and a cooked vegetable.", "nourishment_break_a": "Curd with fruit — a good place for a nutrient-carrying addition, rather than packaged biscuits or namkeen.", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "Chana dal with roti and a cooked vegetable.", "dinner_b": "Egg curry (cooked through) with roti and a cooked vegetable.", "still_hungry": "Fruit, or a familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: The same idea still applies away from home — an ordinary meal, with room for one small addition if you''d like it. Make it easier: If a meal out is bigger than your usual portion, that''s fine as an occasional thing — there''s no need to finish it out of a sense that pregnancy means eating everything on the plate.", "breakfast_a": "Idli with sambar and a side of curd.", "breakfast_b": "Idli with sambar and a fully cooked egg alongside.", "lunch_a": "A dal or sabzi-based thali item with rice or roti.", "lunch_b": "A chicken or fish dish (cooked through), with the same dal or sabzi alongside.", "nourishment_break_a": "Roasted chana or peanuts carried with you — an easy place for today''s small addition.", "nourishment_break_b": "A piece of fruit.", "dinner_a": "A shared family meal — your usual portion.", "dinner_b": "The same meal, with a chicken or egg dish (cooked through) alongside.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "If you''re worried about gaining ''too much''", "notes": "Today: Appetite may increase during the Second Trimester, but experiences vary — some mothers still have nausea, reflux, early fullness, or a limited appetite, and that isn''t a sign anything is wrong either. Try not to intentionally skip or shrink meals out of weight-gain fear; equally, you don''t need to force food past comfortable fullness. If weight-gain worry is heavy or persistent, or if you notice yourself regularly skipping meals or feeling anxious about eating, tell your care team — this is a genuine, common concern worth talking through, not something to manage alone through restriction.", "breakfast_a": "Vegetable poha, in a portion that feels comfortable for you.", "breakfast_b": "Vegetable poha with a fully cooked egg.", "lunch_a": "Dal, roti, rice, and a cooked vegetable.", "lunch_b": "Chicken curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "A familiar snack, eaten without guilt.", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "A vegetable curry with roti, in your usual portion.", "dinner_b": "An egg curry (cooked through) with roti.", "still_hungry": "A familiar snack — hunger deserves a real response either way."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of noticing ''how much more'' is worth a quick look back — and a gentle reminder that this modest shift is meant to feel easy, not like a project. The Second Trimester''s extra energy need is real but modest — usually one nourishing snack or two smaller additions across your day, not a second dinner. Whether your appetite has grown a little, a lot, or not much at all, your care team''s growth and weight-gain guidance for your own body is the most reliable way to know you''re on track, more than counting calories yourself.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which part of ''a little more, not a lot more'' felt easiest to notice this week — the small food additions, letting go of the doubling idea, or trusting your appetite either way?',
   'Next week, we''ll look at iodine — essential for your baby''s brain development, and easy to get right with the salt already in your kitchen.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 15: The right salt, not more salt
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   15,
   'second',
   NULL,
   'The right salt, not more salt',
   '"Check the label, use it moderately — that''s the whole job."',
   'Iodine is needed to make thyroid hormones that support your baby''s brain and nervous-system development throughout pregnancy. ICMR-NIN''s 2020 RDA for iodine during pregnancy is 220mcg per day (up from 150mcg for non-pregnant adults). International organizations such as WHO sometimes reference a higher 250mcg figure, but the practical approach stays the same either way: use iodized salt, in your usual moderate amount — not more of it. India''s decades-long universal salt iodization programme means this is usually already built into everyday cooking. Use iodized salt the right way: - Check the packet specifically says "iodized." - Store it in a closed container, away from moisture and direct heat. - Use it in your usual moderate amount — more salt isn''t a way to get more iodine, and extra sodium isn''t a goal here. If you eat meat, fish, or eggs: If you eat fish, choose lower-mercury options for about two to three meals across the week; egg or chicken cover the other non-vegetarian choices. Iodized salt remains an important source regardless of whether you eat vegetarian or non-vegetarian food.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Iodine is essential for your thyroid hormones and your baby''s brain and nervous-system development throughout pregnancy. In most Indian kitchens, the iodized salt you already cook with — used in your usual amount, not more — is doing most of this work.", "breakfast_a": "Vegetable poha, cooked with your usual iodized salt.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Dal, roti, rice, and a cooked vegetable, seasoned as usual.", "lunch_b": "Chicken curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "A glass of milk.", "nourishment_break_b": "Curd with fruit.", "dinner_a": "A vegetable curry with roti, cooked with your usual salt.", "dinner_b": "Fish curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "Plain sendha namak is not a reliable iodine source", "notes": "Today: Plain rock salt (sendha namak), often used during religious fasts, doesn''t reliably provide iodine unless the packet specifically says it''s iodized. Occasional use during a fast is different from replacing your household''s iodized salt with it for an extended period. This iodine information alone doesn''t determine whether fasting is suitable during pregnancy — that depends on duration, hydration, and your own health circumstances. If you fast repeatedly or for long periods, it''s worth discussing your overall food, fluid, and medication plan with your maternity team. Checking that any packaged rock salt is labelled iodized is a simple habit either way.", "breakfast_a": "Sabudana khichdi with peanuts, and where permitted a side of curd (if fasting), or vegetable upma with your usual iodized salt.", "breakfast_b": "The same, with a boiled egg (cooked through) if not fasting.", "lunch_a": "Dal, roti, and a cooked vegetable, with iodized salt.", "lunch_b": "Chicken curry (cooked through), roti, and a cooked vegetable.", "nourishment_break_a": "A banana or fruit — a good fasting-friendly option too.", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "A vegetable curry with roti, cooked with iodized salt.", "dinner_b": "An egg curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "Already in your everyday cooking", "notes": "Today: Milk, curd, and eggs all contain some iodine too, alongside the iodized salt already in your usual cooking — nothing separate needs to be added. This doesn''t need to be a special ''iodine meal'' — it''s the same cooking and iodized salt already used in many households.", "breakfast_a": "Idli with sambar and a side of curd.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma or chana curry with rice, cooked as usual.", "lunch_b": "Chicken curry (cooked through) with rice.", "nourishment_break_a": "A glass of milk, or curd with fruit.", "nourishment_break_b": "Roasted peanuts or chana.", "dinner_a": "Paneer or tofu curry with roti.", "dinner_b": "Egg curry (cooked through) with roti.", "still_hungry": "A regular hunger-led snack."}, {"day_number": 4, "title": "Where seafood genuinely helps", "notes": "Today: Marine fish and shellfish are naturally iodine-rich, since iodine concentrates in seawater — freshwater fish don''t carry the same amount. If you eat seafood, this is a day it genuinely contributes; if you don''t, the iodized salt already in your cooking remains your main, reliable source. Choose lower-mercury fish and cook it fully, same as every week. If this applies to you (existing thyroid condition): Do not start a separate iodine, kelp, or seaweed supplement on your own. Check whether your prenatal supplement already contains iodine before adding another product — this matters especially with a thyroid condition, since more iodine isn''t automatically better and can affect thyroid function in either direction. Ask your doctor to guide the amount that''s right for you. Source: American Thyroid Association guidance on iodine intake in pregnancy.", "breakfast_a": "Vegetable upma or poha.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Dal, rice, and a cooked vegetable.", "lunch_b": "A marine fish curry (cooked through) — such as sardines or pomfret — with rice.", "nourishment_break_a": "Curd with fruit.", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "A vegetable curry with roti.", "dinner_b": "Chicken curry (cooked through) with roti.", "still_hungry": "Fruit, or a familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: You usually don''t need to plan around iodine specifically when you''re eating out — your regular household pattern is what matters most. Make it easier: You usually don''t need to investigate which salt was used in one occasional meal out. Your regular household pattern matters more — use labelled iodized salt at home, in your usual moderate amount.", "breakfast_a": "Idli or dosa with sambar.", "breakfast_b": "The same, with a boiled egg alongside if it''s available.", "lunch_a": "A dal or sabzi-based thali item with rice or roti.", "lunch_b": "A chicken dish (cooked through), with the same dal or sabzi alongside.", "nourishment_break_a": "A piece of fruit.", "nourishment_break_b": "Roasted chana or peanuts carried with you.", "dinner_a": "A shared family meal — whatever''s on the table.", "dinner_b": "The same meal, with a chicken or egg dish (cooked through) alongside.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "If you''re cutting back on salt", "notes": "Today: Reducing salt for blood pressure is a reasonable goal, but it''s worth doing thoughtfully rather than reaching for a substitute on your own. If this applies to you (high blood pressure): If you have high blood pressure, follow the salt target given by your maternity team. Ask before using a potassium-based salt substitute, particularly if you also have kidney or heart disease, or take medicine that affects potassium levels. Cutting back on sodium isn''t a reason to start an iodine supplement on your own — the amount you get from food varies, and your care team can advise if a supplement is genuinely needed. Source: general clinical guidance on potassium-based salt substitutes and hyperkalemia risk in kidney disease, heart disease, and related conditions.", "breakfast_a": "Vegetable poha, with salt used a little more lightly than usual.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Dal, roti, and a cooked vegetable, seasoned moderately.", "lunch_b": "Chicken curry (cooked through), roti, and a cooked vegetable.", "nourishment_break_a": "A glass of milk, or curd with fruit.", "nourishment_break_b": "Roasted chana or peanuts.", "dinner_a": "A vegetable curry with roti, seasoned moderately.", "dinner_b": "Egg curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of noticing iodine — mostly already handled by your kitchen salt — is worth a quick look back. For most mothers cooking with labelled iodized salt in a normal amount, iodine isn''t something that needs active daily attention. The main things worth remembering: check the packet says iodized, don''t add extra salt to chase iodine, and don''t start an iodine, kelp, or potassium-salt product on your own — especially with an existing thyroid condition — without your care team''s guidance.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'What did you notice this week about where iodine already shows up in your usual cooking — the salt, the dairy, or a meal with fish?',
   'Next week, we''ll look at magnesium — including why it''s often linked to leg cramps, and what the evidence actually says.')
