-- pregnancy week 16: Magnesium — real roles, honest limits
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   16,
   'second',
   NULL,
   'Magnesium — real roles, honest limits',
   '"Worth eating for what it does do — not a promised fix for a cramp."',
   'Magnesium supports nerve and muscle function, blood-sugar regulation, blood-pressure regulation, and building bone and protein. ICMR-NIN''s 2020 RDA for magnesium during pregnancy is about 350mg per day (an adult woman''s usual 310mg, plus roughly 40mg more in pregnancy). Many mothers first hear about magnesium because of leg cramps — this week looks at that honestly: research has not established magnesium supplements as a consistently effective treatment for pregnancy leg cramps, and the studies are small with uncertain evidence. That doesn''t take away from magnesium''s other, well-established roles — it just means it isn''t a guaranteed cramp fix on its own. If you eat meat, fish, or eggs: Magnesium is naturally a mostly plant-forward nutrient — nuts, seeds, whole grains, legumes, and leafy greens are the richest everyday sources, so a vegetarian diet isn''t at any disadvantage here. Meat, fish, and dairy contribute a smaller additional amount. If choosing fish, select a lower-mercury variety for about two to three meals across the week; egg or chicken cover the other non-vegetarian choices.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Magnesium supports nerve and muscle function, blood-sugar and blood-pressure regulation, and building bone and protein — genuinely useful reasons to include it, on their own, regardless of the leg-cramp question this week explores.", "breakfast_a": "Ragi porridge or ragi dosa with a vegetable side.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma or chana curry with rice and a cooked vegetable.", "lunch_b": "The same rajma or chana curry, with chicken curry (cooked through) alongside.", "nourishment_break_a": "A small handful of mixed nuts and roasted pumpkin seeds.", "nourishment_break_b": "A banana with a small handful of peanuts.", "dinner_a": "Bajra or jowar roti with a palak or methi sabzi.", "dinner_b": "The same sabzi and roti, with fish curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "What the evidence on cramps actually says", "notes": "Today: Many mothers reach for magnesium specifically hoping it will stop leg cramps. It''s worth knowing honestly: research has not established magnesium supplements as a consistently effective treatment for pregnancy leg cramps. The studies are small and the evidence remains uncertain. That doesn''t mean magnesium-rich food isn''t worth eating — it supports plenty else. It just means it isn''t a guaranteed fix for cramps on its own.", "breakfast_a": "Vegetable poha or upma.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Moong dal, roti, rice, and a cooked vegetable.", "lunch_b": "Chicken curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "Curd with fruit.", "nourishment_break_b": "Buttermilk with roasted chana.", "dinner_a": "Whole-wheat roti with a spinach or mixed-vegetable sabzi.", "dinner_b": "The same sabzi and roti, with egg curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "Simple things worth trying tonight", "notes": "Today: A few reasonable, low-risk comfort measures to try: stretching your calf before bed (pulling your toes up toward your shin with your leg straight), staying hydrated through the day rather than only in the evening, and gentle walking. A warm bath or gentle massage can help if a cramp strikes at night. Don''t force a stretch through severe pain, and don''t stretch, massage, or warm a leg that''s suddenly and unusually swollen, red, or warm — that''s a different situation, described below. Worth knowing: Seek urgent medical advice if one leg becomes noticeably more swollen, painful, warm, red, or discoloured than the other. Don''t massage or repeatedly stretch a suddenly painful, swollen leg. Sudden breathlessness, chest pain, coughing blood, or collapse needs emergency help. Source: NHS guidance on deep vein thrombosis warning signs in pregnancy.", "breakfast_a": "Idli with sambar.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Dal, roti, rice, and a cooked vegetable.", "lunch_b": "Fish curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "A piece of fruit with a few almonds or walnuts.", "nourishment_break_b": "Roasted peanuts mixed with pumpkin seeds.", "dinner_a": "A vegetable curry with roti.", "dinner_b": "Chicken curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Where magnesium naturally shows up", "notes": "Today: Nuts and seeds, whole grains like bajra, jowar, and ragi, and legumes such as rajma, chana, and moong dal are the richest everyday magnesium sources in Indian vegetarian cooking, with leafy greens adding more. Banana is a familiar, modest contributor too, though not in the same league as these. If this applies to you (gestational diabetes): Nuts, seeds, dal, and leafy vegetables can contribute magnesium, but portions and carbohydrate combinations still need to follow your individual blood-sugar plan. Magnesium supplements are not a substitute for gestational-diabetes treatment.", "breakfast_a": "Jowar or bajra roti with a vegetable side.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma or chana curry with brown rice, if you have it, or your usual rice.", "lunch_b": "The same curry, with chicken curry (cooked through) alongside.", "nourishment_break_a": "A small handful of almonds, cashews, or pumpkin seeds.", "nourishment_break_b": "A banana with a spoon of peanut butter, if you like it.", "dinner_a": "Moong dal with a leafy-green sabzi and roti.", "dinner_b": "The same dal and sabzi, with chicken curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: A meal out or a shared family plate usually already includes enough dal, whole grain, or vegetable to contribute some magnesium — nothing special needs to be arranged.", "breakfast_a": "Idli, dosa, or poha, whatever''s available.", "breakfast_b": "The same, with an egg dish alongside if it''s available.", "lunch_a": "A dal or sabzi-based thali item with rice or roti.", "lunch_b": "A chicken dish (cooked through), with the same dal or sabzi alongside.", "nourishment_break_a": "A piece of fruit with a small packet of roasted nuts.", "nourishment_break_b": "Buttermilk, with roasted chana if you have it.", "dinner_a": "A shared family meal — whatever''s on the table.", "dinner_b": "The same meal, with a chicken or egg dish (cooked through) alongside.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "If you''re thinking about a magnesium supplement", "notes": "Today: Food-source magnesium is generally the better starting point. Magnesium from ordinary food is unlikely to cause harm in people with healthy kidney function; supplements and magnesium-containing antacids or laxatives require more care, particularly with kidney disease. A US reference sets 350mg a day as the upper limit for magnesium from supplements and magnesium-containing medicines during pregnancy — magnesium naturally present in food isn''t counted in that limit. Supplements can cause diarrhoea, nausea, or stomach cramps, so don''t add one without checking the dose already in your prenatal supplement and discussing it with your maternity team. If you''ve heard of magnesium given as an IV drip in a hospital for pre-eclampsia, that''s a different, much higher, medically supervised dose used to prevent seizures — not something an oral tablet at home replicates or is meant to replicate. Ask your care team before starting any magnesium supplement — food is the steadier, lower-risk source for most mothers. If this applies to you (thyroid condition (on levothyroxine)): Magnesium supplements and some magnesium-containing antacids or laxatives can interfere with levothyroxine absorption. Follow the timing instructions supplied with your medicine or given by your doctor or pharmacist; separation of about four hours is commonly advised. Sources: NIH Office of Dietary Supplements pregnancy fact sheet (magnesium upper limit); general drug-interaction guidance on magnesium and levothyroxine timing.", "breakfast_a": "Vegetable paratha with curd.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Dal, roti, rice, and a cooked vegetable.", "lunch_b": "Chicken curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "A glass of milk, or curd with fruit.", "nourishment_break_b": "Roasted chana mixed with peanuts.", "dinner_a": "A vegetable curry with roti.", "dinner_b": "Egg curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of noticing magnesium''s real, ordinary roles — and being honest about what it can''t promise for a cramp — is worth a quick look back. For most mothers, ordinary meals built around whole grains, dal, nuts, and leafy vegetables already provide magnesium. If cramps remain frequent or severe, it''s still worth mentioning to your care team — not because a supplement is guaranteed to fix it, but because they can rule out other causes and advise what''s reasonable to try.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did you try a calf stretch or a change in hydration this week — and did it feel different from focusing on food alone?',
   'Next week, we''ll look at fibre and digestion — a practical, everyday topic as pregnancy hormones and a growing baby both tend to slow things down.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 17: Fibre — keeping things moving, gently
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   17,
   'second',
   NULL,
   'Fibre — keeping things moving, gently',
   '"A gradual, well-hydrated increase does more than a sudden one."',
   'Fibre adds bulk and softness to stool, while some types support beneficial gut microbes and can help moderate post-meal blood-sugar and cholesterol responses. ICMR-NIN''s dietary guidelines set fibre at about 30g per 2000 kilocalories for adults generally; international pregnancy guidance commonly suggests a similar 25-30g/day range, since pregnancy doesn''t sharply change this need the way it does for iron or folate. Many mothers first notice fibre because of constipation, which is genuinely common in pregnancy — this week covers both the everyday food side of that and a few honest, low-risk options if food alone isn''t quite enough. If you eat meat, fish, or eggs: Fibre is almost entirely a plant nutrient — meat, fish, eggs, and dairy contain little to none of it. A non-vegetarian diet doesn''t reduce fibre intake as long as grains, dal, vegetables, and fruit stay on the plate alongside meat, fish, or eggs. If choosing fish, use a lower-mercury variety for about two to three meals across the week; egg or chicken can cover other non-vegetarian choices.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Fibre adds bulk and softness to stool, while some types support beneficial gut microbes and can help moderate post-meal blood-sugar and cholesterol responses — genuinely useful reasons to include it, beyond the constipation question this week focuses on.", "breakfast_a": "Vegetable daliya (broken wheat) or oats upma.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma or chana curry with brown rice or whole-wheat roti, and a cooked vegetable.", "lunch_b": "The same curry, with chicken curry (cooked through) alongside.", "nourishment_break_a": "A fruit with its skin, like a guava or apple, with a few nuts.", "nourishment_break_b": "Roasted chana mixed with peanuts.", "dinner_a": "Whole-wheat roti with a mixed-vegetable sabzi and dal.", "dinner_b": "The same sabzi and dal, with fish curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "Why pregnancy slows things down", "notes": "Today: Constipation is common in pregnancy for a few real reasons: rising progesterone slows how quickly food moves through your gut, your growing uterus adds pressure, and iron supplements can add to it too, especially at higher doses. None of this means something is wrong — it''s a well-known, ordinary trade-off, not a sign you''re doing anything incorrectly. Iron can contribute to constipation, but don''t stop or reduce it yourself. Fibre, fluid, and movement may help. If symptoms persist, ask your maternity team whether the dose, formulation, timing, or an appropriate pregnancy-compatible treatment should be reviewed. Worth knowing: Hemorrhoids can cause a small amount of bright-red blood after a bowel movement, but don''t assume bleeding is from piles — tell your maternity team about rectal bleeding, particularly if it''s new, repeated, heavy, mixed through the stool, accompanied by pain or dizziness, or if the stool is black or tar-like. Seek urgent help for heavy bleeding or feeling faint. Separately: severe or worsening abdominal pain, repeated vomiting, a markedly swollen abdomen, or being unable to pass stool or gas needs urgent medical assessment — don''t take more fibre or a laxative while waiting for advice.", "breakfast_a": "Vegetable poha with peas.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Moong dal, roti, rice, and a cooked vegetable.", "lunch_b": "Chicken curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "Fully ripe papaya or another seasonal fruit, with a few nuts.", "nourishment_break_b": "Buttermilk with roasted chana.", "dinner_a": "Whole-wheat roti with a bhindi or other vegetable sabzi.", "dinner_b": "The same sabzi and roti, with egg curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "Increasing fibre comfortably", "notes": "Today: Adding a lot of fibre all at once can leave you gassy or bloated — genuinely uncomfortable, not a sign to avoid fibre. Increasing it gradually over several days, and drinking enough water alongside, makes a real difference. Fibre needs fluid to do its job; without enough water, more fibre can feel worse, not better. Gentle daily movement, like walking, if it''s comfortable and permitted, and going to the toilet as soon as you feel the urge rather than delaying it, both genuinely help too — not just food and water.", "breakfast_a": "Oats porridge with chopped fruit.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Chana curry with jowar or bajra roti, and a cooked vegetable.", "lunch_b": "The same curry, with chicken curry (cooked through) alongside.", "nourishment_break_a": "A glass of water or buttermilk, with a piece of fruit.", "nourishment_break_b": "Roasted peanuts mixed with pumpkin seeds.", "dinner_a": "Brown rice or whole-wheat roti with a leafy-green sabzi and dal.", "dinner_b": "The same sabzi and dal, with fish curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Where fibre naturally shows up", "notes": "Today: Whole grains and millets (bajra, jowar, ragi, whole wheat, brown rice), dal and legumes (rajma, chana, moong), and vegetables are the everyday sources already common in Indian cooking. Whole fruits such as guava, pear, orange, apple, or fully ripe papaya can contribute fibre too — choose what''s available and comfortable for you. If this applies to you (gestational diabetes): Fibre, especially from whole grains, dal, and vegetables, can help smooth how quickly your blood sugar rises after a meal — a genuinely useful part of a gestational-diabetes eating plan. It works alongside, not instead of, the specific meal plan and portions your care team has given you. Source: general clinical nutrition guidance on dietary fibre and post-meal blood sugar response.", "breakfast_a": "Ragi or jowar roti or dosa with a vegetable side.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma or chana curry with brown rice.", "lunch_b": "The same curry, with chicken curry (cooked through) alongside.", "nourishment_break_a": "Guava or another seasonal fruit, with a few almonds or walnuts.", "nourishment_break_b": "A seasonal fruit with a small handful of walnuts or pumpkin seeds.", "dinner_a": "Moong dal with a mixed-vegetable sabzi and roti.", "dinner_b": "The same dal and sabzi, with egg curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: Choosing a roti or rice-and-dal-and-vegetable combination when you''re eating out still contributes fibre — nothing special needs to be arranged.", "breakfast_a": "Idli or dosa with sambar and vegetable chutney.", "breakfast_b": "The same, with an egg dish alongside if it''s available.", "lunch_a": "A dal or sabzi-based thali item with rice or roti.", "lunch_b": "A chicken dish (cooked through), with the same dal or sabzi alongside.", "nourishment_break_a": "A piece of fruit with a small packet of roasted nuts.", "nourishment_break_b": "Buttermilk, with roasted chana if you have it.", "dinner_a": "A shared family meal — whatever''s on the table, with a vegetable side if there''s a choice.", "dinner_b": "The same meal, with a chicken or egg dish (cooked through) alongside.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "If food alone isn''t enough", "notes": "Today: Isabgol (psyllium husk) is a bulk-forming fibre, widely used and generally considered safe in pregnancy — it isn''t absorbed into your bloodstream and works differently from a stimulant laxative. Don''t start it if you have difficulty swallowing, unexplained rectal bleeding, significant abdominal pain, nausea or vomiting, or possible bowel blockage. Follow the packet dose, take it with about 240ml of fluid, and ask a pharmacist about spacing it from any medicines you take. If food, fluid, and movement aren''t enough, ask your maternity team or pharmacist which pregnancy-compatible option suits your symptoms — different laxatives work differently, so avoid repeatedly self-treating or combining products without advice. Bulk-forming options like isabgol are commonly tried first, but others may be appropriate depending on your symptoms. If this applies to you (thyroid condition (on levothyroxine)): Fibre supplements such as isabgol, and major changes in your usual fibre intake, can affect levothyroxine absorption. Take your medicine consistently according to its label or your doctor''s instructions — commonly on an empty stomach 30-60 minutes before breakfast. Ask your doctor or pharmacist how far to separate isabgol from it, and mention any major, sustained change in your fibre intake, since your thyroid levels or dose may need monitoring. Sources: general levothyroxine prescribing guidance on consistent dosing and timing; MedlinePlus and NHS guidance on psyllium/isabgol precautions and fluid intake.", "breakfast_a": "Vegetable paratha with curd.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Dal, roti, rice, and a cooked vegetable.", "lunch_b": "Chicken curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "Curd with fruit.", "nourishment_break_b": "Roasted chana mixed with peanuts.", "dinner_a": "A vegetable curry with roti.", "dinner_b": "Egg curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of noticing fibre''s ordinary, steady role — and a few honest, low-risk ways to ease constipation — is worth a quick look back. For most mothers, ordinary meals built around whole grains, dal, vegetables, and fruit — increased gradually, paired with enough water, and combined with gentle movement — are all that''s needed. If constipation is persistent, severe, or comes with any warning sign above, it''s worth asking your maternity team for advice rather than adding more fibre or a laxative on your own.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did increasing fibre gradually, alongside more water and a bit of movement, feel any different this week than a sudden change would have?',
   'Next week, we''ll look at vitamin D — a nutrient many Indian mothers run low on, and why sunlight alone doesn''t always solve it.')
on conflict (stage, week_number) do update set
