-- pregnancy week 18: Vitamin D — easy to overlook, hard to judge from symptoms alone
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   18,
   'second',
   NULL,
   'Vitamin D — easy to overlook, hard to judge from symptoms alone',
   '"Sunlight helps, but it isn''t the whole story here."',
   'Vitamin D helps your body absorb calcium for your bones and your baby''s, and also supports muscle and immune function. ICMR-NIN''s RDA for vitamin D is 600 IU (15mcg) a day — this is the same figure for non-pregnant adults, pregnancy, and lactation, unlike some other nutrients this series has covered. This is a population intake reference, not a treatment dose for a confirmed deficiency. Indian studies have reported a high prevalence of low vitamin D during pregnancy, including in sunny regions, although estimates vary widely between studies. Low vitamin D levels have been associated with several pregnancy complications, but association doesn''t prove that low vitamin D caused them — vitamin D supplements shouldn''t be presented as a proven way to prevent preeclampsia or gestational diabetes. If you eat meat, fish, or eggs: Oily fish can provide meaningful vitamin D; egg yolk contributes a smaller amount. A vegetarian diet isn''t left without any options — UV-exposed mushrooms and foods specifically labelled as vitamin-D fortified can help — but for most mothers, of any diet, food alone is an uncertain way to reliably meet vitamin D needs, so your prescribed prenatal supplement matters more here than for many other nutrients. If choosing fish, use a lower-mercury variety for about two to three meals across the week; egg or chicken can cover other non-vegetarian choices (chicken itself isn''t a meaningful vitamin D source). A note on this week''s menus: Food choices can contribute, but many mothers won''t reliably meet their vitamin D needs from ordinary food alone. Follow the supplement plan your maternity team has given you, rather than expecting every meal here to be a guaranteed vitamin D source.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Vitamin D helps your body absorb calcium for your bones and your baby''s, and also supports muscle and immune function. ICMR-NIN''s RDA is 600 IU (15mcg) a day — the same figure whether or not you''re pregnant or breastfeeding, unlike some other nutrients this series has covered. This is a population intake reference, not a treatment dose for a confirmed deficiency, and this week''s menus can''t guarantee 600 IU, since the vitamin D content of fish, eggs, and fortified products varies.", "breakfast_a": "Vegetable poha, with a glass of milk labelled as vitamin-D fortified alongside.", "breakfast_b": "The same, with a boiled egg (yolk included, cooked through) alongside.", "lunch_a": "Dal, roti, rice, and a cooked vegetable, with a side of curd.", "lunch_b": "Chicken curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "A glass of milk labelled as vitamin-D fortified, with a small fruit.", "nourishment_break_b": "Roasted chana mixed with peanuts.", "dinner_a": "A vegetable curry with roti and a side of curd.", "dinner_b": "Fish curry (cooked through) — sardines or Indian mackerel (bangda) — with roti.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "Why sunlight alone doesn''t always solve it", "notes": "Today: Indian studies have reported a high prevalence of low vitamin D during pregnancy, including in sunny regions, although estimates vary widely between studies. Sitting near a sunny window doesn''t help much, since glass blocks the UVB rays your skin needs; time spent mostly indoors, covering clothing, sunscreen, and the amount of melanin in your skin all reduce how much your body makes, regardless of how sunny it is outside.", "breakfast_a": "Idli with sambar and a side of curd.", "breakfast_b": "The same, with a boiled egg (yolk included, cooked through) alongside.", "lunch_a": "Rajma or chana curry with rice and a cooked vegetable.", "lunch_b": "Chicken curry (cooked through), rice, and a cooked vegetable.", "nourishment_break_a": "Curd with fruit.", "nourishment_break_b": "A glass of milk labelled as vitamin-D fortified.", "dinner_a": "Whole-wheat roti with a mixed-vegetable sabzi.", "dinner_b": "The same sabzi and roti, with egg curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "Where vitamin D naturally shows up", "notes": "Today: Oily fish can provide meaningful vitamin D — lower-mercury choices like sardines or Indian mackerel (bangda) are good options. Egg yolk contributes a smaller amount. UV-exposed mushrooms and foods specifically labelled as fortified can also contribute — check the nutrition label, since \"milk,\" \"curd,\" or a plant-based drink isn''t automatically fortified. Vitamin D is fat-soluble and is absorbed with an ordinary mixed meal; there''s no need to add extra ghee or oil specifically for it.", "breakfast_a": "Vegetable paratha with curd.", "breakfast_b": "The same, with a boiled egg (yolk included, cooked through) alongside.", "lunch_a": "Dal, roti, rice, and a mushroom or mixed-vegetable sabzi.", "lunch_b": "A fish curry (cooked through) — sardines or Indian mackerel (bangda) — with rice and a cooked vegetable.", "nourishment_break_a": "A glass of milk labelled as vitamin-D fortified, with a few nuts.", "nourishment_break_b": "Curd with fruit.", "dinner_a": "A vegetable curry with roti.", "dinner_b": "Chicken curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "If deficiency is confirmed or suspected", "notes": "Today: A 25-hydroxyvitamin D blood test is used when testing is clinically appropriate — routine testing isn''t necessary for every pregnant woman, but your maternity team may consider it if you have risk factors, symptoms, bone-health concerns, malabsorption, obesity, very limited sun exposure, or a previous low result. Check whether your prescribed prenatal supplement already contains vitamin D, and follow your maternity team''s advice — don''t combine products or start a treatment-dose vitamin D preparation yourself. When deficiency is confirmed, the appropriate dose and duration depend on the blood result and your clinical situation. If this applies to you (thyroid condition (on levothyroxine)): Many vitamin D supplements sold in India are combined with calcium in the same tablet, and the interaction that matters here comes from the calcium, not the vitamin D. If the product contains calcium, follow the levothyroxine label or your doctor/pharmacist''s spacing instructions — commonly at least four hours apart. A vitamin-D-only product doesn''t carry that calcium interaction. Source: general drug-interaction guidance on calcium and levothyroxine absorption timing.", "breakfast_a": "Vegetable upma, with a glass of milk labelled as vitamin-D fortified.", "breakfast_b": "The same, with a boiled egg (yolk included, cooked through) alongside.", "lunch_a": "Dal, roti, rice, and a cooked vegetable, with a side of curd.", "lunch_b": "Chicken curry (cooked through), roti, rice, and a cooked vegetable.", "nourishment_break_a": "A glass of milk labelled as vitamin-D fortified, or curd with fruit.", "nourishment_break_b": "Roasted chana mixed with peanuts.", "dinner_a": "A vegetable curry with roti.", "dinner_b": "Egg curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: A meal out or a shared family plate can still include a vitamin D source if fish or egg is on the table. Curd is a good addition for calcium and protein either way, but it only counts toward vitamin D if it''s specifically labelled fortified.", "breakfast_a": "Idli, dosa, or poha, whatever''s available.", "breakfast_b": "The same, with an egg dish alongside if it''s available.", "lunch_a": "A dal or sabzi-based thali item with rice or roti, and curd if it''s offered.", "lunch_b": "A chicken dish (cooked through), with the same dal or sabzi alongside.", "nourishment_break_a": "A piece of fruit with a small packet of roasted nuts.", "nourishment_break_b": "A glass of milk labelled as vitamin-D fortified. If only regular milk or buttermilk is available, count it for hydration, protein, and calcium — not as a reliable vitamin D source.", "dinner_a": "A shared family meal — whatever''s on the table.", "dinner_b": "The same meal, with a chicken or egg dish (cooked through) alongside.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "A little time outdoors, safely", "notes": "Today: Your skin can make vitamin D outdoors, but the amount varies greatly with the UV index, season, time of day, skin tone, clothing, and other factors — there''s no single exposure time that works for everyone. Don''t deliberately risk tanning, overheating, or sunburn to chase vitamin D. Follow your ordinary sun-protection habits, and rely on food, your prescribed prenatal supplement, and clinical testing when appropriate, rather than sunlight alone.", "breakfast_a": "Vegetable daliya or oats upma.", "breakfast_b": "The same, with a boiled egg (yolk included, cooked through) alongside.", "lunch_a": "Dal, roti, rice, and a cooked vegetable.", "lunch_b": "Fish curry (cooked through) — sardines or Indian mackerel (bangda) — roti, rice, and a cooked vegetable.", "nourishment_break_a": "A glass of milk labelled as vitamin-D fortified, with a small fruit.", "nourishment_break_b": "Roasted chana mixed with peanuts.", "dinner_a": "A vegetable curry with roti and a side of curd.", "dinner_b": "Chicken curry (cooked through) with roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of noticing vitamin D''s quieter, easy-to-overlook role — and why sunlight and ordinary food alone aren''t always the whole answer — is worth a quick look back. Vitamin D status is genuinely hard to judge from symptoms alone, and food choices vary in how much they can guarantee. Testing isn''t something every mother needs — it''s something your care team may consider if it''s clinically relevant for you. The main habits worth keeping are checking labels, following your prescribed supplement plan, and not chasing sunlight or a higher dose on your own.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Had you thought about vitamin D before this week — and did anything here surprise you about why sunlight and food alone aren''t always enough?',
   'Next week, we''ll look at hydration — how much fluid genuinely helps, and the everyday signs that you might need a little more.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
