-- pregnancy week 19: Hydration — more than plain water
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   19,
   'second',
   NULL,
   'Hydration — more than plain water',
   '"A flexible daily target and pale urine tell you more than a fixed number of glasses."',
   'Fluid supports your growing blood volume, digestion, and temperature regulation, and helps your body maintain normal fluid balance overall. ICMR-NIN advises pregnant women to consume over 2 litres of fluids a day, including water and other beverages — a starting point rather than a rigid ceiling, since hot weather, activity, fever, vomiting, or diarrhoea can raise what you need. A flexible daily target, regular drinking, comfortable thirst, and pale-yellow urine can help you judge what works for you, without needing to fixate on an exact number of glasses. A note for every diet: Hydration needs don''t differ by diet — vegetarian and non-vegetarian mothers alike need roughly the same fluid intake. What varies more is climate, activity level, and body size than what''s on your plate.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Fluid supports your growing blood volume, digestion, and temperature regulation, and helps your body maintain normal fluid balance overall. ICMR-NIN advises pregnant women to consume over 2 litres of fluids a day, including water and other beverages — a starting point rather than a rigid ceiling, since hot weather, activity, fever, vomiting, or diarrhoea can raise what you need.", "breakfast_a": "Vegetable poha with a glass of buttermilk (chaas).", "breakfast_b": "The same, with a vegetable omelette (cooked through) alongside.", "lunch_a": "Rajma curry with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "Home-style chicken pulao with raita.", "nourishment_break_a": "A slice of watermelon or orange.", "nourishment_break_b": "A glass of coconut water.", "dinner_a": "A vegetable curry with roti and a bowl of dal.", "dinner_b": "The same curry and roti, with fish curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "How to tell if you''re getting enough", "notes": "Today: A flexible daily target, regular drinking, comfortable thirst, and pale-yellow urine can help you judge what works for you. Prenatal vitamins and some medicines can change urine colour, so look at the overall pattern rather than one bathroom visit. Repeatedly dark urine, a dry mouth, dizziness, or noticeably reduced urination may mean you need more fluid or medical advice, especially if it continues despite drinking.", "breakfast_a": "Idli with sambar.", "breakfast_b": "The same, with egg bhurji (cooked through) alongside.", "lunch_a": "Moong dal with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "Chicken vegetable stew with rice.", "nourishment_break_a": "Cucumber or orange slices.", "nourishment_break_b": "A glass of buttermilk (chaas).", "dinner_a": "Whole-wheat roti with a vegetable sabzi and a bowl of dal.", "dinner_b": "The same sabzi and roti, with a boiled egg (cooked through) alongside.", "still_hungry": "Roasted makhana."}, {"day_number": 3, "title": "What counts beyond plain water", "notes": "Today: Water, milk, buttermilk, soups, dal, and water-rich fruits such as watermelon, cucumber, and orange all contribute fluid — it doesn''t have to be plain water alone. These can add variety, but plain water remains an excellent everyday choice, and special electrolyte drinks aren''t routinely needed. Coconut water is optional, not essential. Choose an unsweetened serving occasionally if you enjoy it; mothers managing blood sugar, potassium, or kidney concerns should follow their care team''s advice.", "breakfast_a": "Vegetable upma with a glass of milk.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Chana curry with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "A fish curry (cooked through) with rice and a cooked vegetable.", "nourishment_break_a": "A glass of coconut water.", "nourishment_break_b": "Watermelon or another water-rich fruit.", "dinner_a": "A lentil-and-vegetable soup with roti.", "dinner_b": "The same soup and roti, with chicken curry (cooked through) alongside.", "still_hungry": "A piece of fruit or roasted chana."}, {"day_number": 4, "title": "Why pregnancy raises the bar", "notes": "Today: Your blood volume rises by roughly 30-50% during pregnancy, mostly by the second trimester — genuinely more fluid work for your body to do. India''s heat adds to this: more sweat means more fluid lost, so warmer days and physical activity both raise what you need.", "breakfast_a": "Vegetable daliya with a glass of buttermilk.", "breakfast_b": "The same, with a vegetable omelette (cooked through) alongside.", "lunch_a": "Chana curry with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "Grilled or pan-cooked chicken with a cooked vegetable and roti.", "nourishment_break_a": "A glass of coconut water or buttermilk.", "nourishment_break_b": "Orange or watermelon.", "dinner_a": "A vegetable curry with roti and a bowl of dal.", "dinner_b": "The same curry and roti, with egg bhurji alongside.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: Carrying a water bottle and choosing a fluid-rich item where you can — buttermilk, a fruit, or a soup-based dish — makes it easier to keep up even outside your usual routine. Use safe drinking water when you''re unsure of the source, same as always.", "breakfast_a": "Idli, dosa, or poha, whatever''s available.", "breakfast_b": "The same, with an egg dish alongside if it''s available.", "lunch_a": "A dal or sabzi-based thali item with rice or roti, according to appetite.", "lunch_b": "A chicken dish (cooked through), with the same dal or sabzi alongside.", "nourishment_break_a": "A piece of fruit, if it''s available.", "nourishment_break_b": "Buttermilk or a safe bottled water.", "dinner_a": "A shared family meal — whatever''s on the table.", "dinner_b": "The same meal, with a chicken or egg dish (cooked through) alongside.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "Drinking steadily, not forcing it", "notes": "Today: Drink steadily across the day rather than forcing a large amount at once. Plain water can provide most of your fluid, while milk, buttermilk, soups, and water-rich foods can also contribute. More isn''t always necessary once your needs are comfortably met. Worth knowing: Don''t assume repeated tightening is only dehydration. Contact your maternity team promptly if tightening becomes regular or painful, keeps returning despite rest and fluids, or comes with bleeding, leaking fluid, pelvic pressure, lower-back pain, or feeling unwell. If this applies to you (gestational diabetes): If you''re managing gestational diabetes, water and unsweetened buttermilk are usually the simplest everyday choices. Coconut water and fruit still contribute carbohydrate, so use the portions your individual plan advises. Persistent unusual thirst or markedly increased urination is still worth discussing with your care team. Source: general clinical guidance on thirst and polyuria as hyperglycemia symptoms.", "breakfast_a": "Vegetable paratha with curd.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma or mixed dal with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "Egg bhurji (cooked through) with roti and a cooked vegetable.", "nourishment_break_a": "A glass of buttermilk.", "nourishment_break_b": "Roasted makhana or a piece of fruit.", "dinner_a": "A vegetable curry with roti and a bowl of dal or curd.", "dinner_b": "Chicken vegetable stew with roti.", "still_hungry": "Curd or a small homemade snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of noticing fluid in its many everyday forms — not just plain water — is worth a quick look back. For most mothers, a steady mix of water, milk, buttermilk, soups, and water-rich fruit through the day — checked against pale urine and comfortable thirst — is all that''s needed. Persistent symptoms or unusual thirst are still worth mentioning to your care team.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did checking your urine colour or thirst this week feel like a more useful guide than trying to count glasses?',
   'Next week, we''ll look at vitamin C — its real role beyond immunity, and why it matters alongside the iron this series covered earlier.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 20: Vitamin C — quietly working alongside iron
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   20,
   'second',
   NULL,
   'Vitamin C — quietly working alongside iron',
   '"A squeeze of lemon does more than season the dal."',
   'Vitamin C supports collagen for your skin and blood vessels, works as an antioxidant, supports normal immune function, and helps your body absorb plant-based iron more effectively. ICMR-NIN''s RDA for vitamin C in pregnancy is 80mg a day. This last role connects directly back to the iron this series covered earlier — pairing an iron-rich meal with a vitamin-C-rich food is one of the simplest, most useful habits in this whole series. If you eat meat, fish, or eggs: Vitamin C is almost entirely a plant nutrient — meat, fish, and eggs contribute very little of it. A non-vegetarian diet doesn''t need to change, but it''s worth making sure fruits and vegetables stay on the plate specifically for this, rather than assuming a meat- or fish-based meal covers it.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Vitamin C supports collagen for your skin and blood vessels, works as an antioxidant, supports normal immune function, and helps your body absorb plant-based iron more effectively. ICMR-NIN''s RDA for vitamin C in pregnancy is 80mg a day.", "breakfast_a": "Vegetable poha with a squeeze of lemon.", "breakfast_b": "The same, with a vegetable omelette (cooked through) alongside.", "lunch_a": "Rajma curry with rice or roti, according to appetite, and a tomato-onion salad.", "lunch_b": "Home-style chicken pulao with a thoroughly washed, freshly prepared salad.", "nourishment_break_a": "A guava or an orange.", "nourishment_break_b": "Roasted chana with orange or mosambi.", "dinner_a": "A capsicum and vegetable sabzi with roti and a bowl of dal.", "dinner_b": "The same sabzi and roti, with fish curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "Why it matters alongside iron", "notes": "Today: Squeezing lemon over dal, having amla or a citrus fruit alongside an iron-rich meal, or finishing lunch with a tomato-based sabzi can meaningfully boost how much of the plant-based iron from that meal your body actually absorbs — the same iron this series covered a few weeks ago. Vitamin C works by converting iron into a form your gut takes up more easily.", "breakfast_a": "Ragi porridge with a small bowl of amla or orange segments.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Chana curry with rice or roti, according to appetite, and a lemon wedge to squeeze over it.", "lunch_b": "Chicken-and-vegetable stew containing tomato or capsicum, with rice.", "nourishment_break_a": "Fresh amla, guava, or orange.", "nourishment_break_b": "Unsweetened buttermilk with fresh amla.", "dinner_a": "Palak or another leafy-green sabzi with roti and a tomato-based side.", "dinner_b": "The same leafy-green sabzi, roti, and tomato-based side, with egg bhurji cooked through.", "still_hungry": "Roasted makhana."}, {"day_number": 3, "title": "Where vitamin C naturally shows up", "notes": "Today: Amla is a rich source of vitamin C, alongside guava, oranges and other citrus, capsicum, tomatoes, and leafy greens. These are everyday, widely available foods in most Indian kitchens.", "breakfast_a": "Vegetable upma with a side of orange segments.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Mixed dal with rice or roti, according to appetite, and a capsicum sabzi.", "lunch_b": "A fish curry (cooked through) with rice and a tomato-based side.", "nourishment_break_a": "Ripe papaya or an orange.", "nourishment_break_b": "Fresh amla or another fresh vitamin-C-rich fruit.", "dinner_a": "A vegetable curry with roti, a bowl of dal, and a thoroughly washed, freshly prepared salad.", "dinner_b": "Chicken curry (cooked through) with roti and a safely washed tomato-capsicum side, or lemon squeezed on after cooking.", "still_hungry": "A piece of fruit."}, {"day_number": 4, "title": "A vitamin that doesn''t like heat or time", "notes": "Today: Vitamin C is sensitive to heat, storage time, and prolonged contact with cooking water. Fresh, safely washed produce and vegetables cooked briefly with minimal water may retain more than foods cooked or stored for a long time. Amla is rich in vitamin C when fresh, but it can still lose vitamin C during storage and processing.", "breakfast_a": "Vegetable daliya with a side of fresh-cut fruit.", "breakfast_b": "The same, with a vegetable omelette (cooked through) alongside.", "lunch_a": "Rajma or chana curry with rice or roti, according to appetite, and a thoroughly washed, freshly prepared salad.", "lunch_b": "Grilled or pan-cooked chicken with a thoroughly washed, freshly prepared salad and roti.", "nourishment_break_a": "Fresh-cut guava or orange, eaten soon after cutting.", "nourishment_break_b": "Unsweetened buttermilk with orange or mosambi segments.", "dinner_a": "A lightly steamed vegetable sabzi with roti and a bowl of dal or curd.", "dinner_b": "The same sabzi and roti, with egg curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: Choose raw salad only when you''re confident it''s been freshly prepared and thoroughly washed with safe water. Otherwise, choose a cooked vegetable, a freshly peeled fruit, or a squeeze of lemon onto hot food.", "breakfast_a": "Idli, dosa, or poha, whatever''s available.", "breakfast_b": "The same, with an egg dish alongside if it''s available.", "lunch_a": "A dal or sabzi-based thali item with rice or roti, and a safely prepared salad, cooked vegetable, or peelable fruit.", "lunch_b": "A fully cooked chicken dish with rice or roti, plus a cooked tomato- or capsicum-based vegetable, a thoroughly washed freshly prepared salad, or peelable fruit.", "nourishment_break_a": "A piece of fruit, if it''s available.", "nourishment_break_b": "Roasted chana or peanuts with a vitamin-C-rich fruit.", "dinner_a": "A shared family meal — whatever''s on the table, with a lemon wedge if there''s a choice.", "dinner_b": "The same meal, with a chicken or egg dish (cooked through) alongside.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "More isn''t the goal here", "notes": "Today: Most mothers can meet vitamin C needs through varied foods. Don''t add a separate high-dose supplement unless your maternity team recommends one, and check what your prenatal supplement already contains. High intakes can cause diarrhoea and abdominal discomfort.", "breakfast_a": "Vegetable paratha with a side of orange segments.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Chana or mixed dal with rice or roti, according to appetite, and a tomato-onion salad.", "lunch_b": "Tomato-capsicum egg bhurji (cooked through) with roti and a cooked vegetable.", "nourishment_break_a": "A guava or amla.", "nourishment_break_b": "Unsweetened buttermilk with ripe papaya.", "dinner_a": "A capsicum and vegetable sabzi with roti and a bowl of dal.", "dinner_b": "Chicken-and-tomato vegetable stew with roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of noticing vitamin C''s quieter partnership with iron, and how easily it already fits into everyday Indian meals, is worth a quick look back. If you''re eating iron-rich meals from earlier in this series, pairing them with a vitamin-C-rich food — a squeeze of lemon, some amla, a piece of citrus — is a small, easy habit that helps your body use that iron better.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did pairing an iron-rich meal with something like lemon, amla, or citrus this week feel like an easy habit to keep?',
   'Next week, we''ll look at zinc — a quieter nutrient with real roles in immunity and growth that''s easy to overlook.')
