-- pregnancy week 21: Zinc — quiet, steady, easy to overlook
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   21,
   'second',
   NULL,
   'Zinc — quiet, steady, easy to overlook',
   '"Zinc works best as part of a varied, consistent eating pattern."',
   'Zinc supports normal immune function, wound healing, growth, and taste, and plays a part in protein and DNA synthesis — genuinely important for your baby''s rapid growth at this stage. ICMR-NIN''s RDA for zinc in pregnancy is 14.5mg a day. Your body regulates zinc through absorption and excretion but doesn''t maintain a large, readily available reserve, so regularly including zinc-containing foods is more useful than trying to compensate for an occasional low day. If you eat meat, fish, or eggs: Meat, fish, and seafood are generally the richest and most bioavailable zinc sources. Eggs and dairy also contribute. Legumes, nuts, seeds, and whole grains provide zinc too, although phytates can reduce how much is absorbed. Soaking before cooking and using sprouted, fermented, or leavened foods may help improve zinc availability from some plant foods.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Zinc supports normal immune function, wound healing, growth, and taste, and plays a part in protein and DNA synthesis. ICMR-NIN''s RDA for zinc in pregnancy is 14.5mg a day.", "breakfast_a": "Vegetable poha with a small handful of roasted pumpkin seeds.", "breakfast_b": "The same, with a vegetable omelette (cooked through) alongside.", "lunch_a": "Rajma curry with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "Home-style chicken pulao with a thoroughly washed, freshly prepared salad.", "nourishment_break_a": "Roasted chana mixed with sesame seeds.", "nourishment_break_b": "A small handful of cashews or almonds.", "dinner_a": "Paneer or tofu curry with roti and a bowl of dal.", "dinner_b": "A vegetable curry with roti and a fully cooked, lower-mercury fish dish.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "Why pregnancy asks for more", "notes": "Today: Zinc supports your baby''s rapid cell division and DNA synthesis during this stage of growth. Your body regulates zinc through absorption and excretion but doesn''t maintain a large, readily available reserve, so regularly including zinc-containing foods is more useful than trying to compensate for an occasional low day.", "breakfast_a": "Ragi porridge with a small bowl of curd.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Chana curry with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "Chicken-and-vegetable stew with rice.", "nourishment_break_a": "A small handful of pumpkin or sesame seeds.", "nourishment_break_b": "A glass of milk.", "dinner_a": "Mixed dal with a leafy-green sabzi and roti.", "dinner_b": "The same dal and sabzi, with egg bhurji (cooked through) alongside.", "still_hungry": "Roasted makhana."}, {"day_number": 3, "title": "Where zinc naturally shows up", "notes": "Today: Meat, fish, and seafood are generally the richest and most bioavailable zinc sources; eggs and dairy also contribute. Legumes, nuts, seeds, and whole grains — chana, rajma, pumpkin seeds, sesame seeds, cashews, bajra, and ragi — provide zinc too, though phytates can reduce how much is absorbed.", "breakfast_a": "Bajra or ragi roti with a vegetable side.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma or chana curry with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "A fish curry (cooked through) with rice and a cooked vegetable.", "nourishment_break_a": "A small handful of cashews, almonds, or pumpkin seeds.", "nourishment_break_b": "Curd with fruit.", "dinner_a": "Tofu or paneer curry with roti and a bowl of dal.", "dinner_b": "Chicken curry (cooked through) with roti and a cooked vegetable.", "still_hungry": "A piece of fruit."}, {"day_number": 4, "title": "The phytate story", "notes": "Today: Phytates in legumes, grains, nuts, and seeds can reduce zinc absorption, but these foods still contribute meaningful zinc. Soaking before cooking, and using fermented or leavened foods — like idli or dosa batter, or yeasted bread — may help improve availability as part of a varied diet. Well-planned vegetarian diets can meet zinc needs from plant sources — this is about making the most of them, not a sign that a vegetarian diet falls short.", "breakfast_a": "Idli or dosa with sambar.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Fully cooked sprouted-moong curry with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "Grilled or pan-cooked chicken with a cooked vegetable and roti.", "nourishment_break_a": "Roasted chana.", "nourishment_break_b": "A glass of buttermilk.", "dinner_a": "Rajma curry with roti and a bowl of curd.", "dinner_b": "The same curry and roti, with egg curry (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Away from home", "notes": "Today: A dal, legume, or paneer-based dish, or a meat/egg dish if that''s what''s available, both genuinely contribute zinc — nothing special needs to be arranged.", "breakfast_a": "Idli or dosa with sambar, or poha with curd or roasted peanuts.", "breakfast_b": "The same, with an egg dish alongside if it''s available.", "lunch_a": "A dal or paneer-based thali item with rice or roti, according to appetite.", "lunch_b": "A fully cooked chicken dish with rice or roti, plus a cooked vegetable or thoroughly washed salad.", "nourishment_break_a": "A small packet of roasted nuts or seeds, if available.", "nourishment_break_b": "A piece of fruit with a small packet of roasted nuts or seeds, if available.", "dinner_a": "A family meal containing dal, beans, paneer, tofu, or curd.", "dinner_b": "A family meal containing a fully cooked egg, chicken, or fish dish.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "Zinc and iron, at odds in supplement form", "notes": "Today: Higher-dose iron supplements can reduce zinc absorption when taken at the same time as a separate zinc supplement. Don''t rearrange prescribed iron, zinc, or prenatal supplements yourself; ask your doctor or pharmacist whether their timing needs to be separated. This concern is about supplements, not ordinary iron- and zinc-containing foods eaten together. More isn''t the goal here either: sustained high-dose zinc supplements can interfere with copper absorption, so don''t add one on your own beyond what your prenatal supplement already provides. Don''t add a separate zinc supplement unless your maternity team recommends it after considering your diet, prenatal supplement, and individual needs.", "breakfast_a": "Vegetable paratha with curd.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Chana or mixed dal with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "Tomato-capsicum egg bhurji (cooked through) with roti and a cooked vegetable.", "nourishment_break_a": "A small handful of pumpkin or sesame seeds.", "nourishment_break_b": "A glass of milk.", "dinner_a": "A vegetable curry with roti and a bowl of dal.", "dinner_b": "Chicken-and-vegetable stew with roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week of noticing zinc''s quiet, steady role — and how it fits alongside the iron this series covered earlier — is worth a quick look back. For most mothers, ordinary meals built around legumes, seeds, nuts, dairy, and — if eaten — meat, fish, or eggs, already provide zinc. Soaking, sprouting, or using fermented batters and doughs may help your body absorb more of the zinc already present.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did anything about zinc''s connection to iron — cooperating in food, competing in supplement form — surprise you this week?',
   'Next week, we''ll look at choline — a lesser-known nutrient with a real, specific role in your baby''s brain development.')
