  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 22: Choline — a building block for your baby's brain
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   22,
   'second',
   NULL,
   'Choline — a building block for your baby''s brain',
   '"Small, regular choices — an egg, a bowl of dal, a handful of soy — add up to something your baby''s brain is actively using right now."',
   'Choline helps build the outer membrane of every one of your baby''s cells, supports normal liver function by helping move fat out of the liver, and is used to make acetylcholine, a chemical messenger involved in nerve and muscle signalling. It also plays a specific role in brain development — including the hippocampus, the region involved in memory and learning — and works in metabolic pathways related to folate, covered earlier in this series, although one nutrient cannot replace the other. Earlier in pregnancy, both nutrients also played important but distinct roles during neural-tube development. ICMR-NIN''s 2020 guidelines don''t set a specific recommended intake for choline for Indians. The most widely used international reference, from the US National Academies, sets an Adequate Intake of 450mg a day in pregnancy — used here as a general guide, not an official Indian figure. Many people, including many who otherwise eat reasonably well, fall short of this amount from food alone; that''s a reason to include choline-containing foods somewhat deliberately, not a cause for alarm. If you eat meat, fish, or eggs: Egg yolk is one of the most concentrated choline sources available — a single egg contributes a meaningful share of a day''s target. Meat, poultry, and fish also contribute, though less concentrated than egg yolk. Choose fish known to be lower in mercury, vary the type, and follow reliable local guidance where available. Small fish such as sardines are often useful choices. Pregnancy guidance commonly recommends two to three servings a week from lower-mercury options. If you don''t eat eggs, meat, or fish, meaningful amounts can still come from combining soybeans, other legumes, peanuts, dairy, and cruciferous vegetables like cauliflower across the day.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Choline supports normal brain and nervous-system development and helps form cell membranes and acetylcholine, an important chemical messenger. ICMR-NIN''s 2020 guidelines don''t set a specific recommended intake for choline for Indians; the most widely used international reference, from the US National Academies, is an Adequate Intake of 450mg a day in pregnancy.", "breakfast_a": "Vegetable poha with a small bowl of curd.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside — egg yolk is one of the most concentrated choline sources available.", "lunch_a": "Rajma curry with rice or roti, according to appetite, and a cooked vegetable.", "lunch_b": "Chicken keema with green peas, and rice or roti, according to appetite.", "nourishment_break_a": "A small bowl of curd with roasted peanuts.", "nourishment_break_b": "Roasted chana.", "dinner_a": "Mixed dal with a leafy-green sabzi and roti.", "dinner_b": "The same dal and sabzi, with egg bhurji (cooked through) alongside.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "Why it matters now", "notes": "Today: Choline supports normal brain and nervous-system development and works in metabolic pathways related to folate, although one nutrient cannot replace the other. Earlier in pregnancy, both nutrients also played important but distinct roles during neural-tube development.", "breakfast_a": "Besan chilla with a side of curd.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Moong-dal khichdi with a cooked vegetable.", "lunch_b": "Grilled, lower-mercury fish (cooked through) with rice and a cooked vegetable.", "nourishment_break_a": "A boiled egg (cooked through).", "nourishment_break_b": "Milk with a small handful of roasted peanuts.", "dinner_a": "Tofu or soy-keema with roti and a bowl of curd.", "dinner_b": "The same, with a fully cooked chicken curry alongside.", "still_hungry": "Roasted makhana."}, {"day_number": 3, "title": "Where choline naturally shows up", "notes": "Today: Egg yolk is one of the most concentrated choline sources available, and meat, poultry, and fish also contribute meaningfully. Plant sources — soybeans, other legumes, peanuts, cauliflower, and whole grains — provide smaller but genuinely useful amounts, especially combined across a day.", "breakfast_a": "Vegetable paratha with a small bowl of curd.", "breakfast_b": "An egg-and-vegetable roti roll, with a small bowl of curd.", "lunch_a": "Chana curry with rice or roti, according to appetite, and a green peas-and-potato sabzi.", "lunch_b": "Home-style chicken pulao with a thoroughly washed, freshly prepared salad.", "nourishment_break_a": "Roasted peanuts.", "nourishment_break_b": "Curd with roasted soybeans or peanuts.", "dinner_a": "Broccoli-and-potato sabzi with roti and a bowl of dal.", "dinner_b": "The same sabzi and roti, with a fully cooked, lower-mercury fish dish alongside.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Building choline with vegetarian foods", "notes": "Today: If you don''t eat eggs, meat, or fish, meaningful choline can still come from combining soybeans, other legumes, peanuts, dairy, and cruciferous vegetables like cauliflower or cabbage across the day — it takes a bit more deliberate combining than relying on egg yolk alone, but it adds up. Choose A for an egg-free meal or B if you include eggs. Vegetarian meals can contribute useful choline through soy, beans, dairy, peanuts and vegetables. Because these foods generally provide less choline per serving than eggs, regularly combining several sources across the day matters.", "breakfast_a": "Soy milk with oats or muesli, and a small handful of peanuts.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside.", "lunch_a": "Chana-and-vegetable curry with rice or roti, according to appetite, and a green peas sabzi.", "lunch_b": "The same curry, with a boiled egg (cooked through) alongside.", "nourishment_break_a": "Roasted soybeans.", "nourishment_break_b": "Paneer cubes with a small handful of peanuts.", "dinner_a": "Mixed dal with cauliflower sabzi and roti.", "dinner_b": "The same dal and sabzi, with egg curry (cooked through) alongside.", "still_hungry": "A piece of fruit."}, {"day_number": 5, "title": "Away from home", "notes": "Today: A dal, legume, or paneer-based dish, or an egg or meat dish if that''s what''s available, both genuinely contribute to a day''s choline — nothing special needs to be arranged.", "breakfast_a": "Idli or dosa with sambar, or poha with peanuts.", "breakfast_b": "The same, with a boiled egg (cooked through) alongside if it''s available.", "lunch_a": "A dal, chana, or paneer-based thali item with rice or roti, according to appetite.", "lunch_b": "A fully cooked chicken or egg dish with rice or roti, plus a cooked vegetable or thoroughly washed salad.", "nourishment_break_a": "A small packet of roasted peanuts or chana, if available.", "nourishment_break_b": "Curd or buttermilk, if available.", "dinner_a": "A family meal containing dal, beans, paneer, tofu, or soy.", "dinner_b": "A family meal containing a fully cooked egg, chicken, or fish dish.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "More isn''t the goal", "notes": "Today: Some research using higher intakes than the standard reference amount has found modest benefits for infant attention and processing speed, but the wider body of research on choline and child development remains mixed. Ordinary, food-based amounts near the standard reference are a reasonable goal — not a reason to chase a research-study amount through a supplement on your own. Not every prenatal supplement contains choline, and those that do may contain only a small amount. You can check your label to see whether choline is included. If you take a separate choline supplement, more isn''t automatically better — check with your maternity team before adding one beyond your usual diet and prenatal supplement.", "breakfast_a": "Vegetable upma with a small bowl of curd.", "breakfast_b": "A masala omelette (cooked through), with a small bowl of curd.", "lunch_a": "Rajma curry with rice or roti, according to appetite, and a green peas sabzi.", "lunch_b": "Tomato-capsicum egg bhurji (cooked through) with roti and a cooked vegetable.", "nourishment_break_a": "Roasted chana.", "nourishment_break_b": "Milk with roasted chana.", "dinner_a": "Chana curry with roti and a bowl of curd.", "dinner_b": "Chicken-and-vegetable stew with roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how often eggs, legumes, and a few vegetables already carry choline, quietly supporting your baby''s developing brain and nervous system, is worth a quick look back. Ordinary meals can contribute choline, but intake varies considerably — especially when eggs, meat, and fish are not eaten. Regularly including several choline-containing foods matters more than making any one meal perfect.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Had you heard of choline before this week? Did anything about its connection to folate, or to the egg you may already be having most mornings, surprise you?',
   'Next week, we''ll look at omega-3 fats — another nutrient with a direct role in your baby''s brain and eye development.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 23: Omega-3 Fats & DHA
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   23,
   'second',
   NULL,
   'Omega-3 Fats & DHA',
   '"Small, steady choices — a spoon of flaxseed, a handful of walnuts, a sardine curry — building your baby''s brain and eyes, one meal at a time."',
   'DHA, a type of omega-3 fat, is a building block for your baby''s brain and retina — the cell membranes there are especially rich in it. Your body converts only a small share of plant-based omega-3 (ALA, found in flaxseed, walnuts, chia, soy, and canola oil) into DHA, so getting some DHA more directly — mainly from appropriately chosen fish, with smaller and variable amounts from eggs — is worth doing alongside plant sources, not instead of them. Your baby''s DHA needs rise over the months ahead, especially in the third trimester, as brain and eye tissue accumulate this fat rapidly. ICMR-NIN''s 2020 guidelines set a general adult requirement of 2.2 g/day of total omega-3 fat, but don''t set a pregnancy-specific figure or a DHA-specific target. International guidance uses 300 mg of combined EPA and DHA a day, including 200 mg DHA, as a pregnancy reference point; regular servings of appropriately chosen fish can contribute substantially toward this. Because seafood intake varies considerably, DHA may deserve some deliberate attention. If you eat meat, fish, or eggs: Fatty fish — sardines and other fish confirmed to be lower-mercury choices — are the most concentrated, direct DHA source, with eggs contributing smaller and variable amounts. If you eat fish, aim for roughly two to three servings a week, cooking it fully and varying the type where you can; sardines are specifically included in the FDA''s lower-mercury ''Best Choices'' group.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Today''s lunch pairs a direct-DHA option with a plant-based omega-3 option — both genuinely useful, for different purposes. Pick whichever suits you, or mix through the week.", "breakfast_a": "Vegetable poha with a small handful of walnuts (6–7 halves) mixed in.", "breakfast_b": "Masala omelette (cooked through) with a roti.", "lunch_a": "Plant omega-3 option: soybean curry with rice and a cooked vegetable.", "lunch_b": "Direct-DHA option: sardine curry (canned in tomato sauce or fresh, cooked through) with rice and a cooked vegetable.", "nourishment_break_a": "Roasted chana with a piece of fruit.", "nourishment_break_b": "Curd with a spoon of ground flaxseed stirred in.", "dinner_a": "Moong dal khichdi with a bowl of curd.", "dinner_b": "Chicken-and-vegetable stew with rice.", "still_hungry": "A familiar snack."}, {"day_number": 2, "title": "Where DHA naturally shows up", "notes": "Today: Lower-mercury fatty fish provides the most concentrated direct DHA. Eggs may contribute smaller and variable amounts, while chia, walnuts, soy, and canola oil provide ALA, which the body converts into DHA only in small amounts. Sardines and similar lower-mercury fish are a reliable direct-DHA choice — vary which fish you pick where you can, and always cook it through.", "breakfast_a": "Oats porridge with a tablespoon of chia seeds stirred in.", "breakfast_b": "Chicken sandwich (cooked through) with a side of fruit.", "lunch_a": "Plant omega-3 option: rajma curry, cooked in canola oil, with rice and a cooked vegetable.", "lunch_b": "Direct-DHA option: sardines or another fish confirmed to be a lower-mercury choice, grilled or pan-cooked (cooked through), with rice and a cooked vegetable.", "nourishment_break_a": "A small handful of walnuts (6–7 halves).", "nourishment_break_b": "A boiled egg (cooked through).", "dinner_a": "Mixed dal with a leafy-green sabzi and roti.", "dinner_b": "Chicken keema with a leafy-green sabzi and roti.", "still_hungry": "A piece of fruit."}, {"day_number": 3, "title": "Building your baby''s brain and eyes", "notes": "Today: Your baby''s brain and eyes will draw increasingly on DHA over the months ahead, especially in the third trimester — something to build toward now, not a need that peaks at this point in pregnancy. DHA builds up in the retina by birth, and in the brain through the first two years after birth.", "breakfast_a": "Vegetable upma with a small handful of walnuts on the side.", "breakfast_b": "Chicken-and-vegetable roll (cooked through).", "lunch_a": "Chana masala with rice and a cooked vegetable.", "lunch_b": "Egg curry (cooked through) with rice and a cooked vegetable.", "nourishment_break_a": "Roasted soybeans (a small handful).", "nourishment_break_b": "Curd with a spoon of ground flaxseed stirred in.", "dinner_a": "Palak paneer with roti.", "dinner_b": "Chicken curry with roti.", "still_hungry": "A piece of fruit."}, {"day_number": 4, "title": "Building omega-3s without fish", "notes": "Today: If you don''t eat fish, combining a few plant omega-3 foods across the day — and choosing eggs or other animal foods if you eat them — supports your intake, though it doesn''t fully replace a direct DHA source the way fish does. If you eat neither fish nor eggs, it''s worth raising with your maternity team, who may suggest an algae-based DHA supplement made without fish. Choose A for a vegetarian, fish-free meal, or B if you include eggs or other non-vegetarian foods — this day stays fish-free either way. Well-planned vegetarian diets can meet many nutrient needs, but DHA specifically is harder to reach through plant foods alone — that''s a genuine gap worth naming, not a sign you''re doing anything wrong.", "breakfast_a": "Chia-seed pudding made with pasteurized milk, soaked overnight in the refrigerator, served with fruit.", "breakfast_b": "Chia-seed pudding made with pasteurized milk, soaked overnight in the refrigerator, with a boiled egg (cooked through) on the side.", "lunch_a": "Edamame-and-vegetable stir-fry, cooked in canola oil, with rice.", "lunch_b": "Chicken-and-vegetable stir-fry, cooked in canola oil, with rice.", "nourishment_break_a": "Roasted soybeans with a piece of fruit.", "nourishment_break_b": "Curd with a spoon of ground flaxseed stirred in.", "dinner_a": "Rajma curry with rice.", "dinner_b": "Chicken curry with rice.", "still_hungry": "A piece of fruit."}, {"day_number": 5, "title": "Away from home", "notes": "Today: A dal, paneer, or vegetable dish travels well, and a fully cooked fish dish from a place you trust genuinely contributes to this week''s DHA — nothing special needs to be arranged. If a salad is part of your meal, choose one you know is thoroughly washed and freshly prepared, especially away from home. Worth knowing: Skip raw or lightly cooked fish preparations such as sushi or sashimi while pregnant, and avoid fish from unclear or unfamiliar sources — stick to fully cooked options from places you trust.", "breakfast_a": "Idli with sambar.", "breakfast_b": "Idli with sambar, and a boiled egg (cooked through) if available.", "lunch_a": "A simple thali with dal, a cooked vegetable, and rice or roti, from a place you trust.", "lunch_b": "A simple thali with a fully cooked chicken dish (or egg dish, if that''s what''s available), rice or roti, and a cooked vegetable, from a place you trust.", "nourishment_break_a": "A small handful of roasted nuts you''re carrying with you, or a piece of fruit.", "nourishment_break_b": "Curd or buttermilk, if available.", "dinner_a": "A freshly cooked paneer-and-vegetable dish, served hot.", "dinner_b": "Direct-DHA option: a fully cooked fish dish (grilled or in curry, not raw), from a restaurant you trust.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "More isn''t the goal", "notes": "Today: Not every prenatal supplement contains DHA — checking your label is enough, without needing to act on it urgently. Food-based sources plus your usual prenatal remain the starting point. If you''re considering a separate fish-oil or algae-based DHA supplement, check the amount already present in your prenatal first. Speak with your maternity team before adding one, particularly if you take warfarin or another blood-thinning medicine.", "breakfast_a": "Vegetable dalia with a small handful of walnuts stirred in.", "breakfast_b": "Masala omelette (cooked through) with a roti.", "lunch_a": "Chana masala with rice and a cooked vegetable.", "lunch_b": "Chicken-and-vegetable pulao.", "nourishment_break_a": "A small bowl of curd with a spoon of ground flaxseed stirred in.", "nourishment_break_b": "Roasted chana with a piece of fruit.", "dinner_a": "Moong dal khichdi with a bowl of curd.", "dinner_b": "Chicken curry with roti and a cooked vegetable.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how sardines, eggs, walnuts, and a spoon of flaxseed already carry omega-3s toward your baby''s brain and eyes is worth a quick look back. Lower-mercury fatty fish provides direct DHA, while walnuts, flaxseed, and other plant foods contribute ALA. Including the sources that suit your dietary pattern regularly matters more than making any one day perfect.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which of this week''s omega-3 sources — fish, eggs, walnuts, flaxseed — could you realistically fit into your routine most weeks? Is there one small swap you''d like to try?',
   'Next week, we''ll look at magnesium — a mineral that supports your muscles, sleep, and blood pressure as your body keeps adjusting.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 24: Magnesium
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   24,
   'second',
   NULL,
   'Magnesium',
   '"A handful of nuts, a bowl of dal, a leafy-green sabzi — small, ordinary choices that add up for your muscles, nerves and bones."',
   'Magnesium supports hundreds of reactions in the body, including those involved in muscle and nerve function, blood-glucose regulation, bone development, and DNA production. ICMR-NIN''s 2020 guidelines set the general adult RDA for women at 370 mg/day, with no separate pregnancy-specific figure. For international context, the US pregnancy RDA is 350 mg/day for adults aged 19–30 and 360 mg/day for adults aged 31–50. Many useful magnesium sources are plant foods — leafy greens, legumes, nuts, seeds, and whole grains. Regularly including several of these foods can help intake add up across the day. If you eat meat, fish, or eggs: Many useful magnesium sources are plant foods — leafy greens, legumes, nuts, seeds, and whole grains — with meat, fish, and eggs generally contributing smaller amounts. Regularly including several of these plant foods, alongside whichever protein choices suit you, can help intake add up across the day.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Magnesium supports muscle and nerve function, blood sugar regulation, and bone health — small amounts spread across many ordinary foods, not concentrated in any one dish.", "breakfast_a": "Vegetable oats porridge with a small handful of almonds.", "breakfast_b": "Vegetable oats porridge with a small handful of almonds, and a boiled egg (cooked through) alongside.", "lunch_a": "Rajma curry with brown rice and a cooked leafy-green sabzi.", "lunch_b": "Chicken-and-vegetable stew with brown rice and a cooked leafy-green sabzi.", "nourishment_break_a": "A small handful of pumpkin seeds and peanuts.", "nourishment_break_b": "A small bowl of curd with a small handful of pumpkin seeds or peanuts.", "dinner_a": "Mixed dal with whole-wheat roti and a cooked vegetable.", "dinner_b": "Egg-and-spinach roti roll (egg cooked through).", "still_hungry": "A banana."}, {"day_number": 2, "title": "Where magnesium naturally shows up", "notes": "Today: Leafy greens, legumes, nuts, seeds, and whole grains are magnesium''s best sources. Refining grains removes much of the bran and germ where magnesium is concentrated, so whole-wheat, brown rice, and other whole grains generally contain more than their refined versions.", "breakfast_a": "Ragi (finger millet) porridge with pasteurized milk; add fruit or a small amount of jaggery if desired.", "breakfast_b": "Ragi (finger millet) porridge with pasteurized milk, and a boiled egg (cooked through) alongside.", "lunch_a": "Palak (spinach) dal with whole-wheat roti.", "lunch_b": "Palak (spinach) chicken curry with whole-wheat roti.", "nourishment_break_a": "A small handful of cashews and chia seeds.", "nourishment_break_b": "Curd with a small handful of cashews or pumpkin seeds.", "dinner_a": "Brown-rice vegetable pulao with a bowl of curd.", "dinner_b": "Brown-rice chicken-and-vegetable pulao with a bowl of curd.", "still_hungry": "A piece of fruit."}, {"day_number": 3, "title": "Muscles and nerve function", "notes": "Today: Magnesium plays a role in muscle relaxation and nerve signalling. Magnesium supplements are sometimes promoted for pregnancy leg cramps, but studies have produced conflicting results. Do not assume that cramps mean you need more magnesium or start a separate supplement solely for this reason.", "breakfast_a": "Vegetable besan chilla with a small bowl of curd.", "breakfast_b": "Vegetable besan chilla with a boiled egg (cooked through) alongside.", "lunch_a": "Chana masala with whole-wheat roti and a cooked leafy-green sabzi.", "lunch_b": "Chicken curry with whole-wheat roti and a cooked leafy-green sabzi.", "nourishment_break_a": "A small handful of almonds and pumpkin seeds.", "nourishment_break_b": "A glass of milk with a small handful of almonds or pumpkin seeds.", "dinner_a": "Moong dal khichdi with a bowl of curd.", "dinner_b": "Moong dal with roti, and chicken keema with peas alongside.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Whole grains over refined", "notes": "Today: Refining grains — turning whole wheat into maida, or brown rice into white rice — removes much of the bran and germ where magnesium is concentrated. Choosing whole-grain versions where you can, most days, is a simple way to build this in without changing what you eat.", "breakfast_a": "Vegetable daliya (broken wheat) upma.", "breakfast_b": "Vegetable daliya (broken wheat) upma with a boiled egg (cooked through) alongside.", "lunch_a": "Bajra (pearl millet) khichdi with a cooked leafy-green vegetable and a bowl of curd.", "lunch_b": "Chicken-and-vegetable stew with bajra roti and a cooked leafy-green vegetable.", "nourishment_break_a": "Roasted makhana (fox nuts) with a few cashews.", "nourishment_break_b": "Curd with a small handful of cashews or roasted seeds.", "dinner_a": "Whole-wheat roti with mixed dal and a cooked leafy-green vegetable.", "dinner_b": "Whole-wheat roti with chicken curry and a cooked leafy-green vegetable.", "still_hungry": "A piece of fruit."}, {"day_number": 5, "title": "Away from home", "notes": "Today: A simple thali, a dal-and-roti meal, or a legume-based dish all genuinely contribute to today''s magnesium — nothing special needs to be arranged when you''re out. If a salad is part of your meal, choose one you know is thoroughly washed and freshly prepared, especially away from home.", "breakfast_a": "Idli with sambar.", "breakfast_b": "Idli with sambar, and a boiled egg (cooked through) if available.", "lunch_a": "A simple thali with dal, a cooked vegetable, and rice or roti, from a place you trust.", "lunch_b": "A simple thali with a fully cooked chicken or egg dish, dal, a cooked vegetable, and rice or roti, from a place you trust.", "nourishment_break_a": "A small handful of roasted nuts you''re carrying with you, or a piece of fruit.", "nourishment_break_b": "Curd or buttermilk with a small packet of roasted peanuts or chana, if available.", "dinner_a": "A freshly cooked dal-and-vegetable dish, served hot.", "dinner_b": "A freshly cooked chicken or egg dish, served hot, with dal or a cooked leafy-green vegetable alongside.", "still_hungry": "An extra roti, or a familiar snack."}, {"day_number": 6, "title": "More isn''t the goal", "notes": "Today: Magnesium naturally present in food is not known to cause harm in healthy people. Excess intake is more likely to come from high-dose supplements or magnesium-containing medicines, which can cause diarrhoea, nausea, or abdominal cramping. If you''re considering a separate magnesium supplement, check your prenatal label first. Ask your maternity team or pharmacist before adding one if you take regular medication — especially certain antibiotics or medicines that affect magnesium levels.", "breakfast_a": "Vegetable poha with a small handful of peanuts.", "breakfast_b": "Vegetable poha with a small handful of peanuts, and a masala omelette (cooked through) alongside.", "lunch_a": "Chana masala with whole-wheat roti and a cooked leafy-green vegetable.", "lunch_b": "Egg curry (cooked through) with whole-wheat roti and a cooked leafy-green vegetable.", "nourishment_break_a": "A small bowl of curd with a few almonds.", "nourishment_break_b": "A boiled egg (cooked through) with a small handful of peanuts.", "dinner_a": "Mixed dal with roti and a cooked leafy-green vegetable.", "dinner_b": "Fish curry (cooked through, a lower-mercury choice) with roti and a cooked leafy-green vegetable.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how a handful of nuts, a bowl of dal, or a leafy-green sabzi already carry magnesium toward your muscles, nerves, and bones is worth a quick look back. Magnesium is spread across many ordinary foods. Regularly including a mixture of legumes, nuts or seeds, leafy greens, and whole grains matters more than relying on any single ingredient.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which of this week''s magnesium sources — dal, nuts, seeds, leafy greens, whole grains — are already part of your regular week? Is there one small swap, like whole-wheat roti or a millet dish, you''d want to keep?',
   'Next week, we''ll look at calcium — a mineral that works closely with magnesium and vitamin D to build your baby''s bones and keep your own strong.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 25: Iodine
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   25,
   'second',
   NULL,
   'Iodine',
   '"The iodized salt already in your everyday cooking — one part of what keeps your thyroid, and your baby''s, working the way they should."',
   'Iodine helps your thyroid make the hormones that regulate your metabolism and support your baby''s brain and skeletal development. ICMR-NIN lists 150 mcg/day as its general adult RDA; international pregnancy references are higher — 220 mcg/day under the US RDA and 250 mcg/day under WHO guidance. Iodized salt can be an important everyday source, alongside foods such as dairy, eggs, and seafood. This does not mean using extra salt: use iodized salt in your normal cooking amount, and check before adding a separate iodine supplement. If you eat meat, fish, or eggs: Iodine doesn''t split sharply along vegetarian and non-vegetarian lines the way some nutrients do — iodized salt is an important everyday source for everyone, and dairy, eggs, and seafood each add a little more on top of that. Using iodized salt as your normal cooking salt, alongside whichever protein choices suit you, is what matters most this week — not any one specific food.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Iodine helps your thyroid make the hormones that regulate your metabolism and support your baby''s brain and skeletal development. Iodized salt can be an important everyday source, alongside foods such as dairy, eggs, and seafood — used in your normal cooking amount, not extra.", "breakfast_a": "Vegetable poha, cooked with iodized salt, with a glass of pasteurized milk.", "breakfast_b": "Vegetable poha, cooked with iodized salt, with a boiled egg (cooked through) alongside.", "lunch_a": "Rajma curry with whole-wheat roti and a bowl of curd, cooked with iodized salt.", "lunch_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with whole-wheat roti, cooked with iodized salt.", "nourishment_break_a": "A glass of buttermilk (chaas).", "nourishment_break_b": "A small bowl of curd with a small handful of peanuts.", "dinner_a": "Mixed dal with whole-wheat roti and a cooked vegetable, cooked with iodized salt.", "dinner_b": "Chicken curry with whole-wheat roti and a cooked vegetable, cooked with iodized salt.", "still_hungry": "A glass of pasteurized milk."}, {"day_number": 2, "title": "Where iodine naturally shows up", "notes": "Today: Iodized salt can be an important everyday source of iodine, alongside foods like dairy, eggs, and seafood — but how much it actually contributes depends on things like how well the salt was iodized, how it''s stored, and how much you normally use in cooking. This isn''t a reason to add extra salt, just to use iodized salt as your normal choice and let these other foods help fill in the rest.", "breakfast_a": "Idli with sambar, cooked with iodized salt, and a glass of pasteurized milk.", "breakfast_b": "Idli with sambar, cooked with iodized salt, and a boiled egg (cooked through) alongside.", "lunch_a": "Curd rice with a cooked vegetable, cooked with iodized salt.", "lunch_b": "Prawn curry (cooked through) with rice and a cooked vegetable, cooked with iodized salt.", "nourishment_break_a": "A small handful of roasted chana (chickpeas).", "nourishment_break_b": "A piece of fruit with a small handful of peanuts or roasted chana.", "dinner_a": "Paneer-and-vegetable curry with whole-wheat roti, cooked with iodized salt.", "dinner_b": "Chicken-and-vegetable keema with whole-wheat roti, cooked with iodized salt.", "still_hungry": "A glass of buttermilk (chaas)."}, {"day_number": 3, "title": "How you store and cook your salt matters too", "notes": "Today: Some iodine can be lost through prolonged heating and unsuitable storage. Keep iodized salt in an airtight container, away from direct sunlight, heat, and steam, and add it toward the end of cooking — especially in dishes that cook for a long time.", "breakfast_a": "Vegetable daliya (broken wheat) upma, salt added toward the end of cooking, with a glass of pasteurized milk.", "breakfast_b": "Vegetable daliya (broken wheat) upma, salt added toward the end of cooking, with a boiled egg (cooked through) alongside.", "lunch_a": "Chana masala with whole-wheat roti, salt added toward the end of cooking.", "lunch_b": "Chicken-and-vegetable stew with whole-wheat roti, salt added toward the end of cooking.", "nourishment_break_a": "A small handful of roasted peanuts.", "nourishment_break_b": "A small bowl of curd with a small handful of roasted peanuts.", "dinner_a": "Vegetable khichdi with a bowl of curd, salt added toward the end of cooking.", "dinner_b": "Chicken khichdi with a bowl of curd, salt added toward the end of cooking.", "still_hungry": "A piece of fruit."}, {"day_number": 4, "title": "Your baby''s own thyroid, now working alongside yours", "notes": "Today: Earlier in pregnancy, before your baby''s thyroid developed sufficiently, they depended entirely on thyroid hormone supplied by you. By mid-pregnancy, the baby''s thyroid has begun producing its own hormone — but iodine remains necessary for that production, and your thyroid health continues to matter throughout pregnancy.", "breakfast_a": "Vegetable besan chilla, cooked with iodized salt, with a glass of pasteurized milk.", "breakfast_b": "Vegetable besan chilla, cooked with iodized salt, and a boiled egg (cooked through) alongside.", "lunch_a": "Mixed dal with whole-wheat roti and a cooked leafy-green vegetable, cooked with iodized salt.", "lunch_b": "Chicken-and-vegetable curry with whole-wheat roti, cooked with iodized salt.", "nourishment_break_a": "A glass of buttermilk (chaas) with a small handful of almonds.", "nourishment_break_b": "A small bowl of curd with a small handful of almonds.", "dinner_a": "Bajra (pearl millet) khichdi with a bowl of curd, cooked with iodized salt.", "dinner_b": "Chicken-and-bottle-gourd curry with bajra roti, cooked with iodized salt.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Checking your own kitchen''s salt", "notes": "Today: India requires common edible salt sold for human consumption to be iodized, but the amount that finally reaches the plate can still vary with the product, storage, and cooking. Check the packet once to make sure it says \"iodized salt\" or \"double-fortified salt,\" and store it tightly closed, away from sunlight, heat, and steam.", "breakfast_a": "Vegetable oats porridge, cooked with iodized salt, with a glass of pasteurized milk.", "breakfast_b": "Vegetable oats porridge, cooked with iodized salt, and a boiled egg (cooked through) alongside.", "lunch_a": "Vegetable pulao with kala chana and cucumber raita, cooked with iodized salt.", "lunch_b": "Lower-mercury fish (such as sardines, cooked through) with rice and a cooked vegetable, cooked with iodized salt.", "nourishment_break_a": "A small bowl of curd with a few almonds.", "nourishment_break_b": "A glass of buttermilk (chaas) with a small handful of peanuts.", "dinner_a": "Lauki-chana dal with rice or roti, cooked with iodized salt.", "dinner_b": "Chicken-and-vegetable pulao, cooked with iodized salt.", "still_hungry": "A glass of pasteurized milk."}, {"day_number": 6, "title": "More isn''t the goal", "notes": "Today: The iodine already in an ordinary diet with iodized salt is not a safety concern. Very large, concentrated amounts — particularly from kelp or seaweed supplements — can disrupt thyroid function rather than help it. Do not deliberately add extra iodine on your own; check your prenatal label and ask your maternity team if you are unsure whether it provides iodine. If you are considering a separate iodine or seaweed supplement, check your prenatal label first. Some prenatals contain iodine and some do not, and the amount can vary. Do not add a separate iodine or kelp supplement without guidance from your maternity team. If this applies to you (thyroid): Both too little and too much iodine can affect thyroid function. If you have a thyroid condition or take thyroid medicine, do not deliberately increase or restrict iodine, change your usual salt intake, or add kelp or iodine supplements on your own. Continue the plan already given by your maternity or thyroid-care team.", "breakfast_a": "Vegetable uttapam, cooked with iodized salt, with a bowl of curd.", "breakfast_b": "Vegetable uttapam, cooked with iodized salt, and a boiled egg (cooked through) alongside.", "lunch_a": "Lobia (black-eyed pea) curry with rice and a cooked vegetable, cooked with iodized salt.", "lunch_b": "Chicken-and-lobia curry with rice and a cooked vegetable, cooked with iodized salt.", "nourishment_break_a": "A small bowl of curd.", "nourishment_break_b": "A glass of buttermilk (chaas) with a small handful of peanuts.", "dinner_a": "Palak (spinach) dal with whole-wheat roti, cooked with iodized salt.", "dinner_b": "Chicken-and-spinach curry with whole-wheat roti, cooked with iodized salt.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing that the iodized salt already in your everyday cooking, alongside dairy, eggs, and seafood, is quietly contributing to this is worth a quick look back. Iodine depends heavily on one steady habit — cooking with iodized salt, stored well — alongside the smaller, steady contributions from dairy, eggs, and seafood across your week.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Do you know whether the salt used in your home cooking is iodized? Is there one small habit — storing it well, adding it later in cooking — worth starting this week?',
   'Next week, we''ll look at vitamin B12 — an essential nutrient for every mother, and one that deserves particular attention when little or no animal food is eaten.')
