-- pregnancy week 26: Vitamin B12
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   26,
   'second',
   NULL,
   'Vitamin B12',
   '"Nerve and blood-cell health you can''t see happening — but real, and worth understanding, especially if you eat little or no animal food."',
   'Vitamin B12 supports healthy nerve cells and red-blood-cell formation, helps your body make DNA, and helps prevent megaloblastic anaemia. ICMR-NIN lists 2.2 mcg/day as its general adult RDA. For pregnancy, the US RDA is 2.6 mcg/day. If you eat meat, fish, or eggs: This is one of the more animal-concentrated nutrients in this series — B12 occurs naturally only in meat, fish, eggs, and dairy, not in plant foods. Dairy and eggs are useful sources, but their B12 content and the amount you actually eat both vary, so this week''s meals illustrate possible B12-containing choices rather than guaranteeing that any single combination meets the full pregnancy requirement. If you eat no animal food: Ordinary plant foods do not reliably provide vitamin B12. Check whether your prenatal contains B12 and use only packaged foods whose labels confirm B12 fortification. Fortified plant milk can replace dairy milk where suitable, but tofu, pulses, nuts, vegetables, and unfortified plant milk should not be counted as B12 sources. Because B12 needs can be difficult to meet without animal foods or reliably fortified products, a supplement may be necessary. Ask your maternity team whether your prenatal provides enough or whether you need something additional.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Vitamin B12 supports healthy nerve cells and red-blood-cell formation, helps your body make DNA, and helps prevent megaloblastic anaemia. ICMR-NIN lists 2.2 mcg/day as its general adult RDA. For pregnancy, the US RDA is 2.6 mcg/day.", "breakfast_a": "Vegetable poha with a glass of pasteurized milk.", "breakfast_b": "Vegetable poha with a glass of pasteurized milk, and a boiled egg (cooked through) alongside.", "lunch_a": "Paneer-and-vegetable curry with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken curry with whole-wheat roti and a bowl of curd.", "nourishment_break_a": "A glass of buttermilk (chaas).", "nourishment_break_b": "A small bowl of curd with a small handful of peanuts.", "dinner_a": "Mixed dal with whole-wheat roti and a bowl of curd.", "dinner_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with whole-wheat roti.", "still_hungry": "A glass of pasteurized milk."}, {"day_number": 2, "title": "Where B12 naturally shows up", "notes": "Today: Unlike most nutrients in this series, vitamin B12 occurs naturally only in animal foods — meat, fish, eggs, and dairy. Plant foods do not naturally provide reliable vitamin B12. Some packaged plant milks, breakfast cereals, nutritional yeasts, and other products are fortified with it — but fortification varies, so the label must specifically list vitamin B12. This makes B12 genuinely different from a nutrient you can build entirely from plant foods by combining well across the day.", "breakfast_a": "Besan (chickpea flour) chilla with a glass of pasteurized milk.", "breakfast_b": "Besan (chickpea flour) chilla with a boiled egg (cooked through) alongside.", "lunch_a": "Curd rice with a cooked vegetable.", "lunch_b": "Chicken-and-vegetable stew with rice and a cooked vegetable.", "nourishment_break_a": "A small bowl of curd.", "nourishment_break_b": "A small bowl of curd with a small handful of almonds.", "dinner_a": "Paneer bhurji with whole-wheat roti.", "dinner_b": "Chicken roti roll (cooked through) with a bowl of curd.", "still_hungry": "A glass of buttermilk (chaas)."}, {"day_number": 3, "title": "A common, well-documented gap in India", "notes": "Today: Indian studies have reported a high but widely varying prevalence of low B12 during pregnancy, often between 40% and 70% in the populations studied. These figures don''t mean every pregnant mother is deficient, because study groups, laboratory cut-offs, and pregnancy-related blood changes differ. If you eat little or no animal food, have anaemia or neurological symptoms, have a condition that affects absorption, or use certain medicines long term, ask your maternity team whether B12 assessment is appropriate for you.", "breakfast_a": "Ragi (finger millet) porridge with pasteurized milk.", "breakfast_b": "Ragi (finger millet) porridge with pasteurized milk, and a boiled egg (cooked through) alongside.", "lunch_a": "Rajma curry with whole-wheat roti and a bowl of curd.", "lunch_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with whole-wheat roti and a bowl of curd.", "nourishment_break_a": "A glass of pasteurized milk.", "nourishment_break_b": "Coconut water with a small handful of peanuts.", "dinner_a": "Palak (spinach) paneer with whole-wheat roti.", "dinner_b": "Chicken tikka (cooked through) with whole-wheat roti and a cooked leafy-green vegetable.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Working alongside folate", "notes": "Today: B12 and folate (Week 10''s topic) work together in important metabolic processes. Low maternal B12 has been associated with a higher risk of neural-tube defects, although much of this evidence is observational and neural-tube closure occurs very early in pregnancy, often before you knew you were pregnant. At Week 26, the clearest focus is B12''s continuing role in your own nervous system, blood-cell formation, and your baby''s development.", "breakfast_a": "Vegetable daliya (broken wheat) upma with a glass of pasteurized milk.", "breakfast_b": "Vegetable daliya (broken wheat) upma with a glass of pasteurized milk, and a boiled egg (cooked through) alongside.", "lunch_a": "Chana masala with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken-and-vegetable keema with whole-wheat roti and a bowl of curd.", "nourishment_break_a": "A piece of fruit with a small handful of walnuts or almonds.", "nourishment_break_b": "A glass of buttermilk (chaas) with a small handful of peanuts.", "dinner_a": "Chana dal with whole-wheat roti and a bowl of curd.", "dinner_b": "Chicken-and-peas curry with whole-wheat roti.", "still_hungry": "A piece of fruit."}, {"day_number": 5, "title": "Building toward feeding your baby, too", "notes": "Today: If you plan to breastfeed, your own B12 stores matter beyond pregnancy. A baby who is exclusively breastfed by a mother with untreated B12 deficiency — whether caused by very low intake or difficulty absorbing B12 — can develop deficiency during infancy, since their reserves at birth are limited. Making sure your own B12 intake and status are adequate now is part of preparing for that stretch too.", "breakfast_a": "Idli with sambar and a glass of pasteurized milk.", "breakfast_b": "Idli with sambar, and a boiled egg (cooked through) alongside.", "lunch_a": "Vegetable pulao with a bowl of curd.", "lunch_b": "Chicken-and-vegetable pulao with a bowl of curd.", "nourishment_break_a": "A glass of pasteurized milk.", "nourishment_break_b": "A small bowl of curd with a small handful of walnuts.", "dinner_a": "Moong dal khichdi with a bowl of curd.", "dinner_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with rice.", "still_hungry": "A glass of buttermilk (chaas)."}, {"day_number": 6, "title": "Under-intake is the real risk here", "notes": "Today: No tolerable upper limit has been established for vitamin B12 because it is generally considered to have low toxicity. That does not mean higher doses are always more useful. For most people, the practical concern is getting too little rather than too much. If your diet contains little or no animal food, check your prenatal label and follow the supplement amount recommended for your situation — food first doesn''t fully apply to everyone with this particular nutrient. If this applies to you (metformin): Metformin can reduce B12 absorption, particularly when it has been used for a longer period. Do not stop or change your medicine. If you were taking metformin before pregnancy, eat little or no animal food, have anaemia, or have symptoms that could suggest deficiency, mention this to your maternity team so they can decide whether testing is appropriate.", "breakfast_a": "Vegetable oats porridge with a glass of pasteurized milk.", "breakfast_b": "Vegetable oats porridge with a glass of pasteurized milk, and a boiled egg (cooked through) alongside.", "lunch_a": "Lobia (black-eyed pea) curry with rice and a bowl of curd.", "lunch_b": "Chicken-and-lobia curry with rice and a cooked vegetable.", "nourishment_break_a": "A piece of fruit with a small handful of roasted chana.", "nourishment_break_b": "A glass of buttermilk (chaas) with a small handful of peanuts.", "dinner_a": "Palak (spinach) dal with whole-wheat roti and a bowl of curd.", "dinner_b": "Chicken-and-drumstick (moringa) curry with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how much of B12 depends on dairy, eggs, meat, or fish — and how differently that lands depending on what you eat — is worth a quick look back. If you eat dairy or eggs regularly, they''re genuinely useful sources. If you eat little or no animal food at all, this is one nutrient worth asking your maternity team about directly, rather than assuming food alone will cover it.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'How much dairy, eggs, meat, or fish do you eat in a typical week? If it''s very little or none, has anyone checked your B12 levels or talked with you about a supplement?',
   'Next week, we''ll look at potassium — a mineral that works alongside sodium to support healthy blood pressure and muscle function.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
