-- pregnancy week 27: Potassium
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   27,
   'second',
   NULL,
   'Potassium',
   '"An orange, a guava, a boiled potato — the steady, everyday partner to Week 15''s ''right salt, not more salt.''"',
   'Potassium supports normal nerve signalling, muscle contraction, and heart and kidney function. It also forms part of a dietary pattern that supports healthy blood pressure alongside moderate sodium intake. The US pregnancy Adequate Intake is 2900 mg per day for adults aged 19-50 and 2600 mg per day for pregnant adolescents. This is a reference level, not a number that needs to be calculated every day or reached through supplements. If you eat meat, fish, or eggs: Potassium doesn''t split sharply along vegetarian or non-vegetarian lines — fruits and vegetables are its richest everyday sources, and meat, fish, and dairy contribute some too. A genuine variety of fruits and vegetables across your week matters more than any particular protein choice.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Potassium supports normal nerve signalling, muscle contraction, and heart and kidney function. It also forms part of a dietary pattern that supports healthy blood pressure alongside moderate sodium intake. The US pregnancy Adequate Intake is 2900 mg per day for adults aged 19-50 and 2600 mg per day for pregnant adolescents. This is a reference level, not a number that needs to be calculated every day or reached through supplements.", "breakfast_a": "Vegetable poha with a whole orange.", "breakfast_b": "Vegetable poha with a whole orange, and a boiled egg (cooked through) alongside.", "lunch_a": "Rajma curry with rice and a cooked spinach sabzi.", "lunch_b": "Chicken curry with rice and a cooked spinach sabzi.", "nourishment_break_a": "A banana.", "nourishment_break_b": "A small bowl of curd with a banana.", "dinner_a": "Mixed dal with whole-wheat roti and a thoroughly washed potato sabzi, with the skin left on if preferred.", "dinner_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with whole-wheat roti and a thoroughly washed potato sabzi, with the skin left on if preferred.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where potassium naturally shows up", "notes": "Today: Fruits and vegetables are potassium''s richest everyday sources — oranges, dried apricots, potatoes, spinach, tomatoes. Coconut water is a genuinely good Indian source too. Meat, fish, and dairy contribute some as well, so this doesn''t split sharply along vegetarian or non-vegetarian lines — a diet built around a variety of fruits and vegetables naturally does well here, whatever else is on the plate. If this applies to you (monitoring your blood glucose): Choose whole fruit more often than juice, and fit dried fruit or coconut water into the carbohydrate plan your maternity team has given you.", "breakfast_a": "Vegetable daliya (broken wheat) upma with a glass of coconut water.", "breakfast_b": "Vegetable daliya (broken wheat) upma with a glass of coconut water, and a boiled egg (cooked through) alongside.", "lunch_a": "Curd rice with a cooked tomato-and-vegetable sabzi.", "lunch_b": "Chicken-and-vegetable stew with rice and a cooked tomato-and-vegetable sabzi.", "nourishment_break_a": "Dried apricots with a small handful of peanuts.", "nourishment_break_b": "A small bowl of curd with dried apricots.", "dinner_a": "Palak (spinach) dal with whole-wheat roti.", "dinner_b": "Chicken-and-spinach curry with whole-wheat roti.", "still_hungry": "A guava."}, {"day_number": 3, "title": "Working alongside sodium", "notes": "Today: Potassium and sodium work as a team in regulating blood pressure. Eating more potassium-rich fruits and vegetables is a genuinely useful complement to Week 15''s ''the right salt, not more salt'' — but it''s an addition, not a substitute for keeping salt moderate.", "breakfast_a": "Idli with sambar and a banana.", "breakfast_b": "Idli with sambar and a banana, with one fully cooked egg alongside.", "lunch_a": "Chana masala with whole-wheat roti and a cooked tomato-and-vegetable sabzi.", "lunch_b": "Chicken-and-vegetable keema with whole-wheat roti and a cooked tomato-and-vegetable sabzi.", "nourishment_break_a": "A guava.", "nourishment_break_b": "A small bowl of curd with a small handful of almonds.", "dinner_a": "Vegetable khichdi with a cooked pumpkin sabzi.", "dinner_b": "Chicken khichdi with a cooked pumpkin sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Ongoing muscle and nerve support", "notes": "Today: Potassium''s role in muscle contraction and nerve signalling continues throughout pregnancy, alongside calcium (Week 9) and magnesium (Week 16) in that same broad picture. This isn''t a nutrient with a single dramatic story — it''s a steady, everyday contributor, best built from a genuine variety of fruits and vegetables rather than any one food.", "breakfast_a": "Besan (chickpea flour) chilla with a whole orange.", "breakfast_b": "Besan (chickpea flour) chilla with a whole orange, with one fully cooked egg alongside.", "lunch_a": "Mixed dal with whole-wheat roti and a cooked leafy-green vegetable.", "lunch_b": "Chicken-and-vegetable pulao with a cooked leafy-green vegetable.", "nourishment_break_a": "A small handful of walnuts with dried apricots.", "nourishment_break_b": "A small bowl of curd with a small handful of walnuts.", "dinner_a": "Vegetable-and-tomato curry with whole-wheat roti.", "dinner_b": "Chicken-and-tomato curry with whole-wheat roti.", "still_hungry": "A piece of fruit."}, {"day_number": 5, "title": "Away from home", "notes": "Today: An orange, a guava, or a simple potato-and-vegetable dish are all easy, portable, or widely available potassium sources — nothing special needs to be arranged when you''re out. If a salad is part of your meal, choose one you know is thoroughly washed and freshly prepared, especially away from home.", "breakfast_a": "Vegetable oats porridge with a guava or other seasonal fruit.", "breakfast_b": "Vegetable oats porridge with a guava or other seasonal fruit, and a boiled egg (cooked through) alongside.", "lunch_a": "A simple thali with dal, a cooked vegetable, and rice or roti, from a place you trust.", "lunch_b": "A simple thali with a fully cooked chicken dish, dal, a cooked vegetable, and rice or roti, from a place you trust.", "nourishment_break_a": "A piece of fruit you''re carrying with you.", "nourishment_break_b": "Buttermilk (chaas) with a small packet of roasted peanuts, if available.", "dinner_a": "A freshly cooked dal-and-vegetable dish, served hot.", "dinner_b": "A freshly cooked chicken dish, served hot, with dal or a cooked vegetable alongside.", "still_hungry": "An extra piece of fruit, or a familiar snack."}, {"day_number": 6, "title": "Who should be more careful here", "notes": "Today: For people with normal kidney function, potassium from ordinary foods is generally safe because the kidneys help regulate blood potassium levels. Potassium supplements and potassium-based salt substitutes are different because they can provide concentrated amounts. If you have kidney disease, have been told that your potassium is high, or take a medicine that affects potassium, do not deliberately increase or restrict potassium without medical guidance. If this applies to you (kidney disease or potassium-related medical advice): Follow the plan your maternity or medical team has given you. Do not start potassium supplements or potassium-based ''low-sodium'' salt substitutes on your own.", "breakfast_a": "Vegetable uttapam with ripe papaya or guava.", "breakfast_b": "Vegetable uttapam with ripe papaya or guava, and a boiled egg (cooked through) alongside.", "lunch_a": "Masoor dal with rice and a seasonal cooked vegetable.", "lunch_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with rice and a seasonal cooked vegetable.", "nourishment_break_a": "Fruit with a small handful of peanuts.", "nourishment_break_b": "Curd with a small handful of seeds (pumpkin or sunflower).", "dinner_a": "Pumpkin-and-moong dal with whole-wheat roti.", "dinner_b": "Chicken-and-drumstick (moringa) curry with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how an orange, a guava, a boiled potato, or a bowl of spinach dal already carry potassium toward your heart, muscles, and nerves is worth a quick look back. Potassium adds up across many ordinary fruits and vegetables. A genuine variety across your week matters more than any single food.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'How many different fruits and vegetables did you eat this week? Is there one easy addition — an orange, a guava, coconut water — worth keeping as a habit?',
   'Next week, we''ll look at vitamin A — a nutrient your baby needs in careful amounts, where both too little and too much matter.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
