-- pregnancy week 28: Vitamin A
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   28,
   'third',
   NULL,
   'Vitamin A',
   '"A carrot, a mango, a bowl of dal — vision, immunity, and your baby''s growth, with one important safety distinction."',
   'Vitamin A supports vision, immune function, and the health of skin and mucous membranes, and plays a role in your baby''s growth and eye development. The US pregnancy RDA is 770 mcg RAE per day for adults aged 19-50 and 750 mcg RAE per day for pregnant adolescents aged 14-18. This is a reference level, not a number that needs to be calculated meal by meal. This is a nutrient where both too little and too much matter, covered across this week. If you eat meat, fish, or eggs: Eggs, dairy, and fish can contribute vitamin A in ordinary food portions. A well-planned vegetarian diet can also meet vitamin A needs through a variety of colourful fruits, vegetables, and leafy greens. The one caution that applies regardless of how often you eat meat is liver and liver products, covered on Day 3.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Vitamin A supports vision, immune function, and the health of skin and mucous membranes, and plays a role in your baby''s growth and eye development. The US pregnancy RDA is 770 mcg RAE per day for adults aged 19-50 and 750 mcg RAE per day for pregnant adolescents aged 14-18. This is a reference level, not a number that needs to be calculated meal by meal. This is a nutrient where both too little and too much matter, covered across this week.", "breakfast_a": "Carrot-moong cheela with a bowl of curd.", "breakfast_b": "Carrot-moong cheela with a bowl of curd, and a boiled egg (cooked through) alongside.", "lunch_a": "Carrot-and-vegetable sabzi with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken curry with whole-wheat roti, a bowl of curd, and the same carrot-and-vegetable sabzi.", "nourishment_break_a": "A mango or papaya (in season).", "nourishment_break_b": "A mango or papaya (in season) with a small handful of peanuts.", "dinner_a": "Red-amaranth (chaulai) dal with whole-wheat roti and a cooked pumpkin sabzi.", "dinner_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with whole-wheat roti and a cooked pumpkin sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "The safe, plant-based route", "notes": "Today: Colourful fruits, vegetables, and leafy greens provide provitamin A carotenoids, including beta-carotene, which the body can convert into vitamin A. No upper limit has been established for beta-carotene naturally present in foods, so these foods can be included regularly as part of a varied diet.", "breakfast_a": "Sweet potato paratha with a bowl of curd.", "breakfast_b": "Sweet potato paratha with a bowl of curd, and a boiled egg (cooked through) alongside.", "lunch_a": "Carrot-and-peas pulao with a bowl of curd.", "lunch_b": "Chicken-and-vegetable pulao with a bowl of curd and a side of cooked carrots and peas.", "nourishment_break_a": "A sliced carrot with a small handful of peanuts.", "nourishment_break_b": "A sliced carrot with pasteurized buttermilk and a small handful of peanuts.", "dinner_a": "Drumstick-leaf (moringa) dal with rice.", "dinner_b": "Chicken-and-vegetable curry with rice and a side of the same drumstick-leaf (moringa) dal.", "still_hungry": "A guava."}, {"day_number": 3, "title": "Animal sources and the concentrated sources to avoid", "notes": "Today: Ordinary portions of eggs, dairy, fish, and meat can contribute vitamin A. Liver and liver products are different because they can contain very large amounts of preformed vitamin A, so they should be avoided during pregnancy. Do not take cod liver oil or add a vitamin A or retinol supplement unless it has been specifically recommended for you.", "breakfast_a": "Vegetable semiya (vermicelli) upma with papaya.", "breakfast_b": "Vegetable semiya (vermicelli) upma with papaya, and a boiled egg (cooked through) alongside.", "lunch_a": "Paneer-and-vegetable curry with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken-and-vegetable curry with whole-wheat roti and a bowl of curd.", "nourishment_break_a": "A small bowl of curd with a few almonds.", "nourishment_break_b": "A glass of buttermilk (chaas) with a small handful of peanuts.", "dinner_a": "Methi (fenugreek) dal with whole-wheat roti.", "dinner_b": "Chicken-and-methi (fenugreek) curry with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Ongoing support for your baby''s growth", "notes": "Today: Vitamin A supported your baby''s earliest eye and organ development during the first weeks of pregnancy. Now, at the beginning of the third trimester, it continues to support growth, immune function, and vision.", "breakfast_a": "Sweet-potato chaat (cooked, with roasted chana and a light tangy dressing).", "breakfast_b": "Sweet-potato chaat (cooked, with roasted chana and a light tangy dressing), and a boiled egg (cooked through) alongside.", "lunch_a": "Chana-and-carrot curry with whole-wheat roti.", "lunch_b": "Chicken-and-carrot curry with whole-wheat roti.", "nourishment_break_a": "A mango or papaya (in season) with a small handful of walnuts.", "nourishment_break_b": "A mango or papaya (in season) with a small bowl of curd.", "dinner_a": "Pumpkin soup with mixed dal and whole-wheat roti.", "dinner_b": "Pumpkin soup with chicken-and-vegetable curry and whole-wheat roti.", "still_hungry": "A piece of fruit."}, {"day_number": 5, "title": "When a symptom is worth mentioning", "notes": "Today: Difficulty seeing clearly in dim light or at night should not be dismissed or self-diagnosed as vitamin A deficiency. It can have different causes. If you notice a new change in your night vision, mention it to your maternity team rather than starting a vitamin A supplement yourself.", "breakfast_a": "Vegetable appam with a bowl of curd.", "breakfast_b": "Vegetable appam with a bowl of curd, and a boiled egg (cooked through) alongside.", "lunch_a": "Masoor dal with rice and a cooked carrot sabzi.", "lunch_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with rice and the same cooked carrot sabzi.", "nourishment_break_a": "A sliced carrot.", "nourishment_break_b": "A sliced carrot with pasteurized buttermilk and a small handful of peanuts.", "dinner_a": "Carrot-and-peas curry with whole-wheat roti.", "dinner_b": "Chicken-and-vegetable curry with whole-wheat roti and a side of the same carrot-and-peas curry.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "More isn''t the goal", "notes": "Today: The pregnancy upper limit for preformed vitamin A is 3000 mcg RAE per day for adults aged 19-50 and 2800 mcg RAE per day for adolescents aged 14-18. These are safety ceilings, not daily targets. They apply to preformed vitamin A from all sources combined, including food and supplements — not to beta-carotene naturally present in plant foods. Prenatal and multivitamin formulations vary. Check the label and do not add a separate vitamin A/retinol supplement, cod liver oil, or another multivitamin without checking with your maternity team or pharmacist.", "breakfast_a": "Vegetable dhokla with a bowl of curd.", "breakfast_b": "Vegetable dhokla with a bowl of curd, and a boiled egg (cooked through) alongside.", "lunch_a": "Kala chana curry with rice and a cooked carrot sabzi.", "lunch_b": "Chicken stew with rice and the same cooked carrot sabzi.", "nourishment_break_a": "A small bowl of curd.", "nourishment_break_b": "A glass of buttermilk (chaas) with a small handful of almonds.", "dinner_a": "Pumpkin-and-lentil curry with rice.", "dinner_b": "Chicken-and-carrot curry with rice and a side of the same pumpkin-and-lentil curry.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how a carrot, a mango, a bowl of dal, or an egg already carry vitamin A toward your vision, immunity, and your baby''s growth — while also learning the one thing worth skipping — is worth a quick look back. Colourful fruits and vegetables are a reliable food-based way to build vitamin A. The key safety message is simple: avoid liver and liver products, and check before adding a separate vitamin A/retinol supplement or cod liver oil.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'How many colourful fruits and vegetables did you eat this week? Is liver or a liver product something you''d usually eat — and if so, is this week''s note about it new information?',
   'Next week, we''ll look at vitamin E — a nutrient found in nuts, seeds, and oils that plays a supporting role in your body''s antioxidant defences.')
