-- pregnancy week 29: Vitamin E
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   29,
   'third',
   NULL,
   'Vitamin E',
   '"A handful of nuts, a spoon of seeds — steady, everyday support, no megadose required."',
   'Vitamin E acts as an antioxidant, helping protect cells from oxidative damage, and it contributes to normal immune function. ICMR-NIN''s 2020 nutrient tables do not include a separate figure for vitamin E, so this week uses the US pregnancy RDA — 15 mg per day — as a clearly labelled international reference, not a number to calculate meal by meal. If you eat meat, fish, or eggs: Vitamin E comes mainly from nuts, seeds, and vegetable oils rather than from meat, fish, or eggs. If you eat these foods, they can add a little vitamin E to your day, but they aren''t the main source — the plant foods on this week''s chart are doing most of the work either way.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Vitamin E acts as an antioxidant, helping protect cells from oxidative damage, and it contributes to normal immune function. ICMR-NIN''s 2020 nutrient tables do not include a separate figure for vitamin E, so this week uses the US pregnancy RDA — 15 mg per day — as a clearly labelled international reference, not a number to calculate meal by meal. Worth knowing: If you have a nut or seed allergy: skip that food and use only an alternative you already know is safe for you. Do not assume that another nut or seed is automatically safe. Follow the allergy guidance you have already been given.", "breakfast_a": "Idli with peanut and curry-leaf chutney.", "breakfast_b": "Idli with peanut and curry-leaf chutney, and a boiled egg (cooked through) alongside.", "lunch_a": "Palak (spinach) and chana dal with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken-and-spinach curry with whole-wheat roti and a bowl of curd.", "nourishment_break_a": "A small handful of almonds.", "nourishment_break_b": "A small handful of almonds, with a glass of milk.", "dinner_a": "Mixed vegetable curry with a side of roasted sunflower seeds, and whole-wheat roti.", "dinner_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with the same sunflower-seed side and whole-wheat roti.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where vitamin E naturally shows up", "notes": "Today: Vitamin E is found in several foods, but the amounts vary considerably. Sunflower seeds, almonds, peanuts, and certain vegetable oils — sunflower and safflower oil especially — are particularly useful sources. Other nuts and seeds, like walnuts or sesame, can still add variety without necessarily providing the same amount.", "breakfast_a": "Moong dal chilla topped with roasted sunflower seeds.", "breakfast_b": "Moong dal chilla topped with roasted sunflower seeds, and a boiled egg (cooked through) alongside.", "lunch_a": "Sarson ka saag (mustard greens) with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken curry with whole-wheat roti, a bowl of curd, and a side of the same sarson ka saag.", "nourishment_break_a": "A guava with a small handful of almonds.", "nourishment_break_b": "A guava with pasteurized buttermilk and a small handful of almonds.", "dinner_a": "Vegetable stir-fry cooked in sunflower oil, with rice.", "dinner_b": "Chicken-and-vegetable stir-fry cooked in sunflower oil, with rice.", "still_hungry": "A handful of roasted chana."}, {"day_number": 3, "title": "Where meat, fish, and eggs fit in", "notes": "Today: Vitamin E doesn''t split sharply along a meat-versus-plant line the way some nutrients do — but it does lean plant-forward. Eggs and fish contribute a modest amount, and meat contributes very little. If you eat these foods, they add a little to your day; the nuts, seeds, and oils on this week''s chart are doing most of the work either way.", "breakfast_a": "Ragi (finger millet) dosa with a bowl of curd.", "breakfast_b": "Ragi (finger millet) dosa with a bowl of curd, and a small side of sunflower seeds or almonds.", "lunch_a": "Chana (chickpea) and mixed vegetable curry with a side of roasted almonds, and whole-wheat roti.", "lunch_b": "Egg curry (cooked through) with whole-wheat roti and the same side of roasted almonds.", "nourishment_break_a": "A banana with a small handful of sunflower seeds.", "nourishment_break_b": "A banana with pasteurized buttermilk and a small handful of sunflower seeds.", "dinner_a": "Vegetable korma with a cashew-almond gravy and rice.", "dinner_b": "Chicken korma with the same cashew-almond gravy and rice.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Steady support through the third trimester", "notes": "Today: There''s no single dramatic role for vitamin E late in pregnancy — it continues its everyday work as an antioxidant, supporting your immune system, the same way it has throughout. Ordinary, varied meals continue to be the goal, not a specific late-pregnancy target.", "breakfast_a": "Daliya (broken wheat) and sunflower-seed porridge with milk.", "breakfast_b": "Daliya (broken wheat) and sunflower-seed porridge with milk, and a boiled egg (cooked through) alongside.", "lunch_a": "Lauki (bottle gourd) and chana dal with whole-wheat roti and a side of roasted peanuts.", "lunch_b": "Grilled chicken with whole-wheat roti and the same side of roasted peanuts.", "nourishment_break_a": "A sliced apple with a small handful of walnuts.", "nourishment_break_b": "A sliced apple with a glass of milk and a small handful of walnuts.", "dinner_a": "Vegetable pulao cooked in sunflower oil, topped with roasted peanuts.", "dinner_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with the same vegetable pulao, topped with roasted peanuts.", "still_hungry": "A piece of fruit."}, {"day_number": 5, "title": "More isn''t the goal", "notes": "Today: Vitamin E needs are best approached through a varied diet containing suitable nuts, seeds, and vegetable oils. A separate high-dose supplement is not needed unless it has been specifically recommended for you. Routine high-dose antioxidant supplementation with vitamin E and vitamin C is not recommended for improving pregnancy outcomes. Large supplemental doses can increase bleeding risk when combined with anticoagulant or antiplatelet medicines. If you take warfarin, prescribed aspirin, or another clot-related medicine, do not add a separate vitamin E supplement without checking with your maternity team or pharmacist first. Do not stop any prescribed medicine because of this information. The upper limit for supplemental vitamin E is 1,000 mg per day for adults aged 19-50 and 800 mg per day for adolescents aged 14-18. These are safety ceilings, not targets. They apply to vitamin E from supplements, fortified foods, and medications — not the amounts naturally present in ordinary foods.", "breakfast_a": "Vegetable rava (semolina) upma topped with roasted sunflower seeds and curry leaves.", "breakfast_b": "Vegetable rava (semolina) upma topped with roasted sunflower seeds and curry leaves, and a boiled egg (cooked through) alongside.", "lunch_a": "Chole (chickpea curry) with a side of roasted peanuts, and whole-wheat roti.", "lunch_b": "Chicken bhurji with the same side of roasted peanuts, and whole-wheat roti.", "nourishment_break_a": "A small handful of almonds.", "nourishment_break_b": "A small handful of almonds, with pasteurized buttermilk.", "dinner_a": "Vegetable jalfrezi with a side of roasted til (sesame), and whole-wheat roti.", "dinner_b": "Chicken jalfrezi with the same side of roasted til (sesame), and whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Cooking oil is only one contributor", "notes": "Today: Different oils provide different amounts of vitamin E, and the amounts vary by the oil and how it''s processed. You don''t need to change a familiar cooking oil or add extra oil solely for vitamin E — nuts, seeds, and other foods can contribute alongside whatever oil is normally used in your household.", "breakfast_a": "Moong dal dosa with a bowl of curd.", "breakfast_b": "Moong dal dosa with a bowl of curd and a tolerated seed or almond accompaniment.", "lunch_a": "Bhindi (okra) sabzi with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken curry with whole-wheat roti and a bowl of curd.", "nourishment_break_a": "A sliced cucumber and carrot with a small handful of sunflower seeds.", "nourishment_break_b": "A sliced cucumber and carrot with pasteurized buttermilk and a small handful of sunflower seeds.", "dinner_a": "Dal tadka with rice and a side of roasted almonds.", "dinner_b": "Egg-and-vegetable curry (cooked through) with rice and the same side of roasted almonds.", "still_hungry": "A piece of fruit."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how a handful of nuts, a spoon of seeds, or the oil in your kitchen already carry vitamin E toward your body''s everyday antioxidant work — quietly, without needing a supplement — is worth a quick look back. Nuts, seeds, and the oil already in your kitchen are doing steady, ordinary work — no megadose required.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which nuts, seeds, or oils already show up in your usual cooking? Was anything about supplements and cooking oil new information for you this week?',
   'Next week, we''ll look at selenium — a trace mineral that works alongside other antioxidants and supports thyroid function for both you and your baby.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 30: Selenium
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   30,
   'third',
   NULL,
   'Selenium',
   '"An egg, a bowl of curd, dal, grains or fish — ordinary foods can contribute selenium without a separate megadose."',
   'Selenium is part of proteins that help protect cells from oxidative damage and regulate thyroid hormone metabolism. ICMR-NIN''s 2020 committee recommends 40 mcg per day as a general adult adequate intake, without a separate pregnancy figure. NIH''s US pregnancy RDA — 60 mcg per day — is used here as a clearly labelled international reference, not a number to calculate meal by meal. If you eat meat, fish, or eggs: Seafood, poultry, meat, and eggs are selenium''s most concentrated everyday sources, so if you eat these foods, they''re likely doing a meaningful share of the work already. If you don''t eat meat or fish, Day 6 looks at real contributors from the rest of your plate.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Selenium is part of proteins that help protect cells from oxidative damage and regulate thyroid hormone metabolism. ICMR-NIN''s 2020 committee recommends 40 mcg per day as a general adult adequate intake, without a separate pregnancy figure. NIH''s US pregnancy RDA — 60 mcg per day — is used here as a clearly labelled international reference, not a number to calculate meal by meal.", "breakfast_a": "Mushroom-and-vegetable uttapam with a bowl of curd.", "breakfast_b": "Mushroom-and-vegetable uttapam with a bowl of curd, and a boiled egg (cooked through) alongside.", "lunch_a": "Rajma (kidney beans) curry with rice and a cooked spinach sabzi.", "lunch_b": "Chicken curry with rice and the same cooked spinach sabzi.", "nourishment_break_a": "A handful of roasted chana.", "nourishment_break_b": "A handful of roasted chana with a guava or orange.", "dinner_a": "Mixed dal with whole-wheat roti and a cooked vegetable sabzi.", "dinner_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with whole-wheat roti and the same cooked vegetable sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where selenium naturally shows up", "notes": "Today: Seafood, poultry, meat, eggs, and dairy are selenium''s most concentrated and reliable everyday sources. Grains and lentils can contribute too, but the amount varies depending on the selenium content of the soil they were grown in, so no single number can be promised from them.", "breakfast_a": "Vegetable-and-paneer bhurji with whole-wheat toast.", "breakfast_b": "Vegetable-and-egg bhurji with whole-wheat toast.", "lunch_a": "Chana dal with rice and a cooked vegetable sabzi.", "lunch_b": "Chicken keema with rice and the same cooked sabzi.", "nourishment_break_a": "A glass of milk with a banana.", "nourishment_break_b": "A glass of milk with a banana and a small handful of roasted chana.", "dinner_a": "Mushroom-and-pea curry with whole-wheat roti.", "dinner_b": "Prawn curry (cooked through, a low-mercury seafood choice) with whole-wheat roti and a side of the same mushroom-and-pea curry.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "A note on Brazil nuts", "notes": "Today: Brazil nuts are among the most concentrated food sources of selenium — a single nut can contain approximately 68 to 91 mcg, although the amount varies considerably, and even one or two can add up to more than a full day''s pregnancy reference amount. They''re not necessary for meeting your needs, and this week''s chart doesn''t build a meal around them. Worth knowing: Brazil nuts contain unusually large and variable amounts of selenium. They aren''t necessary for meeting your needs. If you already eat them, one occasionally is enough — avoid making several nuts a daily habit, particularly if your prenatal supplement already contains selenium.", "breakfast_a": "Semolina (suji) porridge with milk and a sliced banana.", "breakfast_b": "Vegetable suji (semolina) upma with a fully cooked masala omelette.", "lunch_a": "Vegetable pulao with a bowl of curd.", "lunch_b": "Chicken pulao with a bowl of curd.", "nourishment_break_a": "A banana with a glass of milk.", "nourishment_break_b": "A banana with a small handful of roasted chana.", "dinner_a": "Palak (spinach) and moong dal with whole-wheat roti.", "dinner_b": "Chicken stew with whole-wheat roti and a side of the same palak-moong dal.", "still_hungry": "A piece of fruit."}, {"day_number": 4, "title": "Selenium and your thyroid", "notes": "Today: Selenium is present in the thyroid gland in higher concentration than almost anywhere else in the body. Selenium-containing enzymes help activate and deactivate thyroid hormones. Selenium deficiency can make the effects of iodine deficiency worse, which is one reason ordinary, varied food matters for both minerals together. If this applies to you (thyroid condition or thyroid antibodies): If you have a thyroid condition, continue the treatment and monitoring prescribed by your maternity or thyroid-care team. Do not add a separate selenium supplement unless they specifically recommend it — the American Thyroid Association has specifically advised against routine selenium supplementation for pregnant women who test positive for thyroid antibodies.", "breakfast_a": "Idli with a tomato-and-onion chutney.", "breakfast_b": "Idli with a tomato-and-onion chutney, and a boiled egg (cooked through) alongside.", "lunch_a": "Paneer-and-capsicum curry with whole-wheat roti and a bowl of curd.", "lunch_b": "Grilled chicken with whole-wheat roti and a bowl of curd.", "nourishment_break_a": "A guava.", "nourishment_break_b": "A guava with a glass of milk.", "dinner_a": "Vegetable khichdi with a cooked bhindi sabzi.", "dinner_b": "Chicken khichdi with the same cooked bhindi sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "More isn''t the goal", "notes": "Today: Different authorities use different upper limits for selenium: the US limit is 400 mcg per day during pregnancy, while the newer European limit is 255 mcg per day. Neither is a target. Check whether your prenatal already contains selenium. Do not add a separate selenium supplement or make Brazil nuts a frequent habit unless your maternity team specifically advises it. Unlike some nutrients, selenium toxicity can happen from food alone if concentrated sources are eaten regularly and in large amounts, not only from supplements. Signs include hair and nail brittleness or loss, a garlic-like breath odour, and stomach upset.", "breakfast_a": "Vegetable rava idli with sambar.", "breakfast_b": "Vegetable rava idli with sambar, and a fully cooked masala omelette on the side.", "lunch_a": "Chana masala with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken bhurji with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "A familiar fruit.", "nourishment_break_b": "A small bowl of curd with a familiar fruit.", "dinner_a": "Turai (ridge gourd) and moong dal with whole-wheat roti.", "dinner_b": "Chicken curry (cooked through) with whole-wheat roti and a side of the same turai-moong dal.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Building selenium if you don''t eat meat or fish", "notes": "Today: If you don''t eat meat or fish, eggs and dairy — if included in your diet — along with lentils, beans, grains, mushrooms, nuts, and seeds can all contribute. Selenium in plant foods varies with the soil they were grown in, so variety matters more than relying on one ''selenium-rich'' dish.", "breakfast_a": "Paneer paratha with a bowl of curd.", "breakfast_b": "Egg paratha with a bowl of curd.", "lunch_a": "Mushroom-and-vegetable curry with whole-wheat roti and sliced cucumber-and-tomato salad.", "lunch_b": "Paneer-and-mushroom curry with whole-wheat roti and a side of sliced cucumber-and-tomato salad.", "nourishment_break_a": "A banana with a handful of roasted chana.", "nourishment_break_b": "A banana with a handful of roasted chana, and a glass of milk.", "dinner_a": "Moong dal khichdi with a cooked vegetable sabzi.", "dinner_b": "Paneer-and-mushroom khichdi with the same cooked vegetable sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how an egg, a bowl of curd, a piece of fish, or a mushroom curry already carry selenium toward your thyroid''s and your body''s everyday work — quietly, without needing a supplement — is worth a quick look back. An egg, a bowl of curd, dal, grains, or fish — ordinary foods already carry selenium toward your day, no separate megadose required.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which everyday foods this week were already giving you selenium without you realising it? Did anything about Brazil nuts or selenium and your thyroid surprise you?',
   'Next week, we''ll look at vitamin K — a nutrient with a direct role in normal blood clotting, for both you and your newborn.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
