-- pregnancy week 31: Vitamin K
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   31,
   'third',
   NULL,
   'Vitamin K',
   '"Leafy greens quietly support normal clotting and bone health — ordinary food, consistently included."',
   'Vitamin K helps your body make proteins involved in normal blood clotting, and it also plays a role in bone metabolism. ICMR-NIN''s 2020 committee recommends 55 mcg per day as a general adult figure, without a separate pregnancy value. NIH''s US pregnancy Adequate Intake — 90 mcg per day for adults, 75 mcg per day for pregnant adolescents aged 14-18 — is used here as a clearly labelled international reference, not a number to calculate meal by meal. If you eat meat, fish, or eggs: Vitamin K comes mainly from leafy greens, broccoli, cabbage, and some vegetable oils rather than from meat, fish, or eggs — these foods add only a small amount by comparison. The vegetables on this week''s chart are doing most of the real work either way.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Vitamin K helps your body make proteins involved in normal blood clotting, and it also plays a role in bone metabolism. ICMR-NIN''s 2020 committee recommends 55 mcg per day as a general adult figure, without a separate pregnancy value. NIH''s US pregnancy Adequate Intake — 90 mcg per day for adults, 75 mcg per day for pregnant adolescents aged 14-18 — is used here as a clearly labelled international reference, not a number to calculate meal by meal.", "breakfast_a": "Vegetable poha with roasted peanuts.", "breakfast_b": "Vegetable-and-egg poha with roasted peanuts.", "lunch_a": "Palak (spinach) paneer with whole-wheat roti.", "lunch_b": "Palak (spinach) chicken with whole-wheat roti.", "nourishment_break_a": "An orange.", "nourishment_break_b": "An orange with a small handful of roasted peanuts.", "dinner_a": "Masoor dal with whole-wheat roti and a cooked cabbage-and-pea sabzi.", "dinner_b": "Chicken keema with whole-wheat roti and the same cooked cabbage-and-pea sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where vitamin K naturally shows up", "notes": "Today: Leafy greens are vitamin K''s richest, most reliable source by a wide margin — spinach, kale, broccoli, cabbage, and everyday Indian greens like methi and sarson all contribute meaningfully, along with some vegetable oils. Meat, fish, and eggs add only small amounts by comparison, so this is a genuinely plant-forward nutrient.", "breakfast_a": "Carrot-and-cabbage paratha with a bowl of curd.", "breakfast_b": "Carrot-and-cabbage paratha with fully cooked egg bhurji.", "lunch_a": "Methi (fenugreek) and moong dal with whole-wheat roti and curd.", "lunch_b": "Chicken-and-methi curry with whole-wheat roti and curd.", "nourishment_break_a": "A handful of roasted makhana (fox nuts).", "nourishment_break_b": "A handful of roasted makhana (fox nuts), with a glass of milk.", "dinner_a": "Broccoli-and-paneer stir-fry with rice.", "dinner_b": "Chicken-and-broccoli stir-fry with rice.", "still_hungry": "A handful of roasted chana."}, {"day_number": 3, "title": "Your baby''s vitamin K shot", "notes": "Today: Very little vitamin K crosses the placenta, so babies are born with low vitamin K stores even when their mother ate a healthy, vitamin-K-containing diet during pregnancy. To prevent a rare but serious bleeding condition, doctors give a vitamin K injection to newborns shortly after birth. Eating well supports your own health, but it doesn''t replace the injection — that''s a separate, standard newborn protection your baby''s care team will offer.", "breakfast_a": "Vegetable dalia (broken wheat) upma.", "breakfast_b": "Vegetable dalia (broken wheat) upma, with a fully cooked masala omelette on the side.", "lunch_a": "Toor dal with rice and a cooked spinach sabzi.", "lunch_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with rice and the same cooked spinach sabzi.", "nourishment_break_a": "A guava.", "nourishment_break_b": "A guava with a small handful of peanuts.", "dinner_a": "Kadhi (a curd-based curry) with rice and a cooked cabbage-and-pea sabzi.", "dinner_b": "Chicken-and-vegetable curry with rice and the same cooked cabbage-and-pea sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "If you take warfarin or a similar medicine", "notes": "Today: Warfarin and certain similar anticoagulants work by interfering with vitamin K — this interaction doesn''t apply to every type of blood thinner. If you take warfarin, don''t avoid leafy greens or change your medicine yourself. Keep your usual intake reasonably consistent and discuss any substantial dietary change with your prescribing team. Warfarin isn''t usually used during pregnancy, though it may be prescribed in particular specialist situations — never stop or change an anticoagulant without medical guidance.", "breakfast_a": "Idli with coconut chutney.", "breakfast_b": "Idli with a small bowl of fully cooked chicken-and-vegetable stew.", "lunch_a": "Kabuli chana (white chickpea) curry with whole-wheat roti and a bowl of curd.", "lunch_b": "Fully cooked egg curry with whole-wheat roti and the same bowl of curd.", "nourishment_break_a": "A sliced apple.", "nourishment_break_b": "A sliced apple with a small bowl of curd.", "dinner_a": "Tinda (apple gourd) and moong dal with whole-wheat roti.", "dinner_b": "Grilled chicken with whole-wheat roti and a cooked tinda sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Ordinary food already covers this", "notes": "Today: Clinically significant vitamin K deficiency is rare in healthy adults eating a varied diet — it''s one of the few nutrients this series covers where the honest message is mostly reassurance. No upper limit has been established for naturally occurring forms of vitamin K, because they have a low potential for toxicity. That''s not a reason to add a separate supplement: most healthy adults get enough through ordinary food, and supplements can interact with medicines such as warfarin.", "breakfast_a": "Besan-and-cabbage cheela with a bowl of curd.", "breakfast_b": "Besan-and-cabbage cheela with fully cooked egg bhurji.", "lunch_a": "Green moong dal with rice and a cooked green bean sabzi.", "lunch_b": "Fish curry (cooked through, a lower-mercury choice such as sardines) with rice and the same cooked green bean sabzi.", "nourishment_break_a": "A familiar fruit.", "nourishment_break_b": "A familiar fruit with a small handful of walnuts.", "dinner_a": "Mixed vegetable curry with whole-wheat roti.", "dinner_b": "Chicken tikka (cooked through) with whole-wheat roti and a cooked mixed-vegetable sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Vitamin K and bone health", "notes": "Today: Beyond blood clotting, vitamin K also helps your body use a protein involved in building bone. This isn''t a reason to add a bone-health supplement — it''s another quiet reason the leafy greens on this week''s chart are doing more than one job.", "breakfast_a": "Set dosa with a bowl of curd.", "breakfast_b": "Egg dosa with sambar.", "lunch_a": "Paneer-and-spinach curry with whole-wheat roti.", "lunch_b": "Chicken-and-methi curry with whole-wheat roti.", "nourishment_break_a": "A small handful of almonds.", "nourishment_break_b": "A small handful of almonds, with a glass of milk.", "dinner_a": "Vegetable pulao with a cooked cauliflower sabzi.", "dinner_b": "Chicken pulao with the same cooked cauliflower sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how a bowl of palak, a methi dal, or a broccoli stir-fry already carry vitamin K toward your body''s everyday clotting and bone work — and understanding why your baby still gets a separate vitamin K shot at birth — is worth a quick look back. Leafy greens are quietly doing this week''s work — no supplement needed, and your baby''s own protection comes from a separate, standard newborn shot, not from your diet.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which leafy greens already show up in your usual cooking? Was the difference between your own vitamin K and your baby''s newborn shot new information for you?',
   'Next week, we''ll look at vitamin B6 — a nutrient with a real, practical connection to nausea, alongside its everyday role in how your body uses protein.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
