  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 32: Vitamin B6
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   32,
   'third',
   NULL,
   'Vitamin B6',
   '"Chana, potatoes, bananas, fish, and chicken — vitamin B6 appears across ordinary meals."',
   'Vitamin B6 supports how your body uses protein, helps make neurotransmitters, and plays a role in forming haemoglobin. ICMR-NIN''s 2020 committee gives a genuine pregnancy figure — 2.3 mg per day, up from 1.9 mg for a general adult woman. NIH''s US pregnancy RDA is close but not identical — 1.9 mg per day. Both are real, sourced figures rather than a single universal number, and neither needs calculating meal by meal. If you eat meat, fish, or eggs: Vitamin B6 doesn''t lean heavily toward either meat or plant foods — chana, potatoes, and bananas are genuinely strong plant sources, and fish and chicken add real amounts too. Whichever way you eat, ordinary meals are likely already covering a meaningful share.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Vitamin B6 supports how your body uses protein, helps make neurotransmitters, and plays a role in forming haemoglobin. ICMR-NIN''s 2020 committee gives a genuine pregnancy figure — 2.3 mg per day, up from 1.9 mg for a general adult woman. NIH''s US pregnancy RDA is close but not identical — 1.9 mg per day. Both are real, sourced figures rather than a single universal number, and neither needs calculating meal by meal.", "breakfast_a": "Aloo (potato) paratha with a bowl of curd.", "breakfast_b": "Aloo-and-egg paratha (egg mixed into the filling, cooked through) with a bowl of curd.", "lunch_a": "Chana (chickpea) curry with rice and a cooked vegetable sabzi.", "lunch_b": "Chicken curry with rice and the same cooked vegetable sabzi.", "nourishment_break_a": "A banana.", "nourishment_break_b": "A banana with a small handful of roasted peanuts.", "dinner_a": "Mixed dal with whole-wheat roti and a cooked pumpkin sabzi.", "dinner_b": "Sardine or another confirmed lower-mercury fish curry (cooked through) with whole-wheat roti and the same cooked pumpkin sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where vitamin B6 naturally shows up", "notes": "Today: Vitamin B6 doesn''t split sharply along a meat-versus-plant line — chana, potatoes, and bananas are genuinely good plant sources, while fish and chicken add meaningful amounts too. This is one of the more evenly diet-neutral nutrients in this series.", "breakfast_a": "Moong dal cheela with a bowl of curd.", "breakfast_b": "Moong dal cheela with fully cooked egg bhurji.", "lunch_a": "Aloo-gobi (potato-cauliflower) sabzi with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken-and-potato keema with whole-wheat roti and a bowl of curd.", "nourishment_break_a": "Guava or orange with a handful of roasted chana.", "nourishment_break_b": "Guava or orange with a handful of roasted chana, and a glass of milk.", "dinner_a": "Lobia (black-eyed peas) curry with rice and a cooked mixed-vegetable sabzi.", "dinner_b": "Grilled lower-mercury fish (cooked through) with rice and the same cooked mixed-vegetable sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "If nausea has continued or returned", "notes": "Today: Vitamin B6, alone or combined with doxylamine, is used as a first-line treatment for pregnancy-related nausea. That''s different from getting vitamin B6 through food, and your maternity team should advise you on the exact product and dose — particularly because your prenatal vitamin may already contain B6. At 32 weeks, contact your maternity team promptly if nausea or vomiting is new, suddenly worse, keeps you from keeping fluids down, or comes with a persistent headache, vision changes, pain under your ribs or upper abdomen, sudden swelling of your face or hands, breathlessness, or a general feeling that something is wrong. Choose whichever familiar food settles best; there''s no need to force a particular option during nausea. Worth knowing: Persistent vomiting, dehydration, dark urine, reduced urination, or being unable to keep food and fluids down all need medical assessment — don''t wait it out.", "breakfast_a": "Light vegetable upma with a banana.", "breakfast_b": "Plain toast with a fully cooked scrambled egg, if tolerated, and a banana.", "lunch_a": "Potato-and-pea sabzi with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken stew with whole-wheat roti and a bowl of curd.", "nourishment_break_a": "Plain crackers or dry toast.", "nourishment_break_b": "A small bowl of curd with plain toast, if tolerated.", "dinner_a": "Khichdi (rice and moong dal) with a cooked vegetable sabzi.", "dinner_b": "Chicken curry with rice and the same cooked vegetable sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "More isn''t the goal", "notes": "Today: Different authorities use different upper limits for vitamin B6: the US limit is 100 mg per day for adults aged 19 and over and 80 mg per day for pregnant adolescents aged 14-18, while EFSA''s newer adult limit — including pregnancy — is 12 mg per day. Neither is a target. Repeated excessive supplemental intake can cause peripheral neuropathy, including tingling, burning, numbness, or difficulty with balance and walking. Food doesn''t create this problem, but supplements can stack across a prenatal vitamin, a B-complex product, and a separate nausea treatment. Check labels, and follow your maternity team''s dosing advice.", "breakfast_a": "Moong dal dosa with a bowl of curd.", "breakfast_b": "Egg-and-moong dosa (egg mixed into the batter, cooked through) with a bowl of curd.", "lunch_a": "Kala chana (black chickpea) sabzi with whole-wheat roti and a bowl of curd.", "lunch_b": "Chicken bhurji with whole-wheat roti and the same bowl of curd.", "nourishment_break_a": "A familiar fruit.", "nourishment_break_b": "A familiar fruit with a small handful of walnuts.", "dinner_a": "Vegetable pulao with a cooked carrot-and-peas sabzi.", "dinner_b": "Chicken-and-vegetable pulao (chicken cooked through) with cucumber raita.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Vitamin B6 and its B-vitamin teammates", "notes": "Today: Vitamin B6 works alongside folate and vitamin B12 — nutrients this series has already covered — in managing a compound called homocysteine in your blood. Vitamin B6, folate, and vitamin B12 take part in related pathways, but each nutrient still has its own role and recommended intake. A varied diet — and any supplements your team prescribes — helps support all three.", "breakfast_a": "Ragi (finger millet) porridge with milk and chopped apple or raisins.", "breakfast_b": "Savoury ragi (finger millet) dosa with fully cooked egg bhurji.", "lunch_a": "Palak (spinach) and toor dal with whole-wheat roti.", "lunch_b": "Chicken curry with whole-wheat roti and a cooked spinach sabzi.", "nourishment_break_a": "A small handful of almonds.", "nourishment_break_b": "A small handful of almonds, with a glass of milk.", "dinner_a": "Chana (chickpea) and vegetable curry with rice.", "dinner_b": "Fish-and-vegetable stew (cooked through, a lower-mercury choice such as sardines) with rice.", "still_hungry": "A piece of fruit."}, {"day_number": 6, "title": "Away from home", "notes": "Today: A sandwich, a familiar roti-and-sabzi combination, a piece of fruit — vitamin B6 doesn''t require anything special or hard to find, even on a day when cooking from scratch isn''t realistic.", "breakfast_a": "Vegetable sandwich (whole-wheat bread) with a piece of fruit.", "breakfast_b": "Chicken-and-vegetable sandwich (whole-wheat bread, chicken cooked through) with a piece of fruit.", "lunch_a": "Rajma (kidney beans) curry with rice and a bowl of curd.", "lunch_b": "Fully cooked egg curry with rice and a bowl of curd.", "nourishment_break_a": "A banana with a familiar snack.", "nourishment_break_b": "A banana with a small handful of peanuts.", "dinner_a": "Vegetable stew with whole-wheat roti.", "dinner_b": "Chicken stew with whole-wheat roti.", "still_hungry": "A piece of fruit."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how a banana, a bowl of chana, a potato sabzi, or a piece of fish already carry vitamin B6 toward your everyday protein and nerve work — and, if nausea has continued into your third trimester, learning there''s a real, evidence-backed treatment option worth discussing with your maternity team — is worth a quick look back. Chana, potatoes, bananas, fish, and chicken — vitamin B6 appears across ordinary meals.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which everyday foods this week were already giving you vitamin B6 without you realising it? If nausea has continued into your third trimester, was Day 3''s information new to you?',
   'Next week, we''ll look at copper — a quiet trace mineral that works alongside iron in forming your baby''s blood cells and connective tissue.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 33: Copper
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   33,
   'third',
   NULL,
   'Copper',
   '"A handful of cashews, a bowl of dal, a mushroom sabzi — copper is quietly at work in ordinary meals."',
   'Copper is a cofactor for enzymes involved in iron metabolism, connective tissue formation, and nerve signalling. ICMR-NIN''s 2020 committee gives a general adult figure of 1.7 mg per day, without a separate pregnancy value — the same gap pattern already seen with vitamin E and vitamin K. NIH''s US pregnancy RDA — 1,000 mcg (1 mg) per day — is used here as a clearly labelled international reference, not a number to calculate meal by meal. If you eat meat, fish, or eggs: Copper leans toward plant foods — cashews, sesame and sunflower seeds, whole grains, and legumes are strong, reliable sources. Meat, fish, and chicken add only moderate amounts by comparison; the most concentrated animal sources (shellfish, organ meats) aren''t a focus here — liver in particular already carries a separate caution in this series for its very high vitamin A content.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Copper is a cofactor for enzymes involved in iron metabolism, connective tissue formation, and nerve signalling. ICMR-NIN''s 2020 committee gives a general adult figure of 1.7 mg per day, without a separate pregnancy value — the same gap pattern already seen with vitamin E and vitamin K. NIH''s US pregnancy RDA — 1,000 mcg (1 mg) per day — is used here as a clearly labelled international reference, not a number to calculate meal by meal.", "breakfast_a": "Mushroom-and-vegetable paratha with a bowl of curd.", "breakfast_b": "Mushroom-and-egg paratha (egg mixed into the filling, cooked through) with a bowl of curd.", "lunch_a": "Chana dal (split chickpea) with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-chana curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "A small handful of cashews.", "nourishment_break_b": "Plain curd with chopped fruit and a sesame sprinkle.", "dinner_a": "Toor dal with rice and a cooked vegetable sabzi.", "dinner_b": "Grilled lower-mercury fish (cooked through) with rice and the same cooked vegetable sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where copper naturally shows up", "notes": "Today: Copper leans toward plant foods — cashews, sesame and sunflower seeds, whole grains, millets, and legumes are strong, reliable sources. Meat, fish, and chicken add only moderate amounts by comparison. Liver is naturally very concentrated in copper, but this series already advises caution with liver during pregnancy for a different reason — its very high vitamin A content — so it isn''t featured here as a food choice.", "breakfast_a": "Bajra (pearl millet) khichdi with a bowl of curd.", "breakfast_b": "Bajra (pearl millet) khichdi with fully cooked egg bhurji.", "lunch_a": "Soybean (chunks) curry with rice and a cooked vegetable sabzi.", "lunch_b": "Chicken do pyaza (onion-based curry, cooked through) with rice and a sesame-tempered vegetable sabzi.", "nourishment_break_a": "Roasted sunflower seeds with a piece of fruit.", "nourishment_break_b": "Roasted sunflower seeds with fruit and a small paneer-and-cucumber portion.", "dinner_a": "Sesame (til) tempered vegetable stir-fry with whole-wheat roti.", "dinner_b": "Sesame (til) tempered chicken stir-fry (cooked through) with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "Copper and your baby''s third-trimester stores", "notes": "Today: A large share of a baby''s copper stores develops during the third trimester, particularly in the liver. This helps explain why copper is needed during pregnancy, but it isn''t a reason to count copper or increase it beyond a varied diet and your prescribed prenatal.", "breakfast_a": "Vegetable uttapam with coconut chutney.", "breakfast_b": "Egg uttapam (egg mixed into the batter, cooked through) with coconut chutney.", "lunch_a": "Chana (chickpea) curry with rice and a cooked spinach sabzi.", "lunch_b": "Lower-mercury fish curry (cooked through) with rice, cooked spinach, and a small sesame garnish.", "nourishment_break_a": "A familiar fruit.", "nourishment_break_b": "A familiar fruit with a small handful of cashews.", "dinner_a": "Mixed dal with whole-wheat roti and a cooked mushroom sabzi.", "dinner_b": "Chicken-and-mushroom curry (cooked through) with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "More isn''t the goal", "notes": "Today: The upper limit for copper is 10 mg per day for pregnant adults and 8 mg per day for pregnant adolescents aged 14-18. Copper toxicity is uncommon from ordinary food. Excess exposure is more likely to involve inappropriate high-dose supplements, copper leaching from plumbing into drinking water, or a diagnosed condition such as Wilson''s disease. There''s no reason to add a separate copper supplement beyond your prescribed prenatal unless your maternity team recommends it.", "breakfast_a": "Multigrain (whole-wheat and millet) toast with peanut butter and a banana.", "breakfast_b": "Multigrain (whole-wheat and millet) toast with a fully cooked vegetable-and-egg scramble, and a banana.", "lunch_a": "Whole-wheat pasta with mixed vegetables in a light tomato sauce.", "lunch_b": "Whole-wheat pasta with mixed vegetables and grilled chicken (cooked through) in a light tomato sauce.", "nourishment_break_a": "A small handful of pistachios.", "nourishment_break_b": "Pistachios with unsweetened lassi.", "dinner_a": "Mixed vegetable curry with whole-wheat roti.", "dinner_b": "Chicken-and-mixed-vegetable kadai curry (cooked through) with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Copper and its mineral teammates", "notes": "Today: Copper works closely with iron — a copper-dependent protein called ceruloplasmin helps your body use iron properly, a nutrient this series has already covered (Week 11). Also worth remembering from Week 21: taking high-dose zinc supplements beyond what your prenatal provides can interfere with copper absorption over time, so don''t add extra zinc on your own.", "breakfast_a": "Jowar (sorghum) roti with a mixed vegetable sabzi and a bowl of curd.", "breakfast_b": "Jowar (sorghum) roti with a mixed vegetable sabzi and a fully cooked masala omelette.", "lunch_a": "Moong dal (whole, sabut) with rice and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-sabut-moong curry (cooked through) with rice and the same cooked vegetable sabzi.", "nourishment_break_a": "One small piece of til-gur chikki, or one small til laddu.", "nourishment_break_b": "Plain curd topped with roasted sesame seeds and fruit.", "dinner_a": "Tofu-and-vegetable stir-fry with rice.", "dinner_b": "Lower-mercury fish curry or pan-cooked sardines (cooked through), served with rice and a sesame-tempered vegetable stir-fry.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Away from home", "notes": "Today: A handful of peanuts, a bowl of curd rice, a simple wrap — copper doesn''t need anything elaborate, even on a day when cooking from scratch isn''t realistic.", "breakfast_a": "Peanut butter toast with a banana.", "breakfast_b": "Peanut butter toast with a banana, and a glass of milk.", "lunch_a": "Curd rice with roasted peanuts and a cucumber salad.", "lunch_b": "Chicken roll (whole-wheat roti wrap, chicken cooked through) with the same cucumber salad.", "nourishment_break_a": "An apple with a small portion of roasted chana.", "nourishment_break_b": "A banana with peanut butter.", "dinner_a": "Vegetable khichdi (rice and dal) with curd.", "dinner_b": "Egg khichdi (egg stirred in, cooked through) with curd.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how a handful of cashews, a bowl of chana dal, a mushroom sabzi, or a piece of fish can contribute copper to ordinary meals — and learning how copper supports iron use, connective tissue, and normal development — is worth a quick look back. A handful of cashews, a bowl of dal, a mushroom sabzi — copper is quietly at work in ordinary meals.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which everyday foods this week were already giving you copper without you realising it? Did learning about copper''s role in pregnancy change how you think about these ordinary foods?',
   'Next week, we''ll look at manganese — a trace mineral that works alongside copper in bone formation and antioxidant defence.')
