-- pregnancy week 34: Manganese
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   34,
   'third',
   NULL,
   'Manganese',
   '"A bowl of oats, a dal, a handful of roasted chana — manganese is quietly at work in ordinary meals."',
   'Manganese is a cofactor for enzymes involved in metabolism, antioxidant defence, and bone formation. ICMR-NIN''s 2020 committee gives a general adult figure of 4 mg per day, without a separate pregnancy value — the same gap pattern already seen with vitamin E, vitamin K, and copper. NIH''s evidence base for manganese wasn''t strong enough to set a full RDA, so it publishes an Adequate Intake (AI) instead — 2.0 mg per day in pregnancy — used here as a clearly labelled international reference, not a number to calculate meal by meal. If you eat meat, fish, or eggs: In everyday Indian meals, manganese comes mainly from plant foods such as whole grains, legumes, nuts, and leafy vegetables. Most meat, chicken, fish, eggs, and dairy provide relatively little, although some shellfish are exceptions. Whichever path you choose, the plant foods in this week''s meals remain important.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Manganese is a cofactor for enzymes involved in metabolism, antioxidant defence, and bone formation. ICMR-NIN''s 2020 committee gives a general adult figure of 4 mg per day, without a separate pregnancy value — the same gap pattern already seen with vitamin E, vitamin K, and copper. NIH''s evidence base for manganese wasn''t strong enough to set a full RDA, so it publishes an Adequate Intake (AI) instead — 2.0 mg per day in pregnancy — used here as a clearly labelled international reference, not a number to calculate meal by meal.", "breakfast_a": "Oats porridge with milk and chopped apple.", "breakfast_b": "Vegetable-and-oats upma with a fully cooked egg bhurji.", "lunch_a": "Masoor dal with brown rice and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-masoor-dal curry (cooked through) with brown rice and the same cooked vegetable sabzi.", "nourishment_break_a": "A familiar fruit with roasted chana.", "nourishment_break_b": "Plain curd with chopped fruit and ground nuts.", "dinner_a": "Mixed dal with whole-wheat roti and a cooked beetroot sabzi.", "dinner_b": "Lower-mercury fish curry (cooked through, such as sardines) with whole-wheat roti and the same cooked beetroot sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where manganese naturally shows up", "notes": "Today: Manganese is one of the more plant-forward nutrients in this series — whole grains, legumes, nuts, and leafy greens are the main sources. Most meat, chicken, fish, eggs, and dairy provide relatively little, although some shellfish are exceptions. Whichever way you eat, this week''s plant foods are doing most of the real work.", "breakfast_a": "Whole-wheat vegetable dalia (broken wheat) porridge.", "breakfast_b": "Whole-wheat vegetable dalia (broken wheat) porridge with a fully cooked egg bhurji.", "lunch_a": "Urad dal (split black gram) with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-urad-dal curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "A small bowl of thoroughly cooked moong chaat with lemon and coriander.", "nourishment_break_b": "A small bowl of thoroughly cooked moong-and-chana chaat with lemon and coriander.", "dinner_a": "Vegetable pulao (brown rice) with a cooked methi (fenugreek) sabzi.", "dinner_b": "Chicken-and-vegetable pulao (brown rice, chicken cooked through) with the same cooked methi sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "Manganese, iron, and vitamin K", "notes": "Today: Manganese and iron can affect one another''s absorption. When iron stores are low, the body may absorb more manganese; higher dietary iron can reduce manganese absorption. This is useful background, but it isn''t something to manage meal by meal — continue any iron testing or supplements recommended by your maternity team, for the reasons already covered in Week 11. Manganese is also involved in processes that support normal blood clotting. Vitamin K, covered in Week 31, has its own essential clotting role; the two aren''t interchangeable, and this connection doesn''t change any supplement or medication advice.", "breakfast_a": "Vegetable poha with roasted peanuts.", "breakfast_b": "Vegetable-and-egg poha with roasted peanuts.", "lunch_a": "Palak (spinach) and toor dal with whole-wheat roti.", "lunch_b": "Chicken-and-palak (spinach) curry (cooked through) with whole-wheat roti and a bowl of toor dal.", "nourishment_break_a": "A familiar fruit.", "nourishment_break_b": "A familiar fruit with a small handful of roasted chana.", "dinner_a": "Whole-wheat roti with a mixed vegetable curry and a small bowl of curd.", "dinner_b": "Whole-wheat roti with a mixed vegetable-and-chicken curry (cooked through) and a small bowl of curd.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "More isn''t the goal", "notes": "Today: The upper limit for manganese is 11 mg per day for pregnant adults and 9 mg per day for pregnant adolescents aged 14-18. Harm from manganese in ordinary food has not been demonstrated. Excess exposure has primarily been associated with occupational inhalation or drinking water containing unusually high manganese levels. There''s no reason to add a separate manganese supplement beyond your prescribed prenatal unless your maternity team recommends it.", "breakfast_a": "Vegetable-and-oats paratha with a bowl of curd.", "breakfast_b": "Vegetable-and-oats paratha with a fully cooked masala omelette.", "lunch_a": "Whole-wheat vegetable dalia (broken wheat) pulao with a cooked leafy-green sabzi.", "lunch_b": "Whole-wheat chicken-and-vegetable dalia pulao (chicken cooked through) with the same cooked leafy-green sabzi.", "nourishment_break_a": "A pear or apple with roasted seeds.", "nourishment_break_b": "A small bowl of curd with chopped fruit and cinnamon.", "dinner_a": "Whole-wheat vegetable noodles with leafy greens and roasted seeds.", "dinner_b": "Whole-wheat chicken-and-vegetable noodles (chicken cooked through) with leafy greens and roasted seeds.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "Manganese and bone health", "notes": "Today: Manganese is a cofactor for enzymes involved in building bone, working alongside other nutrients this series has already covered — calcium (Week 9), magnesium (Weeks 16 and 24), and vitamin D (Week 18). Human research on manganese and bone density specifically is limited and inconsistent, so this isn''t a nutrient to fixate on for bone health alone — it''s one small piece alongside the others.", "breakfast_a": "Vegetable idli with sambar (lentil stew).", "breakfast_b": "Idli with sambar and a fully cooked vegetable-and-egg bhurji.", "lunch_a": "Matki (moth bean) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-matki curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "A small bowl of curd with a familiar fruit and ground flaxseed.", "nourishment_break_b": "A small whole-wheat vegetable sandwich with a roasted-seed sprinkle.", "dinner_a": "Brown rice with a mixed vegetable curry.", "dinner_b": "Brown rice with a lower-mercury fish curry (cooked through, such as sardines) and a cooked vegetable sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Away from home", "notes": "Today: A bowl of oats, a handful of roasted chana, a simple frankie — manganese doesn''t need anything elaborate, even on a day when cooking from scratch isn''t realistic.", "breakfast_a": "Overnight oats made with pasteurized milk and chopped banana or apple, prepared the night before and kept refrigerated.", "breakfast_b": "Refrigerated overnight oats made with pasteurized milk, banana, and ground nuts.", "lunch_a": "Whole-wheat vegetable frankie with a bowl of curd.", "lunch_b": "Whole-wheat chicken frankie (chicken cooked through) with the same bowl of curd.", "nourishment_break_a": "An apple with roasted chana.", "nourishment_break_b": "A banana with a small nut-butter portion.", "dinner_a": "Mixed vegetable curry with whole-wheat roti.", "dinner_b": "Chicken curry (cooked through) with whole-wheat roti and a cooked vegetable sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how a bowl of oats, a dal, a handful of roasted chana, or a leafy-green sabzi can contribute manganese — and learning about its role in metabolism, bone formation, and normal clotting — is worth a quick look back. A bowl of oats, a dal, a handful of roasted chana — manganese is quietly at work in ordinary meals.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which everyday foods this week were already giving you manganese without you realising it? Did learning about its roles in metabolism, bone formation, and normal clotting change how you think about these ordinary foods?',
   'Next week, we''ll continue exploring another trace nutrient found in everyday foods.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 35: Thiamine
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   35,
   'third',
   NULL,
   'Thiamine',
   '"A dal, a roti, a handful of seeds — energy, quietly at work."',
   'Thiamine, or vitamin B1, helps the body turn food into usable energy and supports normal cell and nerve function. ICMR-NIN recommends 2 mg per day during pregnancy. The corresponding US recommendation is 1.4 mg per day, reflecting a different reference system. These figures are useful background — not numbers you need to calculate meal by meal. If you eat meat, fish, or eggs: Thiamine doesn''t concentrate heavily in most animal foods — chicken, beef, and eggs contain only small amounts. Fish contributes a moderate amount, and pork, where it''s eaten, is genuinely one of the richer single food sources — but whole grains, dals, and seeds remain the real backbone for most Indian diets regardless of what else you eat this week.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Thiamine, or vitamin B1, helps the body turn food into usable energy and supports normal cell and nerve function. ICMR-NIN recommends 2 mg per day during pregnancy. The corresponding US recommendation is 1.4 mg per day, reflecting a different reference system. These figures are useful background — not numbers you need to calculate meal by meal.", "breakfast_a": "Vegetable dal-and-rice dosa with a bowl of curd.", "breakfast_b": "Vegetable dal-and-rice dosa with a fully cooked egg bhurji.", "lunch_a": "Rajma (kidney bean) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-rajma curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "A piece of fruit with a small handful of roasted sunflower seeds.", "nourishment_break_b": "A small bowl of curd with chopped fruit and one tablespoon of finely ground mixed nuts.", "dinner_a": "Barley (jau) khichdi with a cooked vegetable sabzi.", "dinner_b": "Lower-mercury fish curry (cooked through) with barley khichdi and the same cooked vegetable sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where thiamine naturally shows up", "notes": "Today: Thiamine doesn''t concentrate in most animal foods the way some earlier nutrients in this series have — chicken, beef, and eggs contain only small amounts. Whole grains, dals, and seeds are the real backbone here. Milling matters: heavily polished white rice generally contains less thiamine than brown, less-polished, or parboiled rice. Fortified rice does not always include thiamine, so check the label rather than assuming it does.", "breakfast_a": "Vegetable dalia (broken wheat) porridge.", "breakfast_b": "Vegetable dalia porridge with a fully cooked masala omelette.", "lunch_a": "Lobia (black-eyed pea) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-lobia curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "A small bowl of roasted chana.", "nourishment_break_b": "Peanut-and-cucumber chaat.", "dinner_a": "Whole-wheat pasta with chickpeas and mixed vegetables.", "dinner_b": "Whole-wheat pasta with chicken, chickpeas, and mixed vegetables (chicken cooked through).", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "When vomiting affects nourishment", "notes": "Today: Severe, prolonged vomiting can sometimes deplete thiamine because the body stores only a limited amount. This is uncommon, but it is one reason persistent vomiting and difficulty keeping food or fluids down need medical attention. Worth knowing: If severe vomiting returns, you cannot keep fluids down, or you notice signs of dehydration, contact your maternity team promptly. Tell them about any prolonged period of vomiting or very limited food intake; they can assess whether fluids, medicines, or thiamine treatment are needed.", "breakfast_a": "Whole-wheat besan (chickpea flour) chilla with a bowl of curd.", "breakfast_b": "Whole-wheat besan chilla with a fully cooked egg bhurji.", "lunch_a": "Whole masoor dal with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-masoor-dal curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "A familiar fruit with whole-grain crackers.", "nourishment_break_b": "A familiar fruit with a small handful of roasted chana.", "dinner_a": "Whole-wheat dalia-and-moong khichdi with a cooked vegetable sabzi.", "dinner_b": "Lower-mercury fish curry (cooked through), served alongside the same dalia-and-moong khichdi and vegetable sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "More isn''t the goal", "notes": "Today: No upper limit has been established for thiamine because harmful effects from usual oral intake have not been reported and the available evidence is limited. This does not mean that unlimited doses are useful. There is no reason to add a separate thiamine or high-dose B-complex supplement beyond your prescribed prenatal unless your maternity team recommends it. Medical doses of thiamine are used for specific conditions under clinical supervision.", "breakfast_a": "Whole-wheat vegetable paratha with a bowl of curd.", "breakfast_b": "Whole-wheat vegetable paratha with a fully cooked masala omelette.", "lunch_a": "Chana dal with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-chana-dal curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "Cooked corn chaat.", "nourishment_break_b": "A small bowl of curd with fruit and ground flaxseed.", "dinner_a": "Brown-rice vegetable pulao with a cooked leafy-green sabzi.", "dinner_b": "Chicken-and-brown-rice pulao (chicken cooked through) with the same cooked leafy-green sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "How cooking affects thiamine", "notes": "Today: Thiamine dissolves in water and breaks down with prolonged heat, so how food is cooked changes how much actually reaches you. Simple habits help: using the water dal or vegetables were cooked in as part of the dish rather than draining it away, not overcooking grains and vegetables longer than needed, and choosing whole-wheat atta and less-polished rice where you can.", "breakfast_a": "Ragi (finger millet) porridge with milk.", "breakfast_b": "Ragi porridge with milk and a fully cooked egg bhurji.", "lunch_a": "Moong dal with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-moong-dal curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "Peanuts with a piece of fruit.", "nourishment_break_b": "A small whole-wheat vegetable sandwich.", "dinner_a": "Potato-and-peas curry with whole-wheat roti.", "dinner_b": "Chicken, potato, and peas curry (chicken cooked through) with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Away from home", "notes": "Today: Whole grains, dal, and seeds don''t need anything elaborate, even on a day when cooking from scratch isn''t realistic.", "breakfast_a": "Peanut-butter toast on whole-wheat bread with a banana.", "breakfast_b": "Whole-wheat toast with a hard-boiled egg, banana, and a small portion of roasted chana.", "lunch_a": "A whole-wheat vegetable kathi roll with a cucumber salad.", "lunch_b": "A whole-wheat chicken kathi roll (chicken cooked through) with the same cucumber salad.", "nourishment_break_a": "Roasted-chana trail mix.", "nourishment_break_b": "A piece of fruit with peanut butter.", "dinner_a": "Dal-and-vegetable soup with whole-grain toast.", "dinner_b": "Chicken-and-vegetable soup (chicken cooked through) with whole-grain toast.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how a dal, a roti, a handful of seeds, or a bowl of khichdi already carry thiamine toward your body''s everyday energy and nerve function — and learning how cooking itself changes how much survives — is worth a quick look back. A dal, a roti, a handful of seeds — thiamine is quietly at work in ordinary meals.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did learning that thiamine can be lost through prolonged cooking or discarded cooking water change anything about how you might prepare grains, dals, or vegetables?',
   'Next week, we''ll continue exploring another everyday nutrient your body relies on for steady energy and function.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 36: Riboflavin
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   36,
   'third',
   NULL,
   'Riboflavin',
   '"Milk, an egg, a mushroom sabzi, a handful of almonds — riboflavin''s quiet, everyday work."',
   'Riboflavin, or vitamin B2, helps your body release energy from food and supports normal cell growth and function. ICMR-NIN recommends 2.7 mg per day during pregnancy. The corresponding US recommendation is 1.4 mg per day, reflecting a different reference system. These figures are useful background — not numbers you need to calculate meal by meal. If you eat meat, fish, or eggs: Eggs are a useful riboflavin source. Most chicken and many commonly eaten fish provide smaller amounts than milk, eggs, or organ meats, so mushrooms, spinach, almonds, and fortified foods remain useful alongside them. If you avoid dairy: Wherever milk is listed, you may choose a sealed or pasteurised plant drink whose label specifically lists riboflavin. Curd and paneer do not have automatic nutritional equivalents, so use the stated mushroom, spinach, almond, or fortified-food alternative rather than assuming every plant substitute contains riboflavin.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Today: Riboflavin, or vitamin B2, helps your body release energy from food and supports normal cell growth and function. ICMR-NIN recommends 2.7 mg per day during pregnancy. The corresponding US recommendation is 1.4 mg per day, reflecting a different reference system. These figures are useful background — not numbers you need to calculate meal by meal.", "breakfast_a": "Vegetable poha with milk or a riboflavin-fortified soy drink.", "breakfast_b": "Vegetable poha with a fully cooked egg bhurji.", "lunch_a": "Palak paneer with whole-wheat roti, or palak-mushroom curry with whole-wheat roti for a dairy-free choice.", "lunch_b": "Chicken-and-spinach curry (cooked through) with whole-wheat roti and a small bowl of curd.", "nourishment_break_a": "Almonds with a piece of fruit.", "nourishment_break_b": "Cooked mushroom-and-corn chaat.", "dinner_a": "Mushroom-and-vegetable curry with whole-wheat roti.", "dinner_b": "Chicken-and-mushroom curry (cooked through) with whole-wheat roti and a cooked spinach sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where riboflavin naturally shows up", "notes": "Today: Riboflavin shows up across both plant and animal foods, though not evenly. Milk, curd, and eggs are familiar sources, and mushrooms, spinach, and almonds add a genuine plant contribution too. Liver is the single most concentrated source, but this series already flagged (Week 28) that pregnancy calls for limiting liver because of its very high vitamin A content — so it isn''t built into this week''s meal options. Riboflavin is sensitive to light, so milk is best kept in an opaque or covered container away from direct sunlight. Because riboflavin is water-soluble, boiling vegetables and discarding the water can lose more of it than steaming or microwaving.", "breakfast_a": "Mushroom-and-spinach rice bowl with cucumber.", "breakfast_b": "Curd rice with a hard-boiled egg and cucumber.", "lunch_a": "Paneer-and-spinach curry with whole-wheat roti.", "lunch_b": "Chicken-and-spinach curry (cooked through) with whole-wheat roti and a small bowl of curd.", "nourishment_break_a": "Spinach-and-corn mini sandwich.", "nourishment_break_b": "Fruit with peanuts.", "dinner_a": "Mushroom-and-spinach stir-fry with whole-wheat roti.", "dinner_b": "Chicken-and-mushroom stir-fry (cooked through) with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "When intake may need more attention", "notes": "Today: Riboflavin deficiency is uncommon, but obtaining enough can require more planning if you avoid dairy and eggs, follow a very restricted diet, have prolonged poor intake, or have a condition that affects nutrient absorption. Symptoms such as mouth soreness, skin changes, or eye irritation can have many causes and should not be self-diagnosed as a vitamin deficiency. If your diet has become very limited or you have persistent symptoms, discuss them with your maternity team.", "breakfast_a": "Grilled mushroom-and-vegetable sandwich with milk or a riboflavin-fortified soy drink.", "breakfast_b": "Grilled vegetable-and-egg sandwich (egg cooked through) with milk or a riboflavin-fortified soy drink.", "lunch_a": "Chole (chickpea) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-chole curry (cooked through) with whole-wheat roti and a small bowl of curd.", "nourishment_break_a": "Fortified whole-grain cereal with milk or a riboflavin-fortified soy drink.", "nourishment_break_b": "Fruit with almonds.", "dinner_a": "Spinach-and-corn sabzi with whole-wheat roti.", "dinner_b": "Chicken-and-almond curry (cooked through) with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Food first, supplements only when advised", "notes": "Today: Researchers have studied riboflavin status in relation to pregnancy outcomes, including preeclampsia, but the evidence is limited and supplementation has not been shown reliably to prevent it. Do not add a separate riboflavin supplement for this purpose. Riboflavin-rich foods cannot replace antenatal appointments, blood-pressure checks, or urgent assessment of possible preeclampsia symptoms.", "breakfast_a": "Vegetable vermicelli upma with milk or a riboflavin-fortified soy drink.", "breakfast_b": "Vegetable vermicelli upma with a fully cooked masala omelette.", "lunch_a": "Safed vatana (white pea) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-safed-vatana curry (cooked through) with whole-wheat roti and a small bowl of curd.", "nourishment_break_a": "Mushroom toast.", "nourishment_break_b": "Curd or fortified soy yogurt with fruit.", "dinner_a": "Methi (fenugreek) and mushroom curry with whole-wheat roti.", "dinner_b": "Chicken-and-methi curry (cooked through) with whole-wheat roti and a cooked vegetable sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "More isn''t the goal", "notes": "Today: No upper limit has been established for riboflavin because harmful effects from usual oral intake have not been reported and the available evidence is limited. This does not mean that unlimited doses are useful. There is no reason to add a separate riboflavin or high-dose B-complex supplement beyond your prescribed prenatal unless your maternity team recommends it.", "breakfast_a": "Rava (semolina) idli with coconut chutney and milk or a riboflavin-fortified soy drink.", "breakfast_b": "Rava idli with coconut chutney and a fully cooked egg bhurji.", "lunch_a": "Kala chana (black chickpea) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-kala-chana curry (cooked through) with whole-wheat roti and a cooked vegetable sabzi.", "nourishment_break_a": "Roasted chana trail mix.", "nourishment_break_b": "Fruit with a riboflavin-fortified soy drink.", "dinner_a": "Mixed vegetable curry with whole-wheat roti and a small bowl of curd.", "dinner_b": "Chicken-and-mushroom curry (cooked through) with whole-wheat roti and a cooked vegetable sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Away from home", "notes": "Today: Shelf-stable milk, sealed fortified drinks, nuts, and freshly prepared hot meals can make an away-from-home day easier. Pack curd, paneer, cheese, cooked eggs, or chicken only when they can be kept properly chilled in an insulated bag with an ice pack.", "breakfast_a": "A sealed shelf-stable pasteurised milk pack, or a sealed fortified soy drink, with banana and almonds.", "breakfast_b": "A hard-boiled egg, whole-grain toast, and banana — eaten at home or transported with a cold pack.", "lunch_a": "A freshly prepared hot vegetable-and-mushroom wrap.", "lunch_b": "A freshly prepared hot chicken-and-spinach wrap.", "nourishment_break_a": "Roasted almonds with fruit.", "nourishment_break_b": "A sealed shelf-stable fortified soy drink, if its label lists riboflavin.", "dinner_a": "Mushroom-and-spinach soup with whole-grain toast.", "dinner_b": "Chicken-and-mushroom soup with whole-grain toast.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "Today: A week spent noticing how milk or fortified plant milk, eggs, mushrooms, spinach, or almonds already carry riboflavin toward your body''s everyday energy and cell function is worth a quick look back. Milk, an egg, a mushroom sabzi, a handful of almonds — riboflavin''s quiet, everyday work.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Which foods this week — milk or fortified plant milk, eggs, mushrooms, spinach, almonds, or fortified grains — were already contributing riboflavin without you realising it?',
   'Next week, we''ll continue exploring another everyday nutrient your body relies on for steady energy and function.')
