-- pregnancy week 37: Niacin (Vitamin B3)
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   37,
   'third',
   NULL,
   'Niacin (Vitamin B3)',
   '"Chicken, dal, and a handful of seeds — niacin fuels the everyday energy your body runs on."',
   'Niacin, or vitamin B3, helps your body convert food into usable energy and supports normal function in hundreds of enzyme systems. ICMR-NIN''s recommendation for a sedentary adult woman is 11 mg per day, with an additional 2 mg per day recommended during pregnancy — bringing the pregnancy figure to about 13 mg per day. The corresponding US recommendation, expressed as niacin equivalents (which include a contribution from dietary tryptophan, an amino acid your body can convert to niacin), is 18 mg NE per day. These reflect different reference systems and are useful background — not numbers you need to calculate meal by meal. If you eat meat, fish, or eggs: Chicken and fish are useful direct niacin sources, and this week uses both at different points, alongside a variety of legumes, whole grains, seeds, mushrooms, and fortified foods. Eggs contain almost no niacin directly — when a meal includes egg, it''s the whole grain, legume, seed, or fortified food alongside it that provides the more meaningful direct niacin contribution, while the egg mainly adds protein and a small tryptophan contribution.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Niacin, or vitamin B3, helps your body convert food into usable energy and supports normal function in hundreds of enzyme systems. ICMR-NIN''s recommendation for a sedentary adult woman is 11 mg per day, with an additional 2 mg per day recommended during pregnancy — bringing the pregnancy figure to about 13 mg per day. The corresponding US recommendation, expressed as niacin equivalents (which include a contribution from dietary tryptophan, an amino acid your body can convert to niacin), is 18 mg NE per day. These reflect different reference systems and are useful background — not numbers you need to calculate meal by meal.", "breakfast_a": "Whole-wheat vegetable uttapam with sunflower-seed chutney.", "breakfast_b": "Whole-wheat vegetable uttapam with sunflower-seed chutney and a fully cooked chicken sukka side.", "lunch_a": "Tuvar (pigeon pea) dal with brown rice and a cooked vegetable sabzi.", "lunch_b": "Tuvar dal with brown rice and a cooked mushroom sabzi.", "nourishment_break_a": "Roasted chana with a piece of fruit.", "nourishment_break_b": "A piece of fruit with pumpkin seeds.", "dinner_a": "Potato-and-green-pea curry with whole-wheat roti and a cooked leafy-green sabzi.", "dinner_b": "Lower-mercury fish curry (cooked through) with whole-wheat roti and the same cooked leafy-green sabzi.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where niacin naturally shows up", "notes": "Niacin appears across both plant and animal foods, though not evenly. Chicken and fish are concentrated direct sources. Legumes, brown rice, whole wheat, seeds, and niacin-fortified cereal add a genuine plant contribution, though usually in smaller amounts per serving than meat or fish. Eggs and most dairy contain very little niacin directly. Getting enough riboflavin, vitamin B6, and iron also matters here, since your body needs these nutrients to convert dietary tryptophan into niacin — one more reason a varied diet, not any single food, is what actually covers this.", "breakfast_a": "Whole-wheat vegetable paratha with a bowl of curd.", "breakfast_b": "Whole-wheat vegetable paratha with a fully cooked egg bhurji.", "lunch_a": "Urad dal with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-urad-dal curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "Peanuts with a piece of fruit.", "nourishment_break_b": "Fortified whole-grain cereal with milk.", "dinner_a": "Cracked-wheat (daliya) vegetable pulao with a cooked leafy-green sabzi.", "dinner_b": "Mushroom-and-cracked-wheat pulao with the same cooked leafy-green sabzi.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "When intake may need more attention", "notes": "Severe niacin deficiency (pellagra) is rare today and mainly affects people with severe undernutrition, alcohol use disorder, or a very restricted diet sustained over a long period. Skin changes, digestive upset, or mood changes can have many possible causes and shouldn''t be self-diagnosed as a vitamin deficiency. If your diet has become very limited, or you have persistent symptoms, mention it to your maternity team rather than guessing.", "breakfast_a": "Grilled vegetable-and-mushroom sandwich with a piece of fruit.", "breakfast_b": "Grilled vegetable-and-mushroom sandwich with a fully cooked egg bhurji, and a piece of fruit.", "lunch_a": "Moth bean (matki) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-moth-bean curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "A small bowl of curd with fruit.", "nourishment_break_b": "A piece of fruit with sunflower seeds.", "dinner_a": "Mixed-vegetable curry with brown rice.", "dinner_b": "Mixed-vegetable-and-green-pea curry with brown rice and a small bowl of curd.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "More isn''t the goal", "notes": "A note on supplements: Niacin naturally present in food is not known to cause harm. High-dose niacin supplements are different. Nicotinic acid supplements at around 30 mg or more may cause flushing, warmth, itching, or tingling. The supplemental upper limit during pregnancy is 30 mg a day for ages 14-18 and 35 mg a day for ages 19 and above, unless a clinician prescribes otherwise. Check before adding a separate niacin or B-complex supplement.", "breakfast_a": "Misal — a cooked (not raw) sprouted-moong curry — with pav.", "breakfast_b": "Misal with pav and a fully cooked egg bhurji on the side.", "lunch_a": "Potato-and-mushroom sabzi with whole-wheat roti.", "lunch_b": "Chicken, potato, and mushroom curry (chicken cooked through) with whole-wheat roti.", "nourishment_break_a": "Fortified whole-grain cereal with milk.", "nourishment_break_b": "A piece of fruit with pumpkin seeds.", "dinner_a": "Whole-wheat vegetable khichdi with a cooked spinach side and a peanut garnish.", "dinner_b": "Whole-wheat vegetable-and-spinach khichdi with a small bowl of curd and a peanut garnish.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "How cooking affects niacin", "notes": "Niacin is more heat-stable than some B vitamins, but it''s still water-soluble, so it can leach into cooking water. Using the water dal or vegetables were cooked in as part of the dish, rather than draining it away, and not overcooking food longer than needed, helps retain more of it.", "breakfast_a": "Bajra (pearl millet) khichdi with a cooked vegetable side.", "breakfast_b": "Bajra khichdi with a cooked vegetable side and a fully cooked egg bhurji.", "lunch_a": "Kulthi (horse gram) curry with brown rice and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-kulthi curry (cooked through) with brown rice and the same cooked vegetable sabzi.", "nourishment_break_a": "Roasted chana with a piece of fruit.", "nourishment_break_b": "A small bowl of curd with fruit.", "dinner_a": "Green-pea-and-mushroom curry with whole-wheat roti.", "dinner_b": "Green-pea-and-mushroom curry with whole-wheat roti and a small bowl of curd.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Away from home", "notes": "Sunflower seeds, pumpkin seeds, roasted chana, and a dry-carried fortified cereal travel easily and don''t need refrigeration. Ordinary milk isn''t shelf-stable once opened — carry the cereal dry and pair it with a fresh pasteurized milk pack bought just before eating, or use an unopened UHT pack. Cooked eggs, chicken, curd, and paneer must stay properly chilled in an insulated bag with an ice pack until eaten.", "breakfast_a": "A dry-carried sealed single-serve fortified cereal portion, eaten with fresh pasteurized milk bought just before eating, and a banana.", "breakfast_b": "The same fortified cereal with fresh pasteurized milk, a banana, and a hard-boiled egg (kept chilled with an ice pack until eaten).", "lunch_a": "A freshly prepared hot whole-wheat vegetable-and-mushroom frankie.", "lunch_b": "A freshly prepared hot whole-wheat chicken-and-vegetable frankie (chicken cooked through).", "nourishment_break_a": "Roasted-chana-and-pumpkin-seed trail mix.", "nourishment_break_b": "A piece of fruit with sunflower seeds.", "dinner_a": "A hot dal-and-vegetable soup with whole-grain toast.", "dinner_b": "A hot mushroom-and-vegetable soup with whole-grain toast and a boiled egg (kept chilled with an ice pack until eaten).", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "A week spent noticing how chicken, fish, legumes, whole grains, and seeds each carry niacin toward your body''s everyday energy needs, in their own different ways, is worth a quick look back. Chicken, dal, and a handful of seeds — niacin''s quiet, everyday work.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did learning that different foods contribute different nutrients change how you think about variety across the week? Eggs can be valuable sources of protein and several nutrients, even though they provide very little niacin directly. No single food needs to do every job.',
   'Next week, we''ll continue exploring another everyday nutrient your body relies on for steady, ordinary function.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 38: Pantothenic Acid (Vitamin B5)
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   38,
   'third',
   NULL,
   'Pantothenic Acid (Vitamin B5)',
   '"Eggs, dal, soy, oats — pantothenic acid, found in almost everything you already eat."',
   'Pantothenic acid, or vitamin B5, helps your body build coenzyme A, a compound your cells need to release energy from food and build essential fats. Its name comes from the Greek word for ''from everywhere,'' since small amounts are present in almost every food. ICMR-NIN sets an Adequate Intake of 5 mg per day for both non-pregnant and pregnant women — the evidence hasn''t been enough to set a formal RDA, so both ICMR-NIN and the US use an Adequate Intake instead. The corresponding US recommendation is a slightly higher 6 mg per day during pregnancy, reflecting a different reference system. These figures are useful background — not numbers you need to calculate meal by meal. If you eat meat, fish, or eggs: Chicken, fish, and eggs all contain a moderate, useful amount of pantothenic acid — unlike last week''s nutrient, egg is a real contributor here, not just a protein add-on. Mushrooms, soy, sunflower seeds, avocado, whole grains, and legumes add a genuine plant contribution too, since pantothenic acid is present in small amounts in nearly every food.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Pantothenic acid, or vitamin B5, helps your body build coenzyme A, a compound your cells need to release energy from food and build essential fats. Its name comes from the Greek word for ''from everywhere,'' since small amounts are present in almost every food. ICMR-NIN sets an Adequate Intake of 5 mg per day for both non-pregnant and pregnant women — the evidence hasn''t been enough to set a formal RDA, so both ICMR-NIN and the US use an Adequate Intake instead. The corresponding US recommendation is a slightly higher 6 mg per day during pregnancy, reflecting a different reference system. These figures are useful background — not numbers you need to calculate meal by meal.", "breakfast_a": "Oats porridge with milk and a sliced banana.", "breakfast_b": "Oats porridge with milk, a sliced banana, and a fully cooked egg bhurji.", "lunch_a": "Rajma (kidney bean) curry with brown rice and a cooked spinach sabzi.", "lunch_b": "Soy chunk (soya bean) and spinach curry with brown rice.", "nourishment_break_a": "Sunflower seeds with a piece of fruit.", "nourishment_break_b": "Roasted chana with a piece of fruit.", "dinner_a": "Mushroom-and-vegetable curry with whole-wheat roti.", "dinner_b": "Sweet-potato-and-vegetable curry with whole-wheat roti.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where pantothenic acid naturally shows up", "notes": "Pantothenic acid gets its name from the Greek word for ''from everywhere,'' since small amounts occur in almost every food. Chicken, fish, and eggs are moderate, useful sources, and mushrooms, soy, sunflower seeds, avocado, whole grains, and legumes add a genuine plant contribution too. Liver is the single most concentrated source, but this series already flagged (Week 28) that pregnancy calls for limiting liver because of its very high vitamin A content, so it isn''t built into this week''s meal options.", "breakfast_a": "Whole-wheat toast with mashed avocado.", "breakfast_b": "Whole-wheat toast with mashed avocado and a fully cooked egg.", "lunch_a": "Masoor dal with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-masoor-dal curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "Roasted chana with a piece of fruit.", "nourishment_break_b": "A piece of fruit with sunflower seeds.", "dinner_a": "Broccoli-and-cauliflower sabzi with whole-wheat roti.", "dinner_b": "Paneer-and-broccoli stir-fry with brown rice.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "When intake may need more attention", "notes": "Pantothenic acid deficiency is extremely rare — small amounts are present in almost every food. The very few documented cases occurred in extreme, controlled conditions, such as historic prisoner-of-war diets or deliberately pantothenic-acid-free experimental diets, not ordinary eating patterns. Numbness or burning in the hands and feet, fatigue, or digestive upset can have many other causes and shouldn''t be self-diagnosed. If you have persistent symptoms, mention them to your maternity team.", "breakfast_a": "Whole-wheat besan (chickpea flour) chilla with a bowl of curd.", "breakfast_b": "Whole-wheat besan chilla with a fully cooked egg bhurji.", "lunch_a": "Whole moong dal with whole-wheat roti and a cooked cauliflower sabzi.", "lunch_b": "Soy chunk and cauliflower curry with whole-wheat roti.", "nourishment_break_a": "A piece of fruit with peanuts.", "nourishment_break_b": "Roasted chana with a piece of fruit.", "dinner_a": "Cabbage-and-carrot sabzi with whole-wheat roti.", "dinner_b": "Mushroom-and-green-pea curry with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "More isn''t the goal", "notes": "No upper limit has been set for pantothenic acid, by either ICMR-NIN or NIH — no toxicity has been reported in humans even at high intakes. Very large supplemental doses (several grams a day) have occasionally caused mild diarrhea and stomach upset, but there''s no established benefit to taking more than your body needs from food and your prenatal. There''s no reason to add a separate pantothenic acid or high-dose B-complex supplement beyond what your maternity team recommends.", "breakfast_a": "Vegetable poha with peanuts.", "breakfast_b": "Vegetable poha with peanuts and a fully cooked egg bhurji.", "lunch_a": "Chana dal with brown rice and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-chana-dal curry (cooked through) with brown rice and the same cooked vegetable sabzi.", "nourishment_break_a": "Roasted chana with a piece of fruit.", "nourishment_break_b": "Sunflower seeds with a piece of fruit.", "dinner_a": "Mixed-vegetable curry with whole-wheat roti.", "dinner_b": "Sweet-potato-and-chickpea curry with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "How cooking affects pantothenic acid", "notes": "Pantothenic acid is fairly stable during ordinary cooking, but because it is water-soluble, some can move into cooking liquid. Milling and heavy food processing can also reduce the amount naturally present. Use dal or vegetable cooking liquid in the finished dish where practical, avoid unnecessarily prolonged boiling, and choose whole or less-refined grains regularly. You do not need to undercook food to preserve this vitamin — pregnancy food safety still comes first.", "breakfast_a": "Vegetable dalia (broken wheat) porridge with milk.", "breakfast_b": "Vegetable dalia porridge with milk and a small sunflower-seed garnish.", "lunch_a": "Lobia (black-eyed pea) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Paneer-and-lobia curry with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "Sunflower seeds with a piece of fruit.", "nourishment_break_b": "Mashed avocado on whole-wheat crackers.", "dinner_a": "Cauliflower-and-green-pea curry with whole-wheat roti.", "dinner_b": "Lower-mercury fish curry (cooked through) with whole-wheat roti and a cooked cauliflower-and-green-pea side.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Away from home", "notes": "Sunflower seeds, roasted chana, and a dry-carried fortified cereal travel easily and don''t need refrigeration. Ordinary milk isn''t shelf-stable once opened — carry the cereal dry and pair it with a fresh pasteurized milk pack bought just before eating, or use an unopened UHT pack. Cooked eggs and chicken must stay properly chilled in an insulated bag with an ice pack if they are being carried rather than purchased freshly prepared.", "breakfast_a": "A dry-carried sealed single-serve fortified cereal portion, eaten with fresh pasteurized milk bought just before eating, and a banana.", "breakfast_b": "The same fortified cereal with fresh pasteurized milk, a banana, and a hard-boiled egg (kept chilled with an ice pack until eaten).", "lunch_a": "A freshly prepared hot whole-wheat vegetable-and-broccoli wrap.", "lunch_b": "A freshly prepared hot whole-wheat chicken-and-vegetable wrap (chicken cooked through).", "nourishment_break_a": "Roasted-chana-and-sunflower-seed trail mix.", "nourishment_break_b": "A piece of fruit with peanuts.", "dinner_a": "A hot dal-and-vegetable soup with whole-grain toast.", "dinner_b": "A hot soy-and-vegetable soup with whole-grain toast.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "A week spent noticing how pantothenic acid, true to its name, showed up in almost everything you ate — eggs, dal, soy, whole grains, sunflower seeds, even your morning oats — is worth a quick look back. Eggs, dal, soy, oats — pantothenic acid, quietly present in almost everything.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
