-- pregnancy week 39: Biotin (Vitamin B7)
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   39,
   'third',
   NULL,
   'Biotin (Vitamin B7)',
   '"Egg, fish, sweet potato and seeds — everyday foods contributing biotin for normal metabolism."',
   'Biotin, or vitamin B7, acts as a helper for enzymes involved in processing fats, carbohydrates, and amino acids. Severe deficiency can affect the skin, hair, and nervous system, but deficiency is rare, and taking extra biotin has not been shown to improve hair, skin, or nails in most people who are already getting enough. ICMR-NIN sets an Adequate Intake of 40 micrograms per day for both non-pregnant and pregnant women — like several nutrients in this series, the evidence hasn''t been enough to set a formal RDA. The corresponding US recommendation is a slightly lower 30 micrograms per day, reflecting a different reference system. These figures are useful background — not numbers you need to calculate meal by meal. If you eat meat, fish, or eggs: Eggs and some fish provide useful amounts of biotin. Raw egg whites contain avidin, a protein that binds biotin and reduces its absorption; cooking denatures avidin. Eggs and fish should also be cooked fully during pregnancy for food safety. Sweet potato, sunflower seeds, almonds, and whole grains add a genuine plant contribution, usually in smaller amounts per serving.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Biotin, or vitamin B7, acts as a helper for enzymes involved in processing fats, carbohydrates, and amino acids. Severe deficiency can affect the skin, hair, and nervous system, but deficiency is rare, and taking extra biotin has not been shown to improve hair, skin, or nails in most people who are already getting enough. ICMR-NIN sets an Adequate Intake of 40 micrograms per day for both non-pregnant and pregnant women — like several nutrients in this series, the evidence hasn''t been enough to set a formal RDA. The corresponding US recommendation is a slightly lower 30 micrograms per day, reflecting a different reference system. These figures are useful background — not numbers you need to calculate meal by meal.", "breakfast_a": "Vegetable poha with a piece of fruit.", "breakfast_b": "Vegetable poha with a fully cooked egg bhurji.", "lunch_a": "Chole (chickpea) curry with brown rice and a cooked vegetable sabzi.", "lunch_b": "Soy-and-spinach curry with brown rice.", "nourishment_break_a": "Almonds with a piece of fruit.", "nourishment_break_b": "A piece of fruit with a spoonful of peanut butter.", "dinner_a": "Seasonal-vegetable curry with whole-wheat roti.", "dinner_b": "Lower-mercury fish curry (cooked through) with whole-wheat roti and a cooked seasonal-vegetable side.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where biotin naturally shows up", "notes": "Eggs and some fish provide useful amounts of biotin. Raw egg whites contain avidin, a protein that binds biotin and reduces its absorption; cooking denatures avidin. Eggs and fish should also be cooked fully during pregnancy for food safety. Sweet potato, sunflower seeds, almonds, and whole grains add a genuine plant contribution, though usually smaller amounts per serving. Liver is the single most concentrated source, but this series already flagged (Week 28) that pregnancy calls for limiting liver because of its very high vitamin A content, so it isn''t built into this week''s meal options.", "breakfast_a": "Roasted sweet-potato wedges with a bowl of curd.", "breakfast_b": "Besan (chickpea flour) chilla with a sunflower-seed chutney.", "lunch_a": "Kala chana (black chickpea) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-kala-chana curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "Roasted chana with a piece of fruit.", "nourishment_break_b": "A small bowl of curd with fruit.", "dinner_a": "Mixed-vegetable curry with brown rice.", "dinner_b": "Paneer-and-mixed-vegetable curry with brown rice.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "A pregnancy-specific note", "notes": "Research has found marginal changes in biotin status in some pregnant women despite normal dietary intake. Researchers are still studying what these changes mean for maternal or fetal health. This finding does not establish that routine biotin testing or extra supplementation is beneficial. Continue eating a varied diet and discuss any supplement with your maternity team.", "breakfast_a": "Whole-wheat vegetable paratha with a bowl of curd.", "breakfast_b": "Whole-wheat vegetable paratha with a fully cooked egg bhurji.", "lunch_a": "Safed vatana (white pea) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-safed-vatana curry (cooked through) with whole-wheat roti and the same cooked vegetable sabzi.", "nourishment_break_a": "Sunflower seeds with a piece of fruit.", "nourishment_break_b": "Sweet-potato chaat.", "dinner_a": "Broccoli-and-vegetable stir-fry with brown rice.", "dinner_b": "Paneer-and-broccoli stir-fry with brown rice.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "When intake may need more attention", "notes": "True biotin deficiency is rare in people eating an ordinary, varied diet — it''s mostly linked to a rare inherited condition called biotinidase deficiency, which newborns are screened for in many countries, or to diets that are severely restricted for a long time. Hair thinning, skin rashes, or fatigue can have many other causes and shouldn''t be self-diagnosed as a biotin problem. If you have persistent symptoms, mention them to your maternity team rather than guessing.", "breakfast_a": "Vegetable dalia (broken wheat) porridge with milk.", "breakfast_b": "Whole-grain toast with peanut butter and a banana.", "lunch_a": "Potato-and-green-pea sabzi with whole-wheat roti.", "lunch_b": "Chicken, potato, and green-pea curry (chicken cooked through) with whole-wheat roti.", "nourishment_break_a": "Roasted chana with a piece of fruit.", "nourishment_break_b": "A piece of fruit with almonds.", "dinner_a": "Cauliflower-and-vegetable curry with whole-wheat roti.", "dinner_b": "Cauliflower-and-soy-chunk curry with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "More isn''t the goal", "notes": "High-dose biotin supplements, including some products marketed for hair, skin, and nails, can interfere with certain blood tests and produce falsely high or falsely low results. These may include some thyroid tests and tests used to investigate heart problems. Tell your maternity team and the laboratory about every supplement you take before blood testing. Do not stop a prescribed supplement on your own; follow the timing instructions given by your care team or laboratory. If this applies to you (thyroid): If you have a thyroid condition or are being monitored for one, and you take a biotin supplement (including many hair, skin, or nail products), tell your doctor or lab before any thyroid function test. The interference can either imitate a thyroid problem or conceal one, depending on the test. Your care team may ask you to pause the supplement for a few days beforehand.", "breakfast_a": "Vegetable upma with a piece of fruit.", "breakfast_b": "Vegetable upma with a fully cooked egg bhurji.", "lunch_a": "Palak (spinach) paneer with whole-wheat roti.", "lunch_b": "Soy chunk (soya bean) and spinach curry with whole-wheat roti.", "nourishment_break_a": "Peanut butter on whole-grain crackers.", "nourishment_break_b": "Roasted chana with a piece of fruit.", "dinner_a": "Mushroom-and-vegetable curry with whole-wheat roti.", "dinner_b": "Lower-mercury fish curry (cooked through) with whole-wheat roti and a cooked mushroom side.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Away from home", "notes": "Almonds, sunflower seeds, roasted chana, and a boiled egg all travel well and don''t need much preparation. Cooked eggs and chicken must stay properly chilled in an insulated bag with an ice pack if they are being carried rather than purchased freshly prepared.", "breakfast_a": "Whole-grain toast with peanut or almond butter and a banana.", "breakfast_b": "A hard-boiled egg, whole-grain toast, and a banana (egg kept chilled with an ice pack until eaten).", "lunch_a": "A freshly prepared hot whole-wheat vegetable-and-sweet-potato wrap.", "lunch_b": "A freshly prepared hot whole-wheat chicken-and-vegetable wrap (chicken cooked through).", "nourishment_break_a": "Roasted-chana-and-almond trail mix.", "nourishment_break_b": "A piece of fruit with sunflower seeds.", "dinner_a": "A hot dal-and-vegetable soup with whole-grain toast.", "dinner_b": "A hot soy-and-vegetable soup with whole-grain toast.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "A week spent noticing how egg, fish, sweet potato, and a handful of nuts and seeds each carry biotin toward your body''s normal metabolism is worth a quick look back. Egg, fish, sweet potato, a handful of nuts — biotin''s quiet, everyday work.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did this week change how you think about supplements marketed for hair, skin, or nails? Which ordinary foods helped you see that biotin can come from a varied diet without adding a separate high-dose product?',
   'Next week, we''ll continue exploring another everyday nutrient your body relies on for steady, ordinary function.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;

-- pregnancy week 40: Phosphorus
insert into nourish_week_content
  (stage, week_number, trimester, phase_label, theme_title, mantra,
   why_it_matters, condition_notes, meat_fish_eggs_note, using_meals_note,
   days, reflection, looking_ahead)
values
  ('pregnancy',
   40,
   'third',
   NULL,
   'Phosphorus',
   '"Present in almost everything you eat — a mineral that rarely needs seeking out."',
   'Phosphorus works closely with calcium in bones and teeth. About 85% of the phosphorus in your body is stored there, while the remainder supports cell membranes, energy metabolism, and other essential functions. The US pregnancy RDA is 1,250 mg per day for ages 14-18 and 700 mg per day for ages 19 and above. These figures are useful background, not amounts you need to calculate meal by meal. If you eat meat, fish, or eggs: Phosphorus doesn''t split sharply along a meat-or-plant line the way some nutrients in this series do. Dairy, meat, fish, and eggs all contain it naturally, but so do dal, legumes, nuts, seeds, and whole grains — in a genuinely varied Indian diet, phosphorus tends to arrive alongside whichever protein source you''re already eating, whether or not it includes animal foods. A gentle note for this week: Your appetite and routine may feel less predictable close to birth. Choose smaller portions, repeat familiar foods if that feels easier, and eat according to comfort rather than trying to complete the chart perfectly. If labour begins or you are scheduled for induction or a procedure, follow the eating and drinking instructions from your maternity team or hospital.',
   NULL,
   NULL,
   NULL,
   '[{"day_number": 1, "title": "Anchor", "notes": "Phosphorus works closely with calcium in bones and teeth. About 85% of the phosphorus in your body is stored there, while the remainder supports cell membranes, energy metabolism, and other essential functions. The US pregnancy RDA is 1,250 mg per day for ages 14-18 and 700 mg per day for ages 19 and above. These figures are useful background, not amounts you need to calculate meal by meal.", "breakfast_a": "Moong dal chilla with a bowl of curd.", "breakfast_b": "Moong dal chilla with a fully cooked egg bhurji.", "lunch_a": "Rajma (kidney bean) curry with brown rice and a cooked vegetable sabzi.", "lunch_b": "Chicken-and-rajma curry (cooked through) with brown rice and the same vegetable sabzi.", "nourishment_break_a": "A handful of walnuts with a banana.", "nourishment_break_b": "Roasted peanuts with a piece of fruit.", "dinner_a": "Lauki (bottle gourd) and chana dal curry with whole-wheat roti.", "dinner_b": "Paneer-and-lauki curry with whole-wheat roti.", "still_hungry": "A piece of fruit."}, {"day_number": 2, "title": "Where phosphorus naturally shows up", "notes": "Phosphorus occurs naturally in dairy, meat, fish, eggs, legumes, nuts, seeds, and whole grains — it''s genuinely difficult to eat a normal, varied diet and not get enough. Unlike several nutrients in this series, there''s no need to seek out a particular food group; phosphorus travels along with the protein already on an ordinary plate.", "breakfast_a": "Vegetable-and-moong-dal paratha with a mint-coriander chutney.", "breakfast_b": "Moong dal cheela with a tomato-onion chutney.", "lunch_a": "Chana dal with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Fully cooked egg-and-vegetable curry with whole-wheat roti.", "nourishment_break_a": "A handful of walnuts with a piece of fruit.", "nourishment_break_b": "Roasted chana with a few dates.", "dinner_a": "Mixed-dal khichdi with a cooked vegetable side.", "dinner_b": "Lower-mercury fish curry (cooked through) with brown rice and a cooked vegetable side.", "still_hungry": "A familiar snack."}, {"day_number": 3, "title": "A closer look at how much you actually need", "notes": "True dietary phosphorus deficiency is rare — it''s mostly seen with excessive urinary losses from rare inherited conditions or certain tumors, or in severe refeeding situations after prolonged starvation, not from an ordinary diet. Pregnancy does not increase the US phosphorus RDA above the non-pregnant amount for the corresponding age group. The body adapts mineral metabolism during pregnancy, and ordinary varied eating generally remains sufficient. There is generally no need to increase phosphorus deliberately during pregnancy unless your maternity team identifies a specific medical reason.", "breakfast_a": "Idli with sambar and a coconut chutney.", "breakfast_b": "Idli with a fully cooked egg curry.", "lunch_a": "Soy chunk (soya bean) and vegetable curry with brown rice.", "lunch_b": "Chicken-and-vegetable curry (cooked through) with brown rice.", "nourishment_break_a": "Roasted chana with a piece of fruit.", "nourishment_break_b": "A small bowl of curd with fruit.", "dinner_a": "Whole-wheat vegetable pulao with a cucumber-tomato salad.", "dinner_b": "Green-pea-and-mushroom pulao with a cucumber-tomato salad.", "still_hungry": "A familiar snack."}, {"day_number": 4, "title": "Quality of source matters", "notes": "The bigger consideration for most people isn''t whether they''re getting enough phosphorus — it''s how much comes from packaged and processed sources rather than whole foods. Phosphate additives in packaged foods (used in colas, packaged deli meats, processed cheese, instant noodles, and many fast foods) are often more readily absorbed than phosphorus naturally bound within whole foods, especially plant foods, and they can also increase total phosphorus intake without being obvious from the front of the package. Some research is looking at whether a diet heavy in these additives affects long-term bone health, though this is still being studied. Choosing freshly prepared food over packaged or processed options most of the time is a reasonable, simple way to keep this in the healthier direction — not a reason to worry over any single meal.", "breakfast_a": "Vegetable upma with a piece of fruit.", "breakfast_b": "Besan (chickpea flour) chilla with a mint-coriander chutney.", "lunch_a": "A freshly prepared hot whole-wheat paneer-and-vegetable wrap.", "lunch_b": "A freshly prepared hot whole-wheat chicken-and-vegetable wrap (chicken cooked through).", "nourishment_break_a": "A glass of milk with a handful of almonds.", "nourishment_break_b": "Peanut chikki (jaggery-peanut brittle), a small piece.", "dinner_a": "Palak (spinach) dal with whole-wheat roti.", "dinner_b": "Palak-and-soy-chunk curry with whole-wheat roti.", "still_hungry": "A familiar snack."}, {"day_number": 5, "title": "When kidney function changes the picture", "notes": "For most people, how much phosphorus you eat isn''t something to track — healthy kidneys filter out what the body doesn''t need. This changes for someone with significantly reduced kidney function, where the kidneys can''t clear excess phosphate as efficiently, and it can build up in the blood. If you have a kidney condition, or your maternity team has ever mentioned watching your kidney function, follow their specific dietary guidance rather than general advice like this. Do not add a separate phosphorus supplement or use a sodium-phosphate laxative beyond the labelled or prescribed dose. If you use antacids regularly, mention them to your maternity team, since different products can affect mineral absorption differently — some (containing aluminum hydroxide or calcium carbonate) can bind phosphorus and reduce its absorption with prolonged use. The meal choices below are for the general pregnancy plan; they are not a kidney-disease meal prescription.", "breakfast_a": "Dalia (broken wheat) porridge with mashed banana and a small nut garnish.", "breakfast_b": "Vegetable dalia porridge with a fully cooked egg bhurji on the side.", "lunch_a": "Rajma (kidney bean) curry with whole-wheat roti and a cooked vegetable sabzi.", "lunch_b": "Mixed-dal-and-vegetable khichdi with a cooked sabzi.", "nourishment_break_a": "Roasted peanuts with a piece of fruit.", "nourishment_break_b": "Roasted foxnuts (makhana) with a piece of fruit.", "dinner_a": "Mushroom-and-vegetable curry with brown rice.", "dinner_b": "Lower-mercury fish curry (cooked through) with brown rice and a cooked mushroom side.", "still_hungry": "A familiar snack."}, {"day_number": 6, "title": "Away from home", "notes": "Roasted nuts and chana travel easily without refrigeration. Carry cooked eggs, chicken, and curd in an insulated bag with an ice pack until eaten.", "breakfast_a": "Whole-grain toast with peanut butter and a banana.", "breakfast_b": "A hard-boiled egg, whole-grain toast, and a banana (egg kept chilled with an ice pack until eaten).", "lunch_a": "A freshly prepared hot whole-wheat chana-and-vegetable wrap.", "lunch_b": "A freshly prepared hot whole-wheat chicken-tikka-and-vegetable wrap (chicken cooked through).", "nourishment_break_a": "A small box of curd with fruit.", "nourishment_break_b": "Roasted-chana-and-almond trail mix.", "dinner_a": "A hot dal-and-vegetable soup with whole-grain toast.", "dinner_b": "A hot soy-and-vegetable soup with whole-grain toast.", "still_hungry": "A familiar snack."}, {"day_number": 7, "title": "Reflection", "notes": "A week spent noticing how naturally phosphorus shows up across an ordinary plate — dairy, dal, egg, fish, nuts, whole grains — without needing a single special food is worth a quick look back. Phosphorus is already there in almost everything you eat — this week was about noticing it, not chasing it.", "breakfast_a": "Whichever breakfast felt best this week — worth repeating.", "breakfast_b": null, "lunch_a": "Whichever lunch from this week you''d want again.", "lunch_b": null, "nourishment_break_a": "Whichever snack worked best for you this week.", "nourishment_break_b": null, "dinner_a": "Whichever dinner from this week you''d want again.", "dinner_b": null, "still_hungry": "A familiar snack, whatever suits you."}]'::jsonb,
   'Did anything this week surprise you about how many ordinary foods already contain phosphorus? Did thinking about packaged versus freshly prepared food change how you look at your usual snacks?',
   'Whether your baby arrives this week or later, nourishment does not need to be perfect. Follow your maternity team''s guidance around labour and birth. When the time is right, Nourish will continue with gentle support for recovery, hydration, and the early postpartum period.')
on conflict (stage, week_number) do update set
  trimester = excluded.trimester,
  phase_label = excluded.phase_label,
  theme_title = excluded.theme_title,
  mantra = excluded.mantra,
  why_it_matters = excluded.why_it_matters,
  condition_notes = excluded.condition_notes,
  meat_fish_eggs_note = excluded.meat_fish_eggs_note,
  using_meals_note = excluded.using_meals_note,
  days = excluded.days,
  reflection = excluded.reflection,
  looking_ahead = excluded.looking_ahead;
